```java
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.List;
import java.util.Map;
import java.util.UUID;

public class ModelSimulation extends Simulation {

  private static final String[] ITERATION_KEYS = {
      "csrf",
      "csrfFormActionHidden",
      "csrfFormHidden",
      "csrfHidden",
      "csrfAny",
      "newCsrf",
      "loginStatus",
      "loginLocation",
      "selectedPair",
      "productIdJson",
      "variantIdJson",
      "cartIdObj",
      "cartId",
      "cartIdJson",
      "cartEtag",
      "newEtag",
      "patchStatus",
      "patchReturnedEtag",
      "orderId"
  };

  private static String resolveBaseUrl() {
    String env = System.getenv("BASE_URL");
    return (env == null || env.isBlank()) ? "http://127.0.0.1:8000" : env.trim();
  }

  private static String firstNonBlank(String... values) {
    for (String v : values) {
      if (v != null && !v.isBlank()) {
        return v;
      }
    }
    return "";
  }

  private static String firstNonBlankFromList(List<String> values) {
    if (values == null) {
      return "";
    }
    for (String v : values) {
      if (v != null && !v.isBlank()) {
        return v;
      }
    }
    return "";
  }

  private static boolean hasNonBlank(Session session, String key) {
    String val = session.getString(key);
    return val != null && !val.isBlank();
  }

  private static Session updateCsrfIfPresent(Session session) {
    String newCsrf = session.getString("newCsrf");
    Session updated = session.remove("newCsrf");
    if (newCsrf != null && !newCsrf.isBlank()) {
      return updated.set("csrf", newCsrf);
    }
    return updated;
  }

  private static Session updateEtagIfPresent(Session session) {
    String newEtag = session.getString("newEtag");
    Session updated = session.remove("newEtag");
    if (newEtag != null && !newEtag.isBlank()) {
      return updated.set("cartEtag", newEtag);
    }
    return updated;
  }

  private static String findInStockVariant(List<Object> products) {
    if (products == null) {
      return "";
    }
    for (Object pObj : products) {
      if (!(pObj instanceof Map)) {
        continue;
      }
      Map<?, ?> pMap = (Map<?, ?>) pObj;
      Object prodId = pMap.get("id");
      if (prodId == null) {
        continue;
      }
      Object prodInStock = pMap.get("in_stock");
      if (prodInStock != null && !isTruthy(prodInStock)) {
        continue;
      }
      Object variantsObj = pMap.get("variants");
      if (!(variantsObj instanceof List)) {
        continue;
      }
      List<?> variants = (List<?>) variantsObj;
      for (Object vObj : variants) {
        if (!(vObj instanceof Map)) {
          continue;
        }
        Map<?, ?> vMap = (Map<?, ?>) vObj;
        Object varId = vMap.get("id");
        Object varInStock = vMap.get("in_stock");
        if (varId != null && isTruthy(varInStock)) {
          return toJsonValue(prodId) + "\n" + toJsonValue(varId);
        }
      }
    }
    return "";
  }

  private static boolean isTruthy(Object val) {
    if (val instanceof Boolean) {
      return (Boolean) val;
    }
    if (val instanceof Number) {
      return ((Number) val).intValue() != 0;
    }
    return "true".equalsIgnoreCase(String.valueOf(val));
  }

  private static String toJsonValue(Object value) {
    if (value == null) {
      return "null";
    }
    if (value instanceof Number || value instanceof Boolean) {
      return value.toString();
    }
    return "\"" + escapeJson(value.toString()) + "\"";
  }

  private static String escapeJson(String s) {
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      switch (c) {
        case '\\':
          sb.append("\\\\");
          break;
        case '"':
          sb.append("\\\"");
          break;
        case '\b':
          sb.append("\\b");
          break;
        case '\f':
          sb.append("\\f");
          break;
        case '\n':
          sb.append("\\n");
          break;
        case '\r':
          sb.append("\\r");
          break;
        case '\t':
          sb.append("\\t");
          break;
        default:
          if (c < 0x20) {
            sb.append(String.format("\\u%04x", (int) c));
          } else {
            sb.append(c);
          }
          break;
      }
    }
    return sb.toString();
  }

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(resolveBaseUrl())
      .disableFollowRedirect()
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

  private final ChainBuilder journey = exec(flushCookieJar())
      .exec(session -> {
        Session cleaned = session;
        for (String key : ITERATION_KEYS) {
          cleaned = cleaned.remove(key);
        }
        long uid = cleaned.userId();
        int iter = cleaned.getInt("iter");
        String username = "bench-" + (((uid - 1) % 16) + 1);
        return cleaned
            .set("username", username)
            .set("idempotencyKey", "order-" + uid + "-" + iter + "-" + UUID.randomUUID());
      })
      .exec(
          http("Get Login Form")
              .get("/v2/login-form")
              .check(status().is(200))
              .check(
                  css("form[action*=login] input[type=hidden][name=csrf]", "value")
                      .findAll()
                      .transform(ModelSimulation::firstNonBlankFromList)
                      .optional()
                      .saveAs("csrfFormActionHidden")
              )
              .check(
                  css("form input[type=hidden][name=csrf]", "value")
                      .findAll()
                      .transform(ModelSimulation::firstNonBlankFromList)
                      .optional()
                      .saveAs("csrfFormHidden")
              )
              .check(
                  css("input[type=hidden][name=csrf]", "value")
                      .findAll()
                      .transform(ModelSimulation::firstNonBlankFromList)
                      .optional()
                      .saveAs("csrfHidden")
              )
              .check(
                  css("input[name=csrf]", "value")
                      .findAll()
                      .transform(ModelSimulation::firstNonBlankFromList)
                      .not("")
                      .saveAs("csrfAny")
              )
      )
      .exec(session -> {
        String csrf = firstNonBlank(
            session.getString("csrfFormActionHidden"),
            session.getString("csrfFormHidden"),
            session.getString("csrfHidden"),
            session.getString("csrfAny")
        );
        return session
            .remove("csrfFormActionHidden")
            .remove("csrfFormHidden")
            .remove("csrfHidden")
            .remove("csrfAny")
            .set("csrf", csrf);
      })
      .exec(
          http("Login")
              .post("/v2/login")
              .asJson()
              .body(StringBody(session ->
                  "{\"username\":" + toJsonValue(session.getString("username"))
                      + ",\"password\":\"bench\""
                      + ",\"csrf\":" + toJsonValue(session.getString("csrf"))
                      + "}"
              ))
              .check(status().in(200, 302))
              .check(status().saveAs("loginStatus"))
              .check(header("Location").optional().saveAs("loginLocation"))
              .check(jmesPath("csrf").optional().saveAs("newCsrf"))
      )
      .exec(ModelSimulation::updateCsrfIfPresent)
      .doIf(session -> Integer.valueOf(302).equals(session.get("loginStatus"))).then(
          exec(
              http("Login Redirect")
                  .get("#{loginLocation}")
                  .check(status().is(200))
                  .check(jmesPath("csrf").optional().saveAs("newCsrf"))
          )
          .exec(ModelSimulation::updateCsrfIfPresent)
      )
      .exec(
          http("Get Catalog")
              .get("/v2/catalog")
              .check(status().is(200))
              .check(
                  jmesPath("data.products")
                      .ofList()
                      .transform(ModelSimulation::findInStockVariant)
                      .not("")
                      .saveAs("selectedPair")
              )
      )
      .exec(session -> {
