class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inert_depth = 0
        self.forms = []
        self.current_form = None
        self.orphan_inputs = []

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        if tag_lower in ("template", "noscript"):
            self.inert_depth += 1
            return
        if self.inert_depth > 0:
            return

        attr_map = {}
        for key, value in attrs:
            if key is None:
                continue
            key_lower = key.lower()
            if key_lower not in attr_map:
                attr_map[key_lower] = value

        if tag_lower == "form":
            self.current_form = {"attrs": attr_map, "inputs": []}
            self.forms.append(self.current_form)
        elif tag_lower == "input":
            if self.current_form is not None:
                self.current_form["inputs"].append(attr_map)
            else:
                self.orphan_inputs.append(attr_map)

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        if tag_lower in ("template", "noscript"):
            if self.inert_depth > 0:
                self.inert_depth -= 1
            return
        if tag_lower == "form":
            self.current_form = None


def extract_login_csrf(html_text):
    parser = LoginFormParser()
    parser.feed(html_text or "")
    parser.close()

    def score_input(inp, form_id=None):
        if inp.get("name") != "csrf":
            return None
        val = inp.get("value")
        if val is None or val == "":
            return None
        if "disabled" in inp:
            return None

        score = 0
        inp_type = (inp.get("type") or "").strip().lower()
        if inp_type == "hidden":
            score += 100
        elif inp_type == "":
            score += 10
        else:
            score -= 50

        meta = " ".join(
            str(inp.get(k) or "")
            for k in ("id", "class", "data-role", "data-kind", "data-decoy")
        ).lower()
        if any(word in meta for word in ("decoy", "fake", "dummy", "honeypot")):
            score -= 40

        if "hidden" in inp or (inp.get("aria-hidden") or "").lower() == "true":
            score -= 5

        target_form = inp.get("form")
        if target_form and form_id is not None and target_form != form_id:
            score -= 200

        return score

    forms_by_id = {}
    scored_forms = []
    for form in parser.forms:
        f_attrs = form["attrs"]
        f_inputs = form["inputs"]
        f_score = 0

        action = (f_attrs.get("action") or "").strip().lower()
        method = (f_attrs.get("method") or "").strip().lower()
        style = (f_attrs.get("style") or "").replace(" ", "").lower()

        if "login" in action:
            f_score += 200
        elif action:
            f_score -= 100

        if method == "post":
            f_score += 20
        elif method == "get":
            f_score -= 40

        if "hidden" in f_attrs or "display:none" in style:
            f_score -= 100

        f_meta = " ".join(
            str(f_attrs.get(k) or "")
            for k in ("id", "class", "name", "data-role")
        ).lower()
        if any(word in f_meta for word in ("decoy", "fake", "dummy", "honeypot")):
            f_score -= 80

        has_user = any(
            (i.get("name") or "").lower() in ("username", "user", "login", "email")
            for i in f_inputs
        )
        has_pass = any(
            (i.get("type") or "").lower() == "password"
            or (i.get("name") or "").lower() == "password"
            for i in f_inputs
        )
        if has_user:
            f_score += 60
        if has_pass:
            f_score += 60

        form_id = f_attrs.get("id")
        if form_id:
            forms_by_id[form_id] = f_score
        scored_forms.append((f_score, form_id, f_inputs))

    best = None
    for f_score, form_id, f_inputs in scored_forms:
        for inp in f_inputs:
            iscore = score_input(inp, form_id=form_id)
            if iscore is not None:
                total = f_score + iscore
                if best is None or total > best[0]:
                    best = (total, inp["value"])

    for inp in parser.orphan_inputs:
        target_form = inp.get("form")
        if target_form and target_form in forms_by_id:
            iscore = score_input(inp, form_id=target_form)
            if iscore is not None:
                total = forms_by_id[target_form] + iscore
                if best is None or total > best[0]:
                    best = (total, inp["value"])

    if best is None:
        for inp in parser.orphan_inputs:
            iscore = score_input(inp, form_id=None)
            if iscore is not None:
                if best is None or iscore > best[0]:
                    best = (iscore, inp["value"])

    return best[1] if best is not None else None


def find_in_stock_variant(body):
    if not isinstance(body, dict):
        return None
    container = body.get("data") if isinstance(body.get("data"), dict) else body

    products = container.get("products")
    if isinstance(products, list):
        for prod in products:
            if not isinstance(prod, dict):
                continue
            pid = prod.get("id")
            if pid is None:
                continue
            for var in prod.get("variants") or []:
                if (
                    isinstance(var, dict)
                    and var.get("in_stock") is True
                    and var.get("id") is not None
                ):
                    return pid, var["id"]

    single = container.get("product")
    if isinstance(single, dict) and single.get("id") is not None:
        pid = single["id"]
        for var in single.get("variants") or []:
            if (
                isinstance(var, dict)
                and var.get("in_stock") is True
                and var.get("id") is not None
            ):
                return pid, var["id"]

    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0.05)

    _spawned_users = 0
    _finished_users = 0

    def on_start(self):
        idx = ShopUser._spawned_users
        ShopUser._spawned_users += 1
        self.user_idx = idx
        self._counted_finished = False
        self.iterations_done = 0
        self.csrf = None

        if idx >= TARGET_USERS:
            self._counted_finished = True
            raise StopUser()

        self.username = f"bench-{(idx % 16) + 1}"
        self.password = "bench"

    def on_stop(self):
        self._mark_finished()

    def _mark_finished(self):
        if not self._counted_finished and self.user_idx < TARGET_USERS:
            self._counted_finished = True
            ShopUser._finished_users += 1

    def _parse_json(self, resp):
        try:
            return resp.json()
        except ValueError:
            return None

    def _update_csrf(self, data):
        if isinstance(data, dict):
            new_csrf = data.get("csrf")
            if new_csrf:
                self.csrf = new_csrf

    def _login(self):
        self.client.cookies.clear()
        self.csrf = None

        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET /v2/login-form returned {resp.status_code}")
                return False
            form_csrf = extract_login_csrf(resp.text)
            if not form_csrf:
                resp.failure("Could not extract hidden CSRF input from /v2/login-form")
                return False
            resp.success()

        redirect_url = None
        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": form_csrf,
            },
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 302:
                redirect_url = resp.headers.get("Location")
                if not redirect_url:
                    resp.failure("POST /v2/login 302 missing Location header")
                    return False
                resp.success()
            elif resp.status_code == 200:
                data = self._parse_json(resp)
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure(f"POST /v2/login missing csrf: {resp.text[:200]}")
                    return False
                self._update_csrf(data)
                resp.success()
            else:
                resp.failure(
                    f"POST /v2/login returned {resp.status_code}: {resp.text[:200]}"
                )
                return False

        if redirect_url:
            if not redirect_url.startswith("/") and not redirect_url.startswith("http"):
                redirect_url = "/" + redirect_url
            with self.client.get(
                redirect_url,
                allow_redirects=False,
                name="/v2/login/redirect",
                catch_response=True,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"Login redirect returned {resp.status_code}")
                    return False
                data = self._parse_json(resp)
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure(f"Login redirect missing csrf: {resp.text[:200]}")
                    return False
                self._update_csrf(data)
                resp.success()

        return bool(self.csrf)

    def _recover_auth(self, error_code, cart_id=None):
        recovered = False
        if error_code == "expired" and self.csrf:
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    data = self._parse_json(resp)
                    self._update_csrf(data)
                    resp.success()
                    recovered = bool(self.csrf)
                else:
                    resp.failure(f"Session renew failed: {resp.status_code}")

        if not recovered:
            recovered = self._login()

        if not recovered:
            return False, None

        new_etag = None
        if cart_id is not None:
            with self.client.post(
                f"/v2/carts/{cart_id}/recover",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                name="/v2/carts/{id}/recover",
                catch_response=True,
            ) as resp:
                if resp.status_code in (200, 204):
                    if resp.text:
                        self._update_csrf(self._parse_json(resp))
                    new_etag = resp.headers.get("ETag")
                    resp.success()
                else:
                    resp.failure(f"Cart recover failed: {resp.status_code}")
                    return False, None

        return True, new_etag

    def _select_catalog_item(self):
        url = "/v2/catalog"
        pages = 0
        auth_recovered = False

        while url and pages <= 3:
            req_name = "/v2/catalog" if pages == 0 else "/v2/catalog/page"
            next_url = None
            retry_same = False

            with self.client.get(url, name=req_name, catch_response=True) as resp:
                if resp.status_code == 401 and not auth_recovered:
                    err = (self._parse_json(resp) or {}).get("error")
                    if err in ("expired", "session"):
                        resp.success()
                        retry_same = err
                    else:
                        resp.failure(f"Catalog unauthorized: {resp.text[:200]}")
                        return None
                elif resp.status_code != 200:
                    resp.failure(f"Catalog failed with {resp.status_code}")
                    return None
                else:
                    data = self._parse_json(resp)
                    item = find_in_stock_variant(data)
                    if item is not None:
                        resp.success()
                        return item
                    if isinstance(data, dict):
                        next_url = data.get("next")
                    if next_url and pages < 3:
                        resp.success()
                    else:
                        resp.failure("No in-stock variant found in catalog")
                        return None

            if retry_same:
                auth_recovered = True
                ok, _ = self._recover_auth(retry_same, cart_id=None)
                if not ok:
                    return None
                continue

            if not next_url:
                break
            if not next_url.startswith("/") and not next_url.startswith("http"):
                next_url = "/" + next_url
            url = next_url
            pages += 1

        return None

    def _create_cart(self, product_id, variant_id):
        auth_recovered = False
        while True:
            retry_err = None
            with self.client.post(
                "/v2/carts",
                json={"product_id": product_id, "variant_id": variant_id},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
            ) as resp:
                if resp.status_code == 401 and not auth_recovered:
                    err = (self._parse_json(resp) or {}).get("error")
                    if err in ("expired", "session"):
                        resp.success()
                        retry_err = err
                    else:
                        resp.failure(f"Create cart 401: {resp.text[:200]}")
                        return None, None
                elif resp.status_code != 201:
                    resp.failure(
                        f"Create cart failed with {resp.status_code}: {resp.text[:200]}"
                    )
                    return None, None
                else:
                    data = self._parse_json(resp)
                    if not isinstance(data, dict) or not data.get("id"):
                        resp.failure(f"Create cart missing id: {resp.text[:200]}")
                        return None, None
                    self._update_csrf(data)
                    etag = resp.headers.get("ETag")
                    resp.success()
                    return data["id"], etag

            if retry_err:
                auth_recovered = True
                ok, _ = self._recover_auth(retry_err, cart_id=None)
                if not ok:
                    return None, None

    def _fetch_cart_etag(self, cart_id):
        with self.client.get(
            f"/v2/carts/{cart_id}",
            name="/v2/carts/{id}",
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET cart failed with {resp.status_code}")
                return None
            etag = resp.headers.get("ETag")
            resp.success()
            return etag

    def _patch_cart(self, cart_id, etag, quantity=2):
        if not etag:
            etag = self._fetch_cart_etag(cart_id)
            if not etag:
                return False, None

        retried_412 = False
        auth_recovered = False
        payload = {"quantity": quantity}

        while True:
            retry_err = None
            need_412_retry = False
            headers = {"X-CSRF-Token": self.csrf, "If-Match": etag}

            with self.client.patch(
                f"/v2/carts/{cart_id}",
                json=payload,
                headers=headers,
                name="/v2/carts/{id}",
                catch_response=True,
            ) as resp:
                if resp.status_code == 401 and not auth_recovered:
                    err = (self._parse_json(resp) or {}).get("error")
                    if err in ("expired", "session"):
                        resp.success()
                        retry_err = err
                    else:
                        resp.failure(f"PATCH cart 401: {resp.text[:200]}")
                        return False, etag
                elif resp.status_code == 412 and not retried_412:
                    resp.success()
                    need_412_retry = True
                elif resp.status_code in (200, 204):
                    if resp.text:
                        self._update_csrf(self._parse_json(resp))
                    etag = resp.headers.get("ETag") or etag
                    resp.success()
                    return True, etag
                else:
                    resp.failure(
                        f"PATCH cart failed with {resp.status_code}: {resp.text[:200]}"
                    )
                    return False, etag

            if retry_err:
                auth_recovered = True
                ok, recovered_etag = self._recover_auth(retry_err, cart_id=cart_id)
                if not ok:
                    return False, etag
                if recovered_etag:
                    etag = recovered_etag
                continue

            if need_412_retry:
                retried_412 = True
                fresh_etag = self._fetch_cart_etag(cart_id)
                if not fresh_etag:
                    return False, etag
                etag = fresh_etag

    def _submit_order(self, cart_id, etag):
        idem_key = f"{self.username}-{cart_id}-{uuid.uuid4().hex}"
        retried_412 = False
        auth_recovered = False

        while True:
            retry_err = None
            need_412_retry = False
            headers = {
                "X-CSRF-Token": self.csrf,
                "Idempotency-Key": idem_key,
            }
            if etag:
                headers["If-Match"] = etag

            with self.client.post(
                "/v2/orders",
                json={"cart_id": cart_id},
                headers=headers,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401 and not auth_recovered:
                    err = (self._parse_json(resp) or {}).get("error")
                    if err in ("expired", "session"):
                        resp.success()
                        retry_err = err
                    else:
                        resp.failure(f"POST /v2/orders 401: {resp.text[:200]}")
                        return False
                elif resp.status_code == 412 and not retried_412:
                    resp.success()
                    need_412_retry = True
                elif resp.status_code == 201:
                    data = self._parse_json(resp)
                    if (
                        isinstance(data, dict)
                        and data.get("accepted") is True
                        and data.get("id")
                    ):
                        self._update_csrf(data)
                        resp.success()
                        return True
                    resp.failure(f"Order 201 not accepted: {resp.text[:200]}")
                    return False
                elif resp.status_code == 200:
                    resp.failure(f"Order business failure: {resp.text[:200]}")
                    return False
                else:
                    resp.failure(
                        f"POST /v2/orders failed with {resp.status_code}: {resp.text[:200]}"
                    )
                    return False

            if retry_err:
                auth_recovered = True
                ok, recovered_etag = self._recover_auth(retry_err, cart_id=cart_id)
                if not ok:
                    return False
                if recovered_etag:
                    etag = recovered_etag
                continue

            if need_412_retry:
                retried_412 = True
                fresh_etag = self._fetch_cart_etag(cart_id)
                if not fresh_etag:
                    return False
                etag = fresh_etag

    def _execute_journey(self):
        if not self._login():
            return

        item = self._select_catalog_item()
        if item is None:
            return
        product_id, variant_id = item

        cart_id, etag = self._create_cart(product_id, variant_id)
        if not cart_id:
            return

        ok, etag = self._patch_cart(cart_id, etag, quantity=2)
        if not ok:
            return

        self._submit_order(cart_id, etag)

    @task
    def run_flow(self):
        if self.iterations_done >= ITERATIONS_PER_USER:
            self._mark_finished()
            raise StopUser()

        try:
            self._execute_journey()
        finally:
            self.iterations_done += 1

        if self.iterations_done >= ITERATIONS_PER_USER:
            self._mark_finished()
            raise StopUser()


class ShopLoadShape(LoadTestShape):
    max_run_time = 60

    def tick(self):
        if self.get_run_time() > self.max_run_time:
            return None
        if ShopUser._finished_users >= TARGET_USERS:
            return None
        return (TARGET_USERS, TARGET_USERS)

