import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = resolveBaseUrl();

    private static String resolveBaseUrl() {
        String env = System.getenv("BASE_URL");
        return (env == null || env.isBlank()) ? "http://127.0.0.1:8000" : env.trim();
    }

    private static boolean isTruthy(Object value) {
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        return value != null && "true".equalsIgnoreCase(String.valueOf(value));
    }

    private static boolean isExplicitlyFalse(Object value) {
        if (value instanceof Boolean) {
            return !((Boolean) value);
        }
        return value != null && "false".equalsIgnoreCase(String.valueOf(value));
    }

    private static Map<String, Object> selectInStockItem(List<Object> products) {
        if (products == null) {
            return Collections.emptyMap();
        }
        for (Object prodObj : products) {
            if (!(prodObj instanceof Map<?, ?>)) {
                continue;
            }
            Map<?, ?> product = (Map<?, ?>) prodObj;
            Object productId = product.get("id");
            if (productId == null || isExplicitlyFalse(product.get("in_stock"))) {
                continue;
            }
            Object variantsObj = product.get("variants");
            if (!(variantsObj instanceof List<?>)) {
                continue;
            }
            for (Object varObj : (List<?>) variantsObj) {
                if (!(varObj instanceof Map<?, ?>)) {
                    continue;
                }
                Map<?, ?> variant = (Map<?, ?>) varObj;
                Object variantId = variant.get("id");
                if (variantId != null && isTruthy(variant.get("in_stock"))) {
                    Map<String, Object> selected = new HashMap<>();
                    selected.put("productId", productId);
                    selected.put("variantId", variantId);
                    return selected;
                }
            }
        }
        return Collections.emptyMap();
    }

    private static String jsonString(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder(value.length() + 2);
        sb.append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
                    break;
            }
        }
        sb.append('"');
        return sb.toString();
    }

    private static String jsonValue(Object value) {
        if (value == null) {
            return "null";
        }
        if (value instanceof Number || value instanceof Boolean) {
            return value.toString();
        }
        return jsonString(String.valueOf(value));
    }

    private static HttpRequestActionBuilder createOrderRequest(boolean includeIfMatch) {
        HttpRequestActionBuilder req = http("POST order")
            .post("/v2/orders")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{idempotencyKey}");
        if (includeIfMatch) {
            req = req.header("If-Match", "#{etag}");
        }
        return req
            .body(StringBody(session ->
                "{\"cart_id\":" + jsonValue(session.get("cartId")) + "}"
            ))
            .check(
                status().is(201),
                jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.id").ofObject().find().saveAs("orderId"),
                jsonPath("$.csrf").find().optional().saveAs("csrf")
            );
    }

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableFollowRedirect();

    private final ScenarioBuilder scn = scenario("Nested Catalog Selection Checkout")
        .repeat(2).on(
            exitBlockOnFail().on(
                exec(flushCookieJar()),
                exec(session -> {
                    long accountIndex = Math.floorMod(session.userId() - 1L, 16L) + 1L;
                    return session
                        .removeAll(
                            "csrf",
                            "loginCsrf",
                            "loginLocation",
                            "selectedItem",
                            "productId",
                            "variantId",
                            "cartId",
                            "etag",
                            "idempotencyKey",
                            "orderId"
                        )
                        .set("username", "bench-" + accountIndex)
                        .set("password", "bench")
                        .set("idempotencyKey", UUID.randomUUID().toString());
                }),
                exec(
                    http("GET login-form")
                        .get("/v2/login-form")
                        .check(
                            status().is(200),
                            css("input[name=csrf]", "value").find().saveAs("loginCsrf")
                        )
                ),
                exec(
                    http("POST login")
                        .post("/v2/login")
                        .asJson()
                        .body(StringBody(session ->
                            "{\"username\":" + jsonString(session.getString("username"))
                                + ",\"password\":" + jsonString(session.getString("password"))
                                + ",\"csrf\":" + jsonString(session.getString("loginCsrf")) + "}"
                        ))
                        .check(
                            status().in(200, 302),
                            checkIf((response, session) -> response.status().code() == 302)
                                .then(header("Location").find().saveAs("loginLocation")),
                            checkIf((response, session) -> response.status().code() == 200)
                                .then(jsonPath("$.csrf").find().saveAs("csrf"))
                        )
                ),
                doIf(session -> session.contains("loginLocation")).then(
                    exec(
                        http("GET login redirect")
                            .get("#{loginLocation}")
                            .check(
                                status().is(200),
                                jsonPath("$.csrf").find().saveAs("csrf")
                            )
                    )
                ),
                exec(
                    http("GET catalog")
                        .get("/v2/catalog")
                        .check(
                            status().is(200),
                            jsonPath("$.data.products")
                                .ofList()
                                .find()
                                .transform(ModelSimulation::selectInStockItem)
                                .not(Collections.<String, Object>emptyMap())
                                .saveAs("selectedItem")
                        )
                ),
                exec(session -> {
                    Object selectedObj = session.get("selectedItem");
                    Map<?, ?> selected = (Map<?, ?>) selectedObj;
                    return session
                        .set("productId", selected.get("productId"))
                        .set("variantId", selected.get("variantId"));
                }),
                exec(
                    http("POST cart")
                        .post("/v2/carts")
                        .asJson()
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody(session ->
                            "{\"product_id\":" + jsonValue(session.get("productId"))
                                + ",\"variant_id\":" + jsonValue(session.get("variantId")) + "}"
                        ))
                        .check(
                            status().is(201),
                            jsonPath("$.id").ofObject().find().saveAs("cartId"),
                            jsonPath("$.csrf").find().optional().saveAs("csrf"),
                            header("ETag").find().optional().saveAs("etag")
                        )
                ),
                doIfOrElse(session -> {
                    String etag = session.getString("etag");
                    return etag != null && !etag.isEmpty();
                }).then(
                    exec(createOrderRequest(true))
                ).orElse(
                    exec(createOrderRequest(false))
                )
            )
        );

    {
        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .assertions(global().failedRequests().count().is(0L));
    }
}
