import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      const val = res.headers[keys[i]];
      return Array.isArray(val) ? val[0] : val;
    }
  }
  return null;
}

function parseJson(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (_) {
    return null;
  }
}

function resolveUrl(pathOrUrl) {
  if (!pathOrUrl) return null;
  if (/^https?:\/\//i.test(pathOrUrl)) return pathOrUrl;
  if (pathOrUrl.startsWith('/')) return `${BASE_URL}${pathOrUrl}`;
  return `${BASE_URL}/${pathOrUrl}`;
}

function updateCsrf(body, state) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function extractLoginCsrf(html) {
  if (!html) return null;
  const doc = parseHTML(html);

  function pickValidCsrf(selection) {
    for (let i = 0; i < selection.size(); i++) {
      const el = selection.eq(i);
      if (el.attr('disabled') !== undefined) continue;
      if (el.parents('template, noscript').size() > 0) continue;
      const val = el.attr('value');
      if (typeof val === 'string' && val.trim().length > 0) {
        return val.trim();
      }
    }
    return null;
  }

  const forms = doc.find('form');
  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (form.attr('hidden') !== undefined) continue;
    const action = (form.attr('action') || '').toLowerCase();
    const isLoginForm =
      action.includes('login') ||
      form.find('input[name="username"], input[name="password"]').size() > 0;
    if (!isLoginForm) continue;

    const token = pickValidCsrf(form.find('input[name="csrf"]'));
    if (token) return token;

    const formId = form.attr('id');
    if (formId) {
      const linked = pickValidCsrf(doc.find(`input[name="csrf"][form="${formId}"]`));
      if (linked) return linked;
    }
  }

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (form.attr('hidden') !== undefined) continue;
    const token = pickValidCsrf(form.find('input[name="csrf"]'));
    if (token) return token;
  }

  const anyToken = pickValidCsrf(doc.find('input[name="csrf"]'));
  if (anyToken) return anyToken;

  const fallback = doc.find('input[name="csrf"]').first().attr('value');
  return typeof fallback === 'string' && fallback.trim().length > 0 ? fallback.trim() : null;
}

function performLogin(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar: state.jar,
    redirects: 0,
  });

  const loginCsrf = formRes.status === 200 ? extractLoginCsrf(formRes.body) : null;
  if (!loginCsrf) {
    return { ok: false, formRes, loginRes: null, body: null };
  }

  let loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: state.username,
      password: state.password,
      csrf: loginCsrf,
    }),
    {
      jar: state.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
      },
    }
  );

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'location');
    if (loc) {
      loginRes = http.get(resolveUrl(loc), {
        jar: state.jar,
        redirects: 0,
      });
    }
  }

  const body = parseJson(loginRes);
  if (loginRes.status === 200 && body) {
    updateCsrf(body, state);
    return { ok: Boolean(state.csrf), formRes, loginRes, body };
  }

  return { ok: false, formRes, loginRes, body };
}

function recoverCart(state) {
  if (!state.cartId) return true;
  const res = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, JSON.stringify({}), {
    jar: state.jar,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
  });
  const body = parseJson(res);
  updateCsrf(body, state);
  const etag = getHeader(res, 'etag');
  if (etag) {
    state.etag = etag;
  }
  return res.status >= 200 && res.status < 300;
}

function recoverAuth(state, errorCode) {
  if (errorCode === 'expired') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
      jar: state.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
    });
    if (renewRes.status === 200) {
      updateCsrf(parseJson(renewRes), state);
      return recoverCart(state);
    }
    const relogin = performLogin(state);
    if (!relogin.ok) return false;
    return recoverCart(state);
  }

  if (errorCode === 'session') {
    const relogin = performLogin(state);
    if (!relogin.ok) return false;
    return recoverCart(state);
  }

  return false;
}

function requestWithRecovery(state, fn) {
  let res = fn();
  if (res.status === 401) {
    const body = parseJson(res);
    const err = body && body.error;
    if (err === 'expired' || err === 'session') {
      if (recoverAuth(state, err)) {
        res = fn();
      }
    }
  }
  return res;
}

function selectInStockProductAndVariant(catalogBody) {
  const products =
    (catalogBody && catalogBody.data && Array.isArray(catalogBody.data.products) && catalogBody.data.products) ||
    (catalogBody && Array.isArray(catalogBody.products) && catalogBody.products) ||
    [];

  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || product.id === undefined || product.id === null || product.id === '') {
      continue;
    }
    if (product.in_stock === false) {
      continue;
    }
    const variants = Array.isArray(product.variants) ? product.variants : [];
    for (let j = 0; j < variants.length; j++) {
      const variant = variants[j];
      if (!variant || variant.id === undefined || variant.id === null || variant.id === '') {
        continue;
      }
      if (variant.in_stock === true) {
        return {
          productId: product.id,
          variantId: variant.id,
        };
      }
    }
  }

  return null;
}

export default function () {
  const userIndex = ((__VU - 1) % 16) + 1;
  const state = {
    username: `bench-${userIndex}`,
    password: 'bench',
    jar: new http.CookieJar(),
    csrf: '',
    cartId: null,
    etag: null,
  };

  const loginResult = performLogin(state);
  const loginOk = check(loginResult, {
    'login form returned 200': (r) => r.formRes && r.formRes.status === 200,
    'login succeeded with csrf': (r) => r.ok && r.loginRes && r.loginRes.status === 200,
  });
  if (!loginOk) return;

  let selection = null;
  let catalogUrl = `${BASE_URL}/v2/catalog`;
  let catalogRes = null;
  let pages = 0;

