        jar: state.jar,
        redirects: 0,
      })
    );
    const fetchedEtag = getHeader(cartGetRes, 'etag');
    if (fetchedEtag) {
      state.etag = fetchedEtag;
    }
  }

  const idempotencyKey = `order-${state.cartId}-vu${__VU}-it${__ITER}`;

  const submitOrder = () => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idempotencyKey,
    };
    if (state.etag) {
      headers['If-Match'] = state.etag;
    }
    return http.post(
      `${BASE_URL}/v2/orders`,
      JSON.stringify({
        cart_id: state.cartId,
      }),
      {
        jar: state.jar,
        redirects: 0,
        headers,
      }
    );
  };

  let orderRes = requestWithRecovery(state, submitOrder);

  if (orderRes.status === 412) {
    const refreshRes = requestWithRecovery(state, () =>
      http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
        jar: state.jar,
        redirects: 0,
      })
    );
    const refreshedEtag = getHeader(refreshRes, 'etag');
    if (refreshedEtag) {
      state.etag = refreshedEtag;
    }
    orderRes = requestWithRecovery(state, submitOrder);
  }

  const orderBody = parseJson(orderRes);
  if (orderRes.status === 201 && orderBody) {
    updateCsrf(orderBody, state);
  }

  check(orderRes, {
    'order created with 201': (r) => r.status === 201,
    'order accepted': () => orderBody !== null && orderBody.accepted === true && Boolean(orderBody.id),
  });
}

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = resolveBaseUrl();

    private static String resolveBaseUrl() {
        String env = System.getenv("BASE_URL");
        return (env != null && !env.isBlank()) ? env : "http://127.0.0.1:8000";
    }

    private static boolean hasText(String s) {
        return s != null && !s.isBlank();
    }

    private static String normalizeUrl(String url, String defaultBasePath) {
        if (!hasText(url)) {
            return null;
        }
        String trimmed = url.trim();
        if (trimmed.startsWith("http://") || trimmed.startsWith("https://") || trimmed.startsWith("/")) {
            return trimmed;
        }
        if (trimmed.startsWith("?")) {
            return defaultBasePath + trimmed;
        }
        if (trimmed.startsWith("v2/")) {
            return "/" + trimmed;
        }
        int slash = defaultBasePath.lastIndexOf('/');
        String parentDir = slash >= 0 ? defaultBasePath.substring(0, slash + 1) : "/";
        return parentDir + trimmed;
    }

    private static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder(s.length() + 8);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
                    break;
            }
        }
        return sb.toString();
    }

    private static String toJsonString(String s) {
        return s == null ? "null" : "\"" + escapeJson(s) + "\"";
    }

    private static String toJsonValue(Object obj) {
        if (obj == null) {
            return "null";
        }
        if (obj instanceof Number || obj instanceof Boolean) {
            return obj.toString();
        }
        return toJsonString(String.valueOf(obj));
    }

    private static String unescapeJsonString(String s) {
        if (s == null || s.indexOf('\\') < 0) {
            return s;
        }
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                char next = s.charAt(++i);
                switch (next) {
                    case '"':
                        sb.append('"');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case '/':
                        sb.append('/');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'u':
                        if (i + 4 < s.length()) {
                            String hex = s.substring(i + 1, i + 5);
                            try {
                                sb.append((char) Integer.parseInt(hex, 16));
                                i += 4;
                            } catch (NumberFormatException e) {
                                sb.append("\\u");
                            }
                        } else {
                            sb.append("\\u");
                        }
                        break;
                    default:
                        sb.append(next);
                        break;
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static Session initJourney(Session session) {
        long accountIndex = ((session.userId() - 1L) % 16L) + 1L;
        String username = "bench-" + accountIndex;
        return session
            .markAsSucceeded()
            .removeAll(
                "csrf", "newCsrf", "formCsrf", "allCsrf",
                "loginStatus", "loginLocation",
                "pageJson", "nextPageUrl", "pageCount",
                "foundEligible", "productIdJson", "variantIdJson",
                "cartIdObj", "cartId", "cartIdJson",
                "cartEtag", "newEtag", "patchStatus",
                "idemKey", "orderId"
            )
            .set("username", username)
            .set("nextPageUrl", "/v2/catalog/page")
            .set("pageCount", 0)
            .set("foundEligible", false)
            .set("idemKey", UUID.randomUUID().toString());
    }

    private static Session selectFormCsrf(Session session) {
        String chosen = session.getString("formCsrf");
        if (!hasText(chosen)) {
            List<String> all = session.getList("allCsrf");
            if (all != null) {
                for (String candidate : all) {
                    if (hasText(candidate)) {
                        chosen = candidate;
                        break;
                    }
                }
            }
        }
        Session updated = session.removeAll("formCsrf", "allCsrf");
        if (!hasText(chosen)) {
            return updated.markAsFailed();
        }
        return updated.set("csrf", chosen);
    }

    private static Session updateCsrf(Session session) {
        String fresh = session.getString("newCsrf");
        Session updated = session.remove("newCsrf");
        if (hasText(fresh)) {
            return updated.set("csrf", unescapeJsonString(fresh));
        }
        return updated;
    }

    private static Session updateEtag(Session session) {
        String fresh = session.getString("newEtag");
        Session updated = session.remove("newEtag");
        if (hasText(fresh)) {
            return updated.set("cartEtag", fresh);
        }
        return updated;
    }

    private static void addProductsFromContainer(Map<?, ?> container, List<Map<?, ?>> out) {
        if (container == null) {
            return;
        }
        Object productsObj = container.get("products");
        if (productsObj instanceof List<?>) {
            for (Object item : (List<?>) productsObj) {
                if (item instanceof Map<?, ?>) {
                    out.add((Map<?, ?>) item);
                }
            }
        }
        Object itemsObj = container.get("items");
        if (itemsObj instanceof List<?>) {
            for (Object item : (List<?>) itemsObj) {
                if (item instanceof Map<?, ?>) {
                    out.add((Map<?, ?>) item);
                }
            }
        }
        Object productObj = container.get("product");
        if (productObj instanceof Map<?, ?>) {
            out.add((Map<?, ?>) productObj);
        }
        Object itemObj = container.get("item");
        if (itemObj instanceof Map<?, ?>) {
            out.add((Map<?, ?>) itemObj);
        }
        if (container.containsKey("id") && container.containsKey("variants")) {
            out.add(container);
        }
    }

    private static Session processCatalogPage(Session session) {
        Integer pcObj = session.get("pageCount");
        int nextCount = (pcObj != null ? pcObj : 0) + 1;
        Map<String, Object> root = session.getMap("pageJson");

        String nextUrl = null;
        if (root != null) {
            Object nextObj = root.get("next");
            if (nextObj == null && root.get("data") instanceof Map<?, ?>) {
                nextObj = ((Map<?, ?>) root.get("data")).get("next");
            }
            if (nextObj instanceof String) {
                nextUrl = normalizeUrl((String) nextObj, "/v2/catalog/page");
            }
        }

        Session updated = session
            .remove("pageJson")
            .set("pageCount", nextCount);

        if (hasText(nextUrl)) {
            updated = updated.set("nextPageUrl", nextUrl);
        } else {
            updated = updated.remove("nextPageUrl");
        }

        if (!Boolean.TRUE.equals(updated.get("foundEligible")) && root != null) {
            List<Map<?, ?>> products = new ArrayList<>();
            addProductsFromContainer(root, products);
            Object dataObj = root.get("data");
            if (dataObj instanceof Map<?, ?>) {
                addProductsFromContainer((Map<?, ?>) dataObj, products);
            }

            outer:
            for (Map<?, ?> product : products) {
                Object prodId = product.get("id");
                Object variantsObj = product.get("variants");
                if (prodId == null || !(variantsObj instanceof List<?>)) {
                    continue;
                }
                for (Object vObj : (List<?>) variantsObj) {
                    if (!(vObj instanceof Map<?, ?>)) {
                        continue;
                    }
                    Map<?, ?> variant = (Map<?, ?>) vObj;
                    Object varId = variant.get("id");
                    Object inStockObj = variant.get("in_stock");
                    boolean inStock = Boolean.TRUE.equals(inStockObj)
                        || (inStockObj instanceof String && "true".equalsIgnoreCase((String) inStockObj));
                    if (inStock && varId != null) {
                        updated = updated
                            .set("foundEligible", true)
                            .set("productIdJson", toJsonValue(prodId))
                            .set("variantIdJson", toJsonValue(varId));
                        break outer;
                    }
                }
            }
        }

        return updated;
    }

    private static Session processCartCreated(Session session) {
        Object cartIdObj = session.get("cartIdObj");
        Session updated = session.remove("cartIdObj");
        updated = updateCsrf(updated);
        updated = updateEtag(updated);
        if (cartIdObj == null) {
            return updated.markAsFailed();
        }
        return updated
            .set("cartId", String.valueOf(cartIdObj))
            .set("cartIdJson", toJsonValue(cartIdObj));
    }

    private static ChainBuilder buildPatchCart(boolean isRetry) {
        String name = isRetry ? "patch_cart_retry" : "patch_cart";
        CheckBuilder statusCheck = isRetry
            ? status().in(200, 204)
            : status().in(200, 204, 412).saveAs("patchStatus");

        HttpRequestActionBuilder withIfMatch = http(name)
            .patch(session -> "/v2/carts/" + session.getString("cartId"))
            .asJson()
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("If-Match", session -> session.getString("cartEtag"))
            .body(StringBody("{\"quantity\":2}"))
            .check(
                statusCheck,
                header("ETag").optional().saveAs("newEtag"),
                regex("\"csrf\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").optional().saveAs("newCsrf")
            );

        HttpRequestActionBuilder withoutIfMatch = http(name)
            .patch(session -> "/v2/carts/" + session.getString("cartId"))
            .asJson()
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .body(StringBody("{\"quantity\":2}"))
            .check(
                statusCheck,
                header("ETag").optional().saveAs("newEtag"),
                regex("\"csrf\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").optional().saveAs("newCsrf")
            );

        return doIfOrElse(session -> hasText(session.getString("cartEtag")))
            .then(exec(withIfMatch))
            .orElse(exec(withoutIfMatch))
            .exec(ModelSimulation::updateCsrf)
            .exec(ModelSimulation::updateEtag);
    }

    private static ChainBuilder buildCreateOrder() {
        HttpRequestActionBuilder withIfMatch = http("create_order")
            .post("/v2/orders")
            .asJson()
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("Idempotency-Key", session -> session.getString("idemKey"))
            .header("If-Match", session -> session.getString("cartEtag"))
            .body(StringBody(session -> "{\"cart_id\":" + session.getString("cartIdJson") + "}"))
            .check(
                status().is(201),
                jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.id").exists().saveAs("orderId"),
                jsonPath("$.csrf").optional().saveAs("newCsrf")
            );

        HttpRequestActionBuilder withoutIfMatch = http("create_order")
            .post("/v2/orders")
            .asJson()
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("Idempotency-Key", session -> session.getString("idemKey"))
            .body(StringBody(session -> "{\"cart_id\":" + session.getString("cartIdJson") + "}"))
            .check(
                status().is(201),
                jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.id").exists().saveAs("orderId"),
                jsonPath("$.csrf").optional().saveAs("newCsrf")
            );

        return doIfOrElse(session -> hasText(session.getString("cartEtag")))
            .then(exec(withIfMatch))
            .orElse(exec(withoutIfMatch))
            .exec(ModelSimulation::updateCsrf);
    }

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableFollowRedirect()
        .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

    private final ChainBuilder journey = exitBlockOnFail().on(
        exec(flushCookieJar())
        .exec(ModelSimulation::initJourney)
        .exec(
            http("login_form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("form[action*='/v2/login'] input[name=csrf]", "value").optional().saveAs("formCsrf"),
                    css("input[name=csrf]", "value").findAll().saveAs("allCsrf")
                )
        )
        .exec(ModelSimulation::selectFormCsrf)
        .exec(
            http("login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(session ->
                    "{\"username\":" + toJsonString(session.getString("username"))
                        + ",\"password\":\"bench\""
                        + ",\"csrf\":" + toJsonString(session.getString("csrf")) + "}"
                ))
                .check(
                    status().in(200, 302).saveAs("loginStatus"),
                    header("Location").optional().saveAs("loginLocation"),
                    regex("\"csrf\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").optional().saveAs("newCsrf")
                )
        )
        .exec(ModelSimulation::updateCsrf)
        .doIf(session -> Integer.valueOf(302).equals(session.get("loginStatus"))).then(
            exec(session -> {
                String loc = normalizeUrl(session.getString("loginLocation"), "/v2/login");
                if (!hasText(loc)) {
                    return session.markAsFailed();
                }
                return session.set("loginLocation", loc);
            })
            .exec(
                http("login_redirect")
                    .get(session -> session.getString("loginLocation"))
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").optional().saveAs("newCsrf")
                    )
            )
            .exec(ModelSimulation::updateCsrf)
        )
        .asLongAs(session -> {
            Integer pc = session.get("pageCount");
            int count = pc != null ? pc : 0;
            return count < 3 && hasText(session.getString("nextPageUrl"));
        }).on(
            exec(
                http("catalog_page")
                    .get(session -> session.getString("nextPageUrl"))
                    .check(
                        status().is(200),
                        jsonPath("$").ofMap().saveAs("pageJson")
                    )
            )
            .exec(ModelSimulation::processCatalogPage)
        )
        .exec(session -> Boolean.TRUE.equals(session.get("foundEligible")) ? session : session.markAsFailed())
        .exec(
            http("create_cart")
                .post("/v2/carts")
                .asJson()
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session ->
                    "{\"product_id\":" + session.getString("productIdJson")
                        + ",\"variant_id\":" + session.getString("variantIdJson") + "}"
                ))
                .check(
                    status().is(201),
                    jsonPath("$.id").ofObject().saveAs("cartIdObj"),
                    jsonPath("$.csrf").optional().saveAs("newCsrf"),
                    header("ETag").optional().saveAs("newEtag")
                )
        )
        .exec(ModelSimulation::processCartCreated)
        .exec(
            http("get_cart")
                .get(session -> "/v2/carts/" + session.getString("cartId"))
                .check(
                    status().is(200),
                    header("ETag").optional().saveAs("newEtag")
                )
        )
        .exec(ModelSimulation::updateEtag)
        .exec(buildPatchCart(false))
        .doIf(session -> Integer.valueOf(412).equals(session.get("patchStatus"))).then(
            exec(
                http("get_cart_retry")
                    .get(session -> "/v2/carts/" + session.getString("cartId"))
                    .check(
                        status().is(200),
                        header("ETag").optional().saveAs("newEtag")
                    )
            )
            .exec(ModelSimulation::updateEtag)
            .exec(buildPatchCart(true))
        )
        .exec(buildCreateOrder())
    );

    private final ScenarioBuilder scn = scenario("PaginationCheckout")
        .repeat(2).on(journey);

    {
        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}

import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const MAX_CATALOG_PAGES = 3;

export const options = {
  scenarios: {
    pagination: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1.0'],
  },
};

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (_) {
    return null;
  }
}

function getHeader(headers, name) {
  if (!headers || typeof headers !== 'object') return '';
  const target = name.toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      const val = headers[keys[i]];
      return Array.isArray(val) ? String(val[0] || '') : String(val || '');
    }
  }
  return '';
}

function resolveUrl(baseUrl, currentPath, target) {
  const origin = baseUrl.replace(/\/+$/, '');
  if (!target || typeof target !== 'string') return null;
  const trimmed = target.trim();
  if (!trimmed) return null;
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  if (trimmed.startsWith('/')) return `${origin}${trimmed}`;
  if (trimmed.startsWith('?')) {
    const pathOnly = currentPath.split('?')[0];
    return `${origin}${pathOnly}${trimmed}`;
  }
  const basePath = currentPath.split('?')[0].replace(/\/[^/]*$/, '/');
  return `${origin}${basePath}${trimmed}`;
}

function isAttrPresent(el, attrName) {
  const val = el.attr(attrName);
  return val !== undefined && val !== null;
}

function isValidCsrfInput(inp) {
  if (!inp || inp.size() === 0) return false;
  const val = inp.attr('value');
  if (!val || !String(val).trim()) return false;
  if (isAttrPresent(inp, 'disabled')) return false;
  if (isAttrPresent(inp, 'data-decoy')) return false;
  if (inp.parents('template').size() > 0 || inp.parents('noscript').size() > 0) return false;
  return true;
}

function isHiddenOrDecoyForm(form) {
  if (isAttrPresent(form, 'hidden') || isAttrPresent(form, 'data-decoy')) return true;
  if (String(form.attr('aria-hidden') || '').toLowerCase() === 'true') return true;
  return false;
}

function extractLoginCsrf(html) {
  if (!html) return '';
  const doc = parseHTML(html);
  const forms = doc.find('form');

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (form.parents('template').size() > 0 || form.parents('noscript').size() > 0) continue;
    if (isHiddenOrDecoyForm(form)) continue;
    const action = String(form.attr('action') || '').toLowerCase();
    const isLoginForm =
      action.includes('login') ||
      form.find('input[name="username"]').size() > 0 ||
      form.find('input[name="password"]').size() > 0;
    if (!isLoginForm) continue;
    const inputs = form.find('input[name="csrf"]:not([disabled])');
    for (let j = 0; j < inputs.size(); j++) {
      const inp = inputs.eq(j);
      if (isValidCsrfInput(inp)) return String(inp.attr('value')).trim();
    }
  }

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (form.parents('template').size() > 0 || form.parents('noscript').size() > 0) continue;
    const inputs = form.find('input[name="csrf"]:not([disabled])');
    for (let j = 0; j < inputs.size(); j++) {
      const inp = inputs.eq(j);
      if (isValidCsrfInput(inp)) return String(inp.attr('value')).trim();
    }
  }

  const allInputs = doc.find('input[name="csrf"]:not([disabled])');
  for (let i = 0; i < allInputs.size(); i++) {
    const inp = allInputs.eq(i);
    if (isValidCsrfInput(inp)) return String(inp.attr('value')).trim();
  }

  return '';
}

function extractProducts(body) {
  if (!body || typeof body !== 'object') return [];
  if (body.data && Array.isArray(body.data.products)) return body.data.products;
  if (body.data && body.data.product && typeof body.data.product === 'object') {
    return [body.data.product];
  }
  if (Array.isArray(body.products)) return body.products;
  if (body.product && typeof body.product === 'object') return [body.product];
  if (body.data && Array.isArray(body.data.variants)) return [body.data];
  if (Array.isArray(body.variants)) return [body];
  return [];
}

function findEligibleItem(products) {
  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || product.id === undefined || product.id === null) continue;
    if (product.in_stock === false || product.eligible === false || product.available === false) {
      continue;
    }
    const variants = Array.isArray(product.variants) ? product.variants : [];
    for (let j = 0; j < variants.length; j++) {
      const variant = variants[j];
      if (!variant || variant.id === undefined || variant.id === null) continue;
      if (variant.in_stock === true) {
        return {
          productId: product.id,
          variantId: variant.id,
        };
      }
    }
  }
  return null;
}

function sendRequest(method, url, body, extraHeaders, jar, tags) {
  const headers = Object.assign({ Accept: 'application/json' }, extraHeaders || {});
  const params = {
    headers,
    jar,
    redirects: 0,
  };
  if (tags) {
    params.tags = tags;
  }
  if (body !== null && body !== undefined) {
    if (!headers['Content-Type']) {
      headers['Content-Type'] = 'application/json';
    }
    const payload = typeof body === 'string' ? body : JSON.stringify(body);
    return http.request(method, url, payload, params);
  }
  return http.request(method, url, null, params);
}

function updateCsrf(state, json) {
  if (json && typeof json.csrf === 'string' && json.csrf.length > 0) {
    state.csrf = json.csrf;
  }
}

function performLogin(state) {
  const formRes = sendRequest(
    'GET',
    `${BASE_URL}/v2/login-form`,
    null,
    { Accept: 'text/html,application/xhtml+xml,*/*' },
    state.jar,
    { name: 'login_form' }
  );

  const formCsrf = extractLoginCsrf(formRes.body);
  const formOk = check(formRes, {
    'login form status 200': (r) => r.status === 200,
    'login form csrf extracted': () => formCsrf.length > 0,
  });
  if (!formOk) return false;

  let loginRes = sendRequest(
    'POST',
    `${BASE_URL}/v2/login`,
    { username: state.username, password: PASSWORD, csrf: formCsrf },
    null,
    state.jar,
    { name: 'login' }
  );

  if (loginRes.status >= 300 && loginRes.status < 400) {
    const loc = getHeader(loginRes.headers, 'Location');
    const locUrl = resolveUrl(BASE_URL, '/v2/login', loc);
    const hasLoc = check(loginRes, {
      'login redirect has location': () => Boolean(locUrl),
    });
    if (!hasLoc) return false;
    loginRes = sendRequest(
      'GET',
      locUrl,
      null,
      null,
      state.jar,
      { name: 'login_redirect' }
    );
  }

  const loginJson = safeJson(loginRes);
  updateCsrf(state, loginJson);

  return check(loginRes, {
    'login status 200': (r) => r.status === 200,
    'login csrf returned': () => state.csrf.length > 0,
  });
}

function recoverSession(errType, state) {
  let recovered = false;
  if (errType === 'expired') {
    const renewRes = sendRequest(
      'POST',
      `${BASE_URL}/v2/session/renew`,
      {},
      { 'X-CSRF-Token': state.csrf },
      state.jar,
      { name: 'session_renew' }
    );
    const renewJson = safeJson(renewRes);
    if (renewRes.status >= 200 && renewRes.status < 300) {
      updateCsrf(state, renewJson);
      recovered = true;
    }
  }

  if (!recovered) {
    recovered = performLogin(state);
  }

  if (recovered && state.cartId !== null && state.cartId !== undefined) {
    const recRes = sendRequest(
      'POST',
      `${BASE_URL}/v2/carts/${state.cartId}/recover`,
      {},
      { 'X-CSRF-Token': state.csrf },
      state.jar,
      { name: 'cart_recover' }
    );
    const recJson = safeJson(recRes);
    if (recRes.status >= 200 && recRes.status < 300) {
      updateCsrf(state, recJson);
      const etag = getHeader(recRes.headers, 'ETag');
      if (etag) state.etag = etag;
    }
  }

  return recovered;
}

function authedRequest(method, url, body, extraHeaders, tags, state) {
  const upperMethod = method.toUpperCase();
  const buildHeaders = () => {
    const h = Object.assign({}, extraHeaders || {});
    if (upperMethod !== 'GET') {
      h['X-CSRF-Token'] = state.csrf;
    }
    return h;
  };

  let res = sendRequest(upperMethod, url, body, buildHeaders(), state.jar, tags);

  if (res.status === 401) {
    const errJson = safeJson(res);
    const errType = errJson && typeof errJson.error === 'string' ? errJson.error : '';
    if (errType === 'expired' || errType === 'session') {
      if (recoverSession(errType, state)) {
        res = sendRequest(upperMethod, url, body, buildHeaders(), state.jar, tags);
      }
    }
  }

  if (res.status >= 200 && res.status < 300) {
    const json = safeJson(res);
    updateCsrf(state, json);
  }

  return res;
}

export default function () {
  const userIndex = ((__VU - 1) % 16) + 1;
  const state = {
    username: `bench-${userIndex}`,
    csrf: '',
    jar: new http.CookieJar(),
    cartId: null,
    etag: '',
  };

  if (!performLogin(state)) {
    return;
  }

  let currentUrl = `${BASE_URL}/v2/catalog/page`;
  let currentPath = '/v2/catalog/page';
  const visited = new Set();
  let pagesVisited = 0;
  let selected = null;

  while (currentUrl && pagesVisited < MAX_CATALOG_PAGES) {
    if (visited.has(currentUrl)) {
      break;
    }
    visited.add(currentUrl);
    pagesVisited += 1;

    const pageRes = authedRequest(
      'GET',
      currentUrl,
      null,
      null,
      { name: 'catalog_page' },
      state
    );
    const pageJson = safeJson(pageRes);

    const pageOk = check(pageRes, {
      'catalog page status 200': (r) => r.status === 200,
      'catalog page valid json': () => pageJson !== null,
    });
    if (!pageOk) {
      break;
    }

    const products = extractProducts(pageJson);
    if (!selected) {
      selected = findEligibleItem(products);
    }

    const rawNext =
      pageJson.next !== undefined
        ? pageJson.next
        : pageJson.data && pageJson.data.next !== undefined
        ? pageJson.data.next
        : null;

    if (!rawNext) {
      break;
    }

    const nextUrl = resolveUrl(BASE_URL, currentPath, rawNext);
    if (!nextUrl || visited.has(nextUrl)) {
      break;
    }
    currentUrl = nextUrl;
    currentPath = nextUrl.replace(/^https?:\/\/[^/]+/, '') || '/v2/catalog/page';
  }

  const catalogOk = check(null, {
    'catalog traversal bounded': () => pagesVisited >= 1 && pagesVisited <= MAX_CATALOG_PAGES,
    'eligible item selected': () =>
      selected !== null &&
      selected.productId !== undefined &&
      selected.productId !== null &&
      selected.variantId !== undefined &&
      selected.variantId !== null,
  });
  if (!catalogOk) {
    return;
  }

  const cartRes = authedRequest(
    'POST',
    `${BASE_URL}/v2/carts`,
    {
      product_id: selected.productId,
      variant_id: selected.variantId,
    },
    null,
    { name: 'create_cart' },
    state
  );
  const cartJson = safeJson(cartRes);
  const cartId = cartJson ? cartJson.id : null;
  const cartEtag = getHeader(cartRes.headers, 'ETag');

  const cartOk = check(cartRes, {
    'cart created 201': (r) => r.status === 201,
    'cart id extracted': () => cartId !== undefined && cartId !== null && String(cartId).length > 0,
  });
  if (!cartOk) {
    return;
  }

  state.cartId = cartId;
  state.etag = cartEtag;

  const idempotencyKey = `order-vu${__VU}-iter${__ITER}-cart-${cartId}`;
  const orderHeaders = { 'Idempotency-Key': idempotencyKey };
  if (state.etag) {
    orderHeaders['If-Match'] = state.etag;
  }

  let orderRes = authedRequest(
    'POST',
    `${BASE_URL}/v2/orders`,
    { cart_id: state.cartId },
    orderHeaders,
    { name: 'create_order' },
    state
  );

  if (orderRes.status === 412 || orderRes.status === 428) {
    const refreshRes = authedRequest(
      'GET',
      `${BASE_URL}/v2/carts/${state.cartId}`,
      null,
      null,
      { name: 'get_cart' },
      state
    );
    const refreshedEtag = getHeader(refreshRes.headers, 'ETag');
    if (refreshedEtag) {
      state.etag = refreshedEtag;
      orderHeaders['If-Match'] = refreshedEtag;
    }
    orderRes = authedRequest(
      'POST',
      `${BASE_URL}/v2/orders`,
      { cart_id: state.cartId },
      orderHeaders,
      { name: 'create_order_retry' },
      state
    );
  }

  const orderJson = safeJson(orderRes);
  const orderId = orderJson ? orderJson.id : null;

  check(orderRes, {
    'order created 201': (r) => r.status === 201,
    'order accepted true': () => orderJson !== null && orderJson.accepted === true,
    'order id extracted': () =>
      orderId !== undefined && orderId !== null && String(orderId).length > 0,
  });
}

import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

VOID_TAGS = frozenset(
    {
        "area",
        "base",
        "br",
        "col",
        "embed",
        "hr",
        "img",
        "input",
        "link",
        "meta",
        "param",
        "source",
        "track",
        "wbr",
    }
)
IGNORED_CONTAINER_TAGS = frozenset({"script", "style", "template", "noscript"})
DECOY_KEYWORDS = ("decoy", "fake", "honeypot", "trap", "dummy")


def _has_decoy_marker(attrs):
    for key, val in attrs.items():
        k = (key or "").lower()
        v = (val or "").lower()
        for kw in DECOY_KEYWORDS:
            if kw in k or kw in v:
                return True
    return False


def _is_hidden_container(attrs):
    if "hidden" in attrs:
        return True
    if (attrs.get("aria-hidden") or "").strip().lower() == "true":
        return True
    style = "".join((attrs.get("style") or "").lower().split())
    if "display:none" in style or "visibility:hidden" in style:
        return True
    return False


class LoginFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._tag_stack = []
        self._forms = []
        self._forms_by_id = {}
        self._form_stack = []
        self._candidates = []

    def handle_starttag(self, tag, attrs_list):
        tag_l = tag.lower()
        attrs = {}
        for k, v in attrs_list:
            if k is None:
                continue
            attrs[k.lower()] = v if v is not None else ""

        in_ignored = any(item["tag"] in IGNORED_CONTAINER_TAGS for item in self._tag_stack)

        if tag_l == "form" and not in_ignored:
            form_info = {
                "action": (attrs.get("action") or "").lower(),
                "id": attrs.get("id") or "",
                "class": (attrs.get("class") or "").lower(),
                "name": (attrs.get("name") or "").lower(),
                "has_login_fields": False,
                "is_decoy": _has_decoy_marker(attrs),
                "is_hidden": _is_hidden_container(attrs),
            }
            self._forms.append(form_info)
            if form_info["id"]:
                self._forms_by_id[form_info["id"]] = form_info
            self._form_stack.append(form_info)

        if tag_l == "input" and not in_ignored:
            current_form = self._form_stack[-1] if self._form_stack else None
            input_name = (attrs.get("name") or "").strip()
            input_type = (attrs.get("type") or "").strip().lower()
            form_ref = attrs.get("form") or ""

            if current_form is not None and (
                input_name.lower() in ("username", "password", "user", "login")
                or input_type == "password"
            ):
                current_form["has_login_fields"] = True

            if input_name == "csrf":
                in_hidden_ancestor = any(item["hidden"] for item in self._tag_stack)
                in_decoy_ancestor = any(item["decoy"] for item in self._tag_stack)
                self._candidates.append(
                    {
                        "value": attrs.get("value"),
                        "disabled": "disabled" in attrs,
                        "decoy": _has_decoy_marker(attrs) or in_decoy_ancestor,
                        "hidden_ancestor": in_hidden_ancestor,
                        "is_hidden_type": input_type == "hidden",
                        "form": current_form,
                        "form_ref": form_ref,
                    }
                )

        if tag_l not in VOID_TAGS:
            self._tag_stack.append(
                {
                    "tag": tag_l,
                    "hidden": _is_hidden_container(attrs),
                    "decoy": _has_decoy_marker(attrs),
                }
            )

    def handle_endtag(self, tag):
        tag_l = tag.lower()
        if tag_l in VOID_TAGS:
            return
        if tag_l == "form" and self._form_stack:
            self._form_stack.pop()
        for idx in range(len(self._tag_stack) - 1, -1, -1):
            if self._tag_stack[idx]["tag"] == tag_l:
                del self._tag_stack[idx:]
                break

    def extract_csrf(self):
        if not self._candidates:
            return None

        best_score = None
        best_value = None
        for cand in self._candidates:
            form_info = cand["form"]
            if form_info is None and cand["form_ref"]:
                form_info = self._forms_by_id.get(cand["form_ref"])

            in_form = form_info is not None
            is_login_form = False
            form_decoy = False
            form_hidden = False
            if form_info is not None:
                is_login_form = (
                    "login" in form_info["action"]
                    or "login" in form_info["id"].lower()
                    or "login" in form_info["class"]
                    or "login" in form_info["name"]
                    or form_info["has_login_fields"]
                )
                form_decoy = form_info["is_decoy"]
                form_hidden = form_info["is_hidden"]

            val = cand["value"]
            has_value = bool(val and val.strip())
            score = (
                has_value,
                not cand["disabled"],
                not (cand["decoy"] or form_decoy),
                not (cand["hidden_ancestor"] or form_hidden),
                is_login_form,
                in_form,
                cand["is_hidden_type"],
            )
            if best_score is None or score > best_score:
                best_score = score
                best_value = val

        return best_value if (best_value and best_value.strip()) else None


class PaginationUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0.05)

    TARGET_USERS = 2
    ITERATIONS_PER_USER = 2
    MAX_CATALOG_PAGES = 3

    _spawned_count = 0
    _finished_count = 0

    def on_start(self):
        cls = type(self)
        cls._spawned_count += 1
        if cls._spawned_count > cls.TARGET_USERS:
            self._extra_user = True
            raise StopUser()

        self._extra_user = False
        self._counted_finished = False
        self._user_index = cls._spawned_count
        self.username = f"bench-{((self._user_index - 1) % 16) + 1}"
        self.password = "bench"
        self._iterations_done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None

    def on_stop(self):
        if not getattr(self, "_extra_user", True) and not getattr(self, "_counted_finished", False):
            self._counted_finished = True
            type(self)._finished_count += 1

    def _update_csrf(self, data):
        if isinstance(data, dict):
            token = data.get("csrf")
            if isinstance(token, str) and token:
                self.csrf = token

    def _update_etag(self, response):
        etag = response.headers.get("ETag") or response.headers.get("Etag")
        if etag:
            self.etag = etag

    def _safe_json(self, response):
        try:
            return response.json()
        except ValueError:
            return None

    def _normalize_local_url(self, raw_url, base="/v2/catalog/page"):
        if not isinstance(raw_url, str) or not raw_url.strip():
            return None
        resolved = urljoin(base, raw_url.strip())
        parts = urlsplit(resolved)
        if parts.scheme or parts.netloc:
            host_parts = urlsplit(self.host)
            if (
                parts.scheme.lower() != host_parts.scheme.lower()
                or parts.netloc.lower() != host_parts.netloc.lower()
            ):
                return None
        path = parts.path or "/"
        if parts.query:
            return f"{path}?{parts.query}"
        return path

    def _perform_login(self, clear_cookies=True):
        if clear_cookies:
            self.client.cookies.clear()
            self.csrf = None

        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form failed with status {resp.status_code}")
                return False
            parser = LoginFormParser()
            parser.feed(resp.text or "")
            parser.close()
            form_csrf = parser.extract_csrf()
            if not form_csrf:
                resp.failure("login-form missing input[name=csrf]")
                return False
            resp.success()
            self.csrf = form_csrf

        redirect_location = None
        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": self.csrf,
            },
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        ) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("login returned non-JSON body")
                    return False
                self._update_csrf(data)
                resp.success()
                return True
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                normalized = self._normalize_local_url(loc, base="/v2/login") if loc else None
                if not normalized:
                    resp.failure("login 302 missing valid local Location header")
                    return False
                redirect_location = normalized
                resp.success()
            else:
                resp.failure(f"login failed with status {resp.status_code}")
                return False

        with self.client.get(
            redirect_location,
            allow_redirects=False,
            catch_response=True,
            name="/v2/login-redirect",
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login redirect failed with status {resp.status_code}")
                return False
            data = self._safe_json(resp)
            if not isinstance(data, dict):
                resp.failure("login redirect returned non-JSON body")
                return False
            self._update_csrf(data)
            resp.success()
            return True

    def _recover_cart(self):
        if not self.cart_id:
            return True
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            catch_response=True,
            name="/v2/carts/{id}/recover",
        ) as resp:
            if resp.status_code not in (200, 201, 204):
                resp.failure(f"cart recover failed with status {resp.status_code}")
                return False
            data = self._safe_json(resp)
            self._update_csrf(data)
            self._update_etag(resp)
            resp.success()
            return True

    def _recover_session(self, error_kind):
        if error_kind == "expired":
            headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=headers,
                catch_response=True,
                name="/v2/session/renew",
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"session renew failed with status {resp.status_code}")
                    return False
                data = self._safe_json(resp)
                self._update_csrf(data)
                resp.success()
            return self._recover_cart()

        if error_kind == "session":
            if not self._perform_login(clear_cookies=False):
                return False
            return self._recover_cart()

        return False

    def _refresh_cart_etag(self):
        if not self.cart_id:
            return False
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            name="/v2/carts/{id}",
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"cart refresh failed with status {resp.status_code}")
                return False
            self._update_etag(resp)
            data = self._safe_json(resp)
            self._update_csrf(data)
            if not self.etag:
                resp.failure("cart refresh missing ETag")
                return False
            resp.success()
            return True

    def _authed_request(
        self,
        method,
        url,
        name,
        json_body=None,
        extra_headers=None,
        use_if_match=False,
        retry_on_412=False,
        expected_statuses=(200,),
        validator=None,
    ):
        recovered_401 = False
        retried_412 = False
        retries_429 = 0

        while True:
            headers = dict(extra_headers) if extra_headers else {}
            if method.upper() != "GET" and self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if use_if_match and self.etag:
                headers["If-Match"] = self.etag

            kwargs = {
                "headers": headers,
                "catch_response": True,
                "name": name,
            }
            if json_body is not None:
                kwargs["json"] = json_body

            with self.client.request(method, url, **kwargs) as resp:
                status = resp.status_code
                data = self._safe_json(resp)

                if status == 429 and retries_429 < 4:
                    resp.success()
                    retry_after_raw = resp.headers.get("Retry-After", "1")
                    try:
                        delay = max(0.0, float(retry_after_raw))
                    except ValueError:
                        delay = 1.0
                    retries_429 += 1
                    time.sleep(delay)
                    continue

                if status == 401:
                    err = data.get("error") if isinstance(data, dict) else None
                    if err in ("expired", "session") and not recovered_401:
                        resp.success()
                        recovered_401 = True
                        if not self._recover_session(err):
                            return None, None
                        continue
                    resp.failure(f"{method} {name} returned 401 ({err or 'unauthorized'})")
                    return None, None

                if status == 412 and retry_on_412 and not retried_412:
                    resp.success()
                    retried_412 = True
                    if not self._refresh_cart_etag():
                        return None, None
                    continue

                if status not in expected_statuses:
                    resp.failure(f"{method} {name} unexpected status {status}")
                    return None, None

                if validator is not None:
                    err_msg = validator(resp, data)
                    if err_msg:
                        resp.failure(err_msg)
                        return None, None

                self._update_csrf(data)
                self._update_etag(resp)
                resp.success()
                return data, resp

    def _extract_products(self, payload):
        if not isinstance(payload, dict):
            return []

        containers = []
        data_field = payload.get("data")
        if isinstance(data_field, dict):
            containers.append(data_field)
        elif isinstance(data_field, list):
            return [p for p in data_field if isinstance(p, dict)]
        containers.append(payload)

        for container in containers:
            for list_key in ("products", "items"):
                items = container.get(list_key)
                if isinstance(items, list):
                    return [p for p in items if isinstance(p, dict)]
            for single_key in ("product", "item"):
                item = container.get(single_key)
                if isinstance(item, dict):
                    return [item]
            if "variants" in container and ("id" in container or "product_id" in container):
                return [container]
        return []

    def _extract_next_url(self, payload):
        if not isinstance(payload, dict):
            return None

        candidates = [payload.get("next"), payload.get("next_url")]
        for nested_key in ("data", "links", "pagination"):
            nested = payload.get(nested_key)
            if isinstance(nested, dict):
                candidates.append(nested.get("next"))
                candidates.append(nested.get("next_url"))

        for cand in candidates:
            if isinstance(cand, dict):
                cand = cand.get("href") or cand.get("url")
            if isinstance(cand, str) and cand.strip():
                return cand.strip()
        return None

    def _is_truthy_stock(self, val):
        if val is True:
            return True
        if isinstance(val, int) and not isinstance(val, bool):
            return val > 0
        if isinstance(val, str):
            return val.strip().lower() == "true"
        return False

    def _find_eligible_item(self, payload):
        for product in self._extract_products(payload):
            if (
                product.get("active") is False
                or product.get("available") is False
                or product.get("eligible") is False
            ):
                continue
            product_id = product.get("id")
            if product_id is None:
                product_id = product.get("product_id")
            variants = product.get("variants")
            if product_id is None or not isinstance(variants, list):
                continue
            for variant in variants:
                if not isinstance(variant, dict):
                    continue
                if (
                    variant.get("active") is False
                    or variant.get("available") is False
                    or variant.get("eligible") is False
                ):
                    continue
                variant_id = variant.get("id")
                if variant_id is None:
                    variant_id = variant.get("variant_id")
                if variant_id is not None and self._is_truthy_stock(variant.get("in_stock")):
                    return product_id, variant_id
        return None

    def _traverse_catalog_pages(self):
        next_url = "/v2/catalog/page"
        visited = set()
        selected = None

        for _ in range(self.MAX_CATALOG_PAGES):
            if not next_url:
                break
            resolved = self._normalize_local_url(next_url, base="/v2/catalog/page")
            if not resolved or resolved in visited:
                break
            visited.add(resolved)

            data, _ = self._authed_request(
                "GET",
                resolved,
                name="/v2/catalog/page",
                expected_statuses=(200,),
                validator=lambda r, d: None if isinstance(d, dict) else "catalog page returned non-JSON",
            )
            if data is None:
                return None

            if selected is None:
                selected = self._find_eligible_item(data)

            next_url = self._extract_next_url(data)

        return selected

    def _execute_pagination_journey(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None

        if not self._perform_login(clear_cookies=True):
            return

        selected = self._traverse_catalog_pages()
        if not selected:
            return
        product_id, variant_id = selected

        cart_data, _ = self._authed_request(
            "POST",
            "/v2/carts",
            name="/v2/carts",
            json_body={"product_id": product_id, "variant_id": variant_id},
            expected_statuses=(201,),
            validator=lambda r, d: (
                None if (isinstance(d, dict) and d.get("id")) else "cart creation missing id"
            ),
        )
        if cart_data is None:
            return
        self.cart_id = cart_data["id"]

        if not self.etag:
            if not self._refresh_cart_etag():
                return

        patch_data, _ = self._authed_request(
            "PATCH",
            f"/v2/carts/{self.cart_id}",
            name="/v2/carts/{id}",
            json_body={"quantity": 2},
            use_if_match=True,
            retry_on_412=True,
            expected_statuses=(200, 204),
        )
        if patch_data is None and self.etag is None:
            return

        idempotency_key = str(uuid.uuid4())

        def _validate_order(resp, data):
            if resp.status_code != 201:
                return f"order expected 201, got {resp.status_code}"
            if not isinstance(data, dict):
                return "order response non-JSON"
            if data.get("accepted") is not True:
                return "order rejected (accepted is not true)"
            if not data.get("id"):
                return "order response missing id"
            return None

        self._authed_request(
            "POST",
            "/v2/orders",
            name="/v2/orders",
            json_body={"cart_id": self.cart_id},
            extra_headers={"Idempotency-Key": idempotency_key},
            use_if_match=bool(self.etag),
            retry_on_412=True,
            expected_statuses=(200, 201),
            validator=_validate_order,
        )

    @task
    def run_journey(self):
        if self._iterations_done >= self.ITERATIONS_PER_USER:
            raise StopUser()
        self._iterations_done += 1
        try:
            self._execute_pagination_journey()
        finally:
            if self._iterations_done >= self.ITERATIONS_PER_USER:
                raise StopUser()


class PaginationLoadShape(LoadTestShape):
    MAX_RUN_TIME = 120

    def tick(self):
        if self.get_run_time() > self.MAX_RUN_TIME:
            return None

        target = PaginationUser.TARGET_USERS
        spawned = PaginationUser._spawned_count
        finished = PaginationUser._finished_count

        if finished >= target:
            return None

        if spawned < target:
            return (target, 10)

        current = (
            self.get_current_user_count()
            if getattr(self, "runner", None) is not None
            else max(0, target - finished)
        )
        if current <= 0:
            return None
        return (current, 10)

import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const QUANTITY = 2;

export const options = {
  scenarios: {
    etag_journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const target = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === target) {
      const val = res.headers[key];
      return Array.isArray(val) ? val[0] : val;
    }
  }
  return null;
}

function parseJsonSafe(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function updateCsrf(state, body) {
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function extractEtag(res, body) {
  const hdr = getHeader(res, 'etag');
  if (hdr && hdr.trim().length > 0) {
    return hdr.trim();
  }
  if (body && typeof body.etag === 'string' && body.etag.trim().length > 0) {
    return body.etag.trim();
  }
  return null;
}

function resolveUrl(base, location) {
  if (!location) return null;
  if (/^https?:\/\//i.test(location)) {
    return location;
  }
  if (location.startsWith('/')) {
    return `${base}${location}`;
  }
  return `${base}/${location}`;
}

function extractLoginCsrf(html) {
  const doc = parseHTML(html);

  const hasHiddenStyle = (el) => {
    const st = (el.attr('style') || '').replace(/\s+/g, '').toLowerCase();
    return st.includes('display:none') || st.includes('visibility:hidden');
  };

  const isDecoyEl = (el, checkHiddenStyle) => {
    if (!el || el.size() === 0) return true;
    if (el.attr('disabled') !== undefined) return true;
    if (el.attr('inert') !== undefined) return true;
    if ((el.attr('aria-hidden') || '').toLowerCase() === 'true') return true;
    const cls = (el.attr('class') || '').toLowerCase();
    const id = (el.attr('id') || '').toLowerCase();
    if (
      cls.includes('decoy') ||
      id.includes('decoy') ||
      cls.includes('fake') ||
      id.includes('fake') ||
      cls.includes('honeypot') ||
      id.includes('honeypot')
    ) {
      return true;
    }
    if (el.attr('data-decoy') !== undefined || el.attr('data-fake') !== undefined) return true;
    if (el.parents('template, noscript').size() > 0) return true;
    if (el.parents('[hidden], [inert], [aria-hidden="true"], [data-decoy], [data-fake]').size() > 0) {
      return true;
    }
    if (checkHiddenStyle) {
      if (hasHiddenStyle(el)) return true;
      const styledAnc = el.parents('[style]');
      for (let i = 0; i < styledAnc.size(); i++) {
        if (hasHiddenStyle(styledAnc.eq(i))) return true;
      }
    }
    return false;
  };

  const isDecoyForm = (form) => {
    if (isDecoyEl(form, true)) return true;
    if (form.attr('hidden') !== undefined) return true;
    const action = (form.attr('action') || '').toLowerCase();
    if (action.includes('decoy') || action.includes('fake') || action.includes('trap')) return true;
    return false;
  };

  const pickCsrfFromInputs = (inputs, checkHiddenStyle, expectedFormId) => {
    for (let i = 0; i < inputs.size(); i++) {
      const inp = inputs.eq(i);
      const name = (inp.attr('name') || '').trim().toLowerCase();
      if (name !== 'csrf') continue;
      const formAttr = inp.attr('form');
      if (formAttr && expectedFormId && formAttr !== expectedFormId) continue;
      if (formAttr && !expectedFormId && formAttr.toLowerCase().includes('decoy')) continue;
      if (isDecoyEl(inp, checkHiddenStyle)) continue;
      const val = inp.attr('value');
      if (val && val.trim().length > 0) {
        return val.trim();
      }
    }
    return null;
  };

  const forms = doc.find('form');
  const loginForms = [];
  const otherForms = [];
  for (let i = 0; i < forms.size(); i++) {
    const f = forms.eq(i);
    if (isDecoyForm(f)) continue;
    const action = (f.attr('action') || '').toLowerCase();
    const hasLoginFields = f.find('input[name="username"], input[name="password"]').size() > 0;
    const hasLoginAction = action.includes('/v2/login') || action === '/login';
    if (hasLoginAction || hasLoginFields) {
      loginForms.push({ f, priority: (hasLoginAction ? 2 : 0) + (hasLoginFields ? 1 : 0) });
    } else {
      otherForms.push(f);
    }
  }
  loginForms.sort((a, b) => b.priority - a.priority);

  for (const checkHiddenStyle of [true, false]) {
    for (const item of loginForms) {
      const fid = item.f.attr('id') || null;
      const token = pickCsrfFromInputs(item.f.find('input'), checkHiddenStyle, fid);
      if (token) return token;
      if (fid) {
        const linked = doc.find(`input[form="${fid}"]`);
        const linkedToken = pickCsrfFromInputs(linked, checkHiddenStyle, fid);
        if (linkedToken) return linkedToken;
      }
    }
    for (const f of otherForms) {
      const token = pickCsrfFromInputs(f.find('input'), checkHiddenStyle, f.attr('id') || null);
      if (token) return token;
    }
    const anyToken = pickCsrfFromInputs(doc.find('input'), checkHiddenStyle, null);
    if (anyToken) return anyToken;
  }

  return null;
}

function findInStockVariant(payload) {
  if (!payload || typeof payload !== 'object') return null;
  const data = payload.data && typeof payload.data === 'object' ? payload.data : payload;
  let products = [];
  if (Array.isArray(data.products)) {
    products = data.products;
  } else if (data.product) {
    products = [data.product];
  } else if (payload.product) {
    products = [payload.product];
  }
  for (const product of products) {
    if (!product || !product.id) continue;
    const variants = Array.isArray(product.variants) ? product.variants : [];
    for (const variant of variants) {
      if (variant && variant.id && variant.in_stock === true) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

export default function () {
  const username = `bench-${((__VU - 1) % 16) + 1}`;
  const jar = new http.CookieJar();
  const state = { csrf: null };

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar,
    redirects: 0,
    tags: { name: 'GET /v2/login-form' },
  });
  const formCsrf = formRes.status === 200 ? extractLoginCsrf(formRes.body) : null;
  const formOk = check(formRes, {
    'login form loaded': (r) => r.status === 200,
    'login form csrf extracted': () => Boolean(formCsrf),
  });
  if (!formOk || !formCsrf) {
    return;
  }

  let loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      jar,
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
      tags: { name: 'POST /v2/login' },
    }
  );
  if (loginRes.status >= 300 && loginRes.status < 400) {
    const location = getHeader(loginRes, 'location');
    const redirectUrl = resolveUrl(BASE_URL, location);
    const hasLocation = check(loginRes, {
      'login redirect has location': () => Boolean(redirectUrl),
    });
    if (!hasLocation || !redirectUrl) {
      return;
    }
    loginRes = http.get(redirectUrl, {
      jar,
      redirects: 0,
      tags: { name: 'GET /v2/login/redirect' },
    });
  }
  const loginBody = parseJsonSafe(loginRes);
  updateCsrf(state, loginBody);
  const loginOk = check(loginRes, {
    'login succeeded': (r) => r.status === 200,
    'session csrf present': () => Boolean(state.csrf),
  });
  if (!loginOk) {
    return;
  }

  let catRes = http.get(`${BASE_URL}/v2/catalog`, {
    jar,
    tags: { name: 'GET /v2/catalog' },
  });
  let catBody = parseJsonSafe(catRes);
  let selected = catRes.status === 200 ? findInStockVariant(catBody) : null;
  let pagesVisited = 0;
  while (!selected && catRes.status === 200 && catBody && catBody.next && pagesVisited < 3) {
    const nextUrl = resolveUrl(BASE_URL, catBody.next);
    if (!nextUrl) break;
    catRes = http.get(nextUrl, {
      jar,
      tags: { name: 'GET /v2/catalog/page' },
    });
    catBody = parseJsonSafe(catRes);
    selected = catRes.status === 200 ? findInStockVariant(catBody) : null;
    pagesVisited += 1;
  }
  const catalogOk = check(catRes, {
    'catalog loaded': (r) => r.status === 200,
    'in-stock variant found': () => Boolean(selected),
  });
  if (!catalogOk || !selected) {
    return;
  }

  const cartRes = http.post(
    `${BASE_URL}/v2/carts`,
    JSON.stringify({
      product_id: selected.product_id,
      variant_id: selected.variant_id,
    }),
    {
      jar,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      tags: { name: 'POST /v2/carts' },
    }
  );
  const cartBody = parseJsonSafe(cartRes);
  updateCsrf(state, cartBody);
  const cartId = cartBody && cartBody.id ? String(cartBody.id) : null;
  let cartEtag = extractEtag(cartRes, cartBody);

  if (cartRes.status === 201 && cartId && !cartEtag) {
    const initialReadRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar,
      tags: { name: 'GET /v2/carts/{id}' },
    });
    const initialReadBody = parseJsonSafe(initialReadRes);
    updateCsrf(state, initialReadBody);
    cartEtag = extractEtag(initialReadRes, initialReadBody);
  }

  const cartOk = check(cartRes, {
    'cart created': (r) => r.status === 201 && Boolean(cartId),
    'initial etag extracted': () => Boolean(cartEtag),
  });
  if (!cartOk || !cartId || !cartEtag) {
    return;
  }

  const patchPayload = JSON.stringify({ quantity: QUANTITY });
  let patchRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, patchPayload, {
    jar,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'If-Match': cartEtag,
    },
    responseCallback: http.expectedStatuses(200, 412),
    tags: { name: 'PATCH /v2/carts/{id}' },
  });
  let patchBody = parseJsonSafe(patchRes);
  updateCsrf(state, patchBody);

  if (patchRes.status === 412) {
    const rereadRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar,
      tags: { name: 'GET /v2/carts/{id}' },
    });
    const rereadBody = parseJsonSafe(rereadRes);
    updateCsrf(state, rereadBody);
    const freshEtag = extractEtag(rereadRes, rereadBody);
    const rereadOk = check(rereadRes, {
      'cart re-read after 412 succeeded': (r) => r.status === 200,
      'refreshed etag extracted': () => Boolean(freshEtag),
    });
    if (!rereadOk || !freshEtag) {
      return;
    }
    cartEtag = freshEtag;

    patchRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, patchPayload, {
      jar,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'If-Match': cartEtag,
      },
      tags: { name: 'PATCH /v2/carts/{id}' },
    });
    patchBody = parseJsonSafe(patchRes);
    updateCsrf(state, patchBody);
  }

  const returnedQty =
    patchBody && patchBody.quantity !== undefined
      ? Number(patchBody.quantity)
      : patchBody && patchBody.cart && patchBody.cart.quantity !== undefined
      ? Number(patchBody.cart.quantity)
      : null;

  const patchOk = check(patchRes, {
    'cart updated': (r) => r.status === 200,
    'cart quantity preserved': () => returnedQty === null || returnedQty === QUANTITY,
  });
  if (!patchOk) {
    return;
  }

  const updatedEtag = extractEtag(patchRes, patchBody);
  if (updatedEtag) {
    cartEtag = updatedEtag;
  } else {
    const postPatchRead = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar,
      tags: { name: 'GET /v2/carts/{id}' },
    });
    const postPatchBody = parseJsonSafe(postPatchRead);
    updateCsrf(state, postPatchBody);
    const syncedEtag = extractEtag(postPatchRead, postPatchBody);
    if (syncedEtag) {
      cartEtag = syncedEtag;
    }
  }

  const idempotencyKey = `order-${cartId}-vu${__VU}-it${__ITER}`;
  const orderPayload = JSON.stringify({ cart_id: cartId });
  let orderRes = http.post(`${BASE_URL}/v2/orders`, orderPayload, {
    jar,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idempotencyKey,
      'If-Match': cartEtag,
    },
    tags: { name: 'POST /v2/orders' },
  });
  let orderBody = parseJsonSafe(orderRes);
  updateCsrf(state, orderBody);

  if (orderRes.status === 412) {
    const rereadOrderRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar,
      tags: { name: 'GET /v2/carts/{id}' },
    });
    const rereadOrderBody = parseJsonSafe(rereadOrderRes);
    updateCsrf(state, rereadOrderBody);
    const freshOrderEtag = extractEtag(rereadOrderRes, rereadOrderBody);
    if (rereadOrderRes.status === 200 && freshOrderEtag) {
      cartEtag = freshOrderEtag;
      orderRes = http.post(`${BASE_URL}/v2/orders`, orderPayload, {
        jar,
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'Idempotency-Key': idempotencyKey,
          'If-Match': cartEtag,
        },
        tags: { name: 'POST /v2/orders' },
      });
      orderBody = parseJsonSafe(orderRes);
      updateCsrf(state, orderBody);
    }
  }

  check(orderRes, {
    'order committed': (r) =>
      r.status === 201 && Boolean(orderBody) && orderBody.accepted === true && Boolean(orderBody.id),
  });
}

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final Pattern STRIP_NOISE = Pattern.compile(
            "<!--[\\s\\S]*?-->|<script\\b[^>]*>[\\s\\S]*?</script>|<style\\b[^>]*>[\\s\\S]*?</style>|<template\\b[^>]*>[\\s\\S]*?</template>|<noscript\\b[^>]*>[\\s\\S]*?</noscript>",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern FORM_PATTERN = Pattern.compile(
            "<form\\b((?:\"[^\"]*\"|'[^']*'|[^'\">])*)>([\\s\\S]*?)</form>",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern INPUT_PATTERN = Pattern.compile(
            "<input\\b((?:\"[^\"]*\"|'[^']*'|[^'\">])*)/?>",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern ATTR_PATTERN = Pattern.compile(
            "([a-zA-Z_:][a-zA-Z0-9_.:-]*)(?:\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+)))?"
    );

    public ModelSimulation() {
        String envBaseUrl = System.getenv("BASE_URL");
        String baseUrl = (envBaseUrl == null || envBaseUrl.isBlank()) ? "http://127.0.0.1:8000" : envBaseUrl.trim();
        while (baseUrl.endsWith("/")) {
            baseUrl = baseUrl.substring(0, baseUrl.length() - 1);
        }

        HttpProtocolBuilder httpProtocol = http
                .baseUrl(baseUrl)
                .disableFollowRedirect()
                .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

        List<Map<String, Object>> accounts = new ArrayList<>();
        for (int i = 1; i <= 16; i++) {
            Map<String, Object> row = new HashMap<>();
            row.put("username", "bench-" + i);
            row.put("password", "bench");
            accounts.add(row);
        }
        FeederBuilder<Object> accountFeeder = listFeeder(accounts).circular();

        ScenarioBuilder scn = scenario("ShopExpiryRecovery")
                .feed(accountFeeder)
                .repeat(2).on(
                        exitBlockOnFail().on(
                                exec(flushCookieJar())
                                        .exec(ModelSimulation::resetJourneyState)
                                        .exec(loginChain())
                                        .exec(catalogChain())
                                        .exec(createCartChain())
                                        .exec(ensureEtagChain())
                                        .exec(patchCartChain())
                                        .exec(createOrderChain())
                        )
                );

        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }

    private static ChainBuilder loginChain() {
        return exec(
                http("Login Form")
                        .get("/v2/login-form")
                        .check(
                                status().is(200),
                                bodyString().transform(ModelSimulation::extractLoginCsrf).not("").saveAs("csrf")
                        )
        ).exec(
                http("Login")
                        .post("/v2/login")
                        .asJson()
                        .body(StringBody(ModelSimulation::buildLoginJson))
                        .check(
                                status().in(200, 302).saveAs("loginStatus"),
                                header("Location").optional().saveAs("loginLocation"),
                                bodyString().saveAs("loginBody")
                        )
        ).exec(session -> {
            if (intVal(session, "loginStatus", 0) == 200) {
                String nextCsrf = extractCsrfFromBody(str(session, "loginBody"));
                if (!nextCsrf.isEmpty()) {
                    session = session.set("csrf", nextCsrf);
                }
            }
            return session;
        }).doIf(session -> intVal(session, "loginStatus", 0) == 302).then(
                exec(session -> {
                    if (str(session, "loginLocation").isEmpty()) {
                        return session.markAsFailed();
                    }
                    return session;
                }).exec(
                        http("Login Redirect")
                                .get(session -> str(session, "loginLocation"))
                                .check(
                                        status().is(200),
                                        bodyString().saveAs("loginRedirectBody")
                                )
                ).exec(session -> {
                    String redirectBody = str(session, "loginRedirectBody");
                    String nextCsrf = extractCsrfFromBody(redirectBody);
                    if (nextCsrf.isEmpty()) {
                        nextCsrf = extractLoginCsrf(redirectBody);
                    }
                    if (!nextCsrf.isEmpty()) {
                        session = session.set("csrf", nextCsrf);
                    }
                    return session;
                })
        );
    }

    private static ChainBuilder recoverSessionChain() {
        return exec(session -> {
            String err = extractError(str(session, "lastBody"));
            if (!"expired".equals(err) && !"session".equals(err)) {
                return session.markAsFailed();
            }
            return session
                    .set("authError", err)
                    .set("needRelogin", "session".equals(err))
                    .set("renewStatus", 0)
                    .set("renewBody", "");
        }).doIf(session -> "expired".equals(str(session, "authError"))).then(
                exec(
                        http("Session Renew")
                                .post("/v2/session/renew")
                                .asJson()
                                .header("X-CSRF-Token", session -> str(session, "csrf"))
                                .body(StringBody("{}"))
                                .check(
                                        status().in(200, 201, 401).saveAs("renewStatus"),
                                        bodyString().saveAs("renewBody"),
                                        bodyString().transform(ModelSimulation::checkRenewResponse).is(true)
                                )
                ).exec(session -> {
                    int st = intVal(session, "renewStatus", 0);
                    if (st == 200 || st == 201) {
                        String nextCsrf = extractCsrfFromBody(str(session, "renewBody"));
                        if (!nextCsrf.isEmpty()) {
                            session = session.set("csrf", nextCsrf);
                        }
                        return session.set("needRelogin", false);
                    }
                    return session.set("needRelogin", true);
                })
        ).doIf(session -> boolVal(session, "needRelogin")).then(
                loginChain()
        ).doIf(session -> !str(session, "cartId").isEmpty()).then(
                exec(
                        http("Cart Recover")
                                .post(session -> "/v2/carts/" + str(session, "cartId") + "/recover")
                                .asJson()
                                .header("X-CSRF-Token", session -> str(session, "csrf"))
                                .body(StringBody("{}"))
                                .check(
                                        status().in(200, 201),
                                        header("ETag").optional().saveAs("respEtag"),
                                        bodyString().saveAs("recoverBody")
                                )
                ).exec(session -> {
                    String recoverBody = str(session, "recoverBody");
                    String nextCsrf = extractCsrfFromBody(recoverBody);
                    if (!nextCsrf.isEmpty()) {
                        session = session.set("csrf", nextCsrf);
                    }
                    String nextEtag = str(session, "respEtag");
                    if (nextEtag.isEmpty()) {
                        nextEtag = extractEtagFromBody(recoverBody);
                    }
                    if (!nextEtag.isEmpty()) {
                        session = session.set("etag", nextEtag);
                    }
                    return session.remove("respEtag");
                })
