    private static String str(Session session, String key) {
        if (!session.contains(key)) {
            return "";
        }
        Object v = session.get(key);
        return v == null ? "" : String.valueOf(v);
    }

    private static int intVal(Session session, String key, int defaultValue) {
        if (!session.contains(key)) {
            return defaultValue;
        }
        Object v = session.get(key);
        if (v instanceof Number) {
            return ((Number) v).intValue();
        }
        if (v != null) {
            try {
                return Integer.parseInt(String.valueOf(v));
            } catch (NumberFormatException ignored) {
                return defaultValue;
            }
        }
        return defaultValue;
    }

    private static boolean boolVal(Session session, String key) {
        if (!session.contains(key)) {
            return false;
        }
        Object v = session.get(key);
        if (v instanceof Boolean) {
            return (Boolean) v;
        }
        return "true".equalsIgnoreCase(String.valueOf(v));
    }

    private static String extractLoginCsrf(String html) {
        if (html == null || html.isEmpty()) {
            return "";
        }
        String cleaned = STRIP_NOISE.matcher(html).replaceAll(" ");

        List<String> loginForms = new ArrayList<>();
        List<String> normalForms = new ArrayList<>();
        Matcher fm = FORM_PATTERN.matcher(cleaned);
        while (fm.find()) {
            String formAttrs = fm.group(1) == null ? "" : fm.group(1);
            String formBody = fm.group(2) == null ? "" : fm.group(2);
            String lowerAttrs = formAttrs.toLowerCase(Locale.ROOT);
            boolean formDecoy = lowerAttrs.contains("decoy") || lowerAttrs.contains("fake") || lowerAttrs.contains("honeypot");
            boolean formHidden = hasBooleanAttr(formAttrs, "hidden") || lowerAttrs.replaceAll("\\s+", "").contains("display:none");
            if (!formDecoy && !formHidden) {
                if (lowerAttrs.contains("login")) {
                    loginForms.add(formBody);
                } else {
                    normalForms.add(formBody);
                }
            }
        }

        for (String body : loginForms) {
            String tok = findCsrfInput(body, true);
            if (!tok.isEmpty()) {
                return tok;
            }
        }
        for (String body : normalForms) {
            String tok = findCsrfInput(body, true);
            if (!tok.isEmpty()) {
                return tok;
            }
        }
        String strict = findCsrfInput(cleaned, true);
        if (!strict.isEmpty()) {
            return strict;
        }
        return findCsrfInput(cleaned, false);
    }

    private static boolean hasBooleanAttr(String attrs, String target) {
        Matcher am = ATTR_PATTERN.matcher(attrs);
        while (am.find()) {
            String name = am.group(1).toLowerCase(Locale.ROOT);
            if (target.equals(name)) {
                String val = am.group(2) != null ? am.group(2) : (am.group(3) != null ? am.group(3) : am.group(4));
                if (val == null || !"false".equalsIgnoreCase(val)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static String findCsrfInput(String fragment, boolean strict) {
        Matcher im = INPUT_PATTERN.matcher(fragment);
        while (im.find()) {
            String attrs = im.group(1);
            if (attrs == null) {
                continue;
            }
            String name = "";
            String value = "";
            boolean disabled = false;
            boolean decoy = false;
            boolean hiddenAttr = false;

            Matcher am = ATTR_PATTERN.matcher(attrs);
            while (am.find()) {
                String attrName = am.group(1).toLowerCase(Locale.ROOT);
                String rawVal = am.group(2) != null ? am.group(2) : (am.group(3) != null ? am.group(3) : am.group(4));
                String attrVal = rawVal == null ? "" : rawVal;

                if ("name".equals(attrName)) {
                    name = attrVal;
                } else if ("value".equals(attrName)) {
                    value = attrVal;
                } else if ("disabled".equals(attrName) && (rawVal == null || !"false".equalsIgnoreCase(attrVal))) {
                    disabled = true;
                } else if ("hidden".equals(attrName) && (rawVal == null || !"false".equalsIgnoreCase(attrVal))) {
                    hiddenAttr = true;
                }

                if (attrName.contains("decoy") || attrName.contains("fake") || attrName.contains("honeypot")) {
                    decoy = true;
                }
                if (!"value".equals(attrName)) {
                    String lv = attrVal.toLowerCase(Locale.ROOT);
                    if (lv.contains("decoy") || lv.contains("fake") || lv.contains("honeypot")) {
                        decoy = true;
                    }
                }
            }

            if ("csrf".equals(name) && !value.isEmpty()) {
                if (!strict || (!disabled && !decoy && !hiddenAttr)) {
                    return unescapeHtml(value);
                }
            }
        }
        return "";
    }

    private static String unescapeHtml(String s) {
        return s.replace("&amp;", "&")
                .replace("&quot;", "\"")
                .replace("&#39;", "'")
                .replace("&apos;", "'")
                .replace("&lt;", "<")
                .replace("&gt;", ">");
    }

    private static String extractCsrfFromBody(String body) {
        Map<String, Object> m = parseJsonObject(body);
        if (m == null) {
            return "";
        }
        String c = asString(m.get("csrf"));
        if (!c.isEmpty()) {
            return c;
        }
        Map<String, Object> data = asMap(m.get("data"));
        return data != null ? asString(data.get("csrf")) : "";
    }

