    private static String[] extractCatalogChoice(String body) {
        Map<String, Object> root = parseJsonObject(body);
        if (root == null) {
            return new String[]{"", "", ""};
        }
        Map<String, Object> data = asMap(root.get("data"));
        String nextUrl = asString(root.get("next"));
        if (nextUrl.isEmpty() && data != null) {
            nextUrl = asString(data.get("next"));
        }

        List<Map<String, Object>> products = new ArrayList<>();
        if (data != null) {
            addProductCandidates(products, data.get("products"));
            addProductCandidates(products, data.get("product"));
        }
        addProductCandidates(products, root.get("products"));
        addProductCandidates(products, root.get("product"));

        for (Map<String, Object> prod : products) {
            String pid = asId(prod.get("id"));
            if (pid.isEmpty()) {
                continue;
            }
            List<Object> variants = asList(prod.get("variants"));
            if (variants == null) {
                continue;
            }
            for (Object vObj : variants) {
                Map<String, Object> variant = asMap(vObj);
                if (variant == null) {
                    continue;
                }
                if (isInStock(variant.get("in_stock"))) {
                    String vid = asId(variant.get("id"));
                    if (!vid.isEmpty()) {
                        return new String[]{pid, vid, nextUrl};
                    }
                }
            }
        }
        return new String[]{"", "", nextUrl};
    }

    private static void addProductCandidates(List<Map<String, Object>> dest, Object obj) {
        if (obj instanceof List<?>) {
            for (Object item : (List<?>) obj) {
                Map<String, Object> m = asMap(item);
                if (m != null) {
                    dest.add(m);
                }
            }
        } else {
            Map<String, Object> m = asMap(obj);
            if (m != null) {
                dest.add(m);
            }
        }
    }

    private static boolean isInStock(Object val) {
        if (val instanceof Boolean) {
            return (Boolean) val;
        }
        if (val instanceof Number) {
            return ((Number) val).doubleValue() > 0;
        }
        if (val instanceof String) {
            return "true".equalsIgnoreCase((String) val);
        }
        return false;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> asMap(Object obj) {
        return obj instanceof Map<?, ?> ? (Map<String, Object>) obj : null;
    }

    @SuppressWarnings("unchecked")
    private static List<Object> asList(Object obj) {
        return obj instanceof List<?> ? (List<Object>) obj : null;
    }

    private static String asString(Object obj) {
        return obj instanceof String ? (String) obj : "";
    }

    private static String asId(Object obj) {
        if (obj instanceof String) {
            return (String) obj;
        }
        if (obj instanceof Number) {
            return String.valueOf(obj);
        }
        return "";
    }

    private static String jsonEscape(String s) {
        StringBuilder sb = new StringBuilder(s.length() + 8);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    private static Map<String, Object> parseJsonObject(String text) {
        if (text == null || text.isEmpty()) {
            return null;
        }
        try {
            Object parsed = new JsonParser(text).parse();
            return asMap(parsed);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private static final class JsonParser {
        private final String s;
        private int pos;

        JsonParser(String s) {
            this.s = s;
            this.pos = 0;
        }

        Object parse() {
            skipWs();
            if (pos >= s.length()) {
                return null;
            }
            Object val = parseValue();
            skipWs();
            return pos == s.length() ? val : null;
        }

        private Object parseValue() {
            skipWs();
            if (pos >= s.length()) {
                throw new IllegalArgumentException("Unexpected end");
            }
            char c = s.charAt(pos);
            switch (c) {
                case '{': return parseObject();
                case '[': return parseArray();
                case '"': return parseString();
                case 't': return parseLiteral("true", Boolean.TRUE);
                case 'f': return parseLiteral("false", Boolean.FALSE);
                case 'n': return parseLiteral("null", null);
                default:
                    if (c == '-' || (c >= '0' && c <= '9')) {
                        return parseNumber();
                    }
                    throw new IllegalArgumentException("Unexpected char: " + c);
            }
        }

        private Map<String, Object> parseObject() {
            pos++;
            skipWs();
            Map<String, Object> map = new LinkedHashMap<>();
            if (pos < s.length() && s.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != '"') {
                    throw new IllegalArgumentException("Expected key");
                }
                String key = parseString();
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != ':') {
                    throw new IllegalArgumentException("Expected :");
                }
                pos++;
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos >= s.length()) {
                    throw new IllegalArgumentException("Unterminated object");
                }
                char c = s.charAt(pos++);
                if (c == '}') {
                    return map;
                }
                if (c != ',') {
                    throw new IllegalArgumentException("Expected , or }");
                }
            }
        }

        private List<Object> parseArray() {
            pos++;
            skipWs();
            List<Object> list = new ArrayList<>();
            if (pos < s.length() && s.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                list.add(parseValue());
                skipWs();
                if (pos >= s.length()) {
                    throw new IllegalArgumentException("Unterminated array");
                }
                char c = s.charAt(pos++);
                if (c == ']') {
                    return list;
                }
                if (c != ',') {
                    throw new IllegalArgumentException("Expected , or ]");
                }
            }
        }

        private String parseString() {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos++);
                if (c == '"') {
                    return sb.toString();
                }
                if (c == '\\') {
                    if (pos >= s.length()) {
                        throw new IllegalArgumentException("Unterminated escape");
                    }
                    char e = s.charAt(pos++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > s.length()) {
                                throw new IllegalArgumentException("Bad unicode escape");
                            }
                            sb.append((char) Integer.parseInt(s.substring(pos, pos + 4), 16));
                            pos += 4;
                            break;
                        default:
                            throw new IllegalArgumentException("Bad escape: " + e);
                    }
                } else {
                    sb.append(c);
                }
            }
            throw new IllegalArgumentException("Unterminated string");
        }

        private Object parseLiteral(String lit, Object val) {
            if (s.startsWith(lit, pos)) {
                pos += lit.length();
                return val;
            }
            throw new IllegalArgumentException("Expected " + lit);
        }

        private Number parseNumber() {
            int start = pos;
            if (s.charAt(pos) == '-') {
                pos++;
            }
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                pos++;
            }
            boolean isFloat = false;
            if (pos < s.length() && s.charAt(pos) == '.') {
                isFloat = true;
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                    pos++;
                }
            }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                isFloat = true;
                pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) {
                    pos++;
                }
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                    pos++;
                }
            }
            String num = s.substring(start, pos);
            if (isFloat) {
                return Double.valueOf(num);
            }
            try {
                return Long.valueOf(num);
            } catch (NumberFormatException ignored) {
                return Double.valueOf(num);
            }
        }

        private void skipWs() {
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
                    pos++;
                } else {
                    break;
                }
            }
        }
    }
}

import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    expiry: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate==1.0'],
  },
};

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const target = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === target) {
      const value = res.headers[key];
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return null;
}

function parseJsonSafe(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (_) {
    return null;
  }
}

function resolveUrl(location) {
  if (!location) return null;
  if (/^https?:\/\//i.test(location)) return location;
  if (location.startsWith('/')) return `${BASE_URL}${location}`;
  return `${BASE_URL}/${location}`;
}

function updateCsrfFromRes(state, res) {
  if (!res || res.status < 200 || res.status >= 300) return;
  const body = parseJsonSafe(res);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function updateEtagFromRes(state, res) {
  if (!res || res.status < 200 || res.status >= 300) return;
  const etag = getHeader(res, 'etag');
  if (etag) {
    state.etag = etag;
  }
}

function extractCsrfFromHtml(html) {
  if (!html) return null;
  const doc = parseHTML(html);

  const pickToken = (selection, strict) => {
    const count = selection.size();
    for (let i = 0; i < count; i++) {
      const el = selection.eq(i);
      if (el.attr('disabled') !== undefined) continue;
      if (el.parents('template').size() > 0) continue;
      if (strict) {
        if (el.attr('data-decoy') !== undefined) continue;
        if (el.attr('aria-hidden') === 'true') continue;
      }
      const val = el.attr('value');
      if (val && val.length > 0) return val;
    }
    return null;
  };

  const forms = doc.find('form');
  const formCount = forms.size();
  for (const strict of [true, false]) {
    for (let i = 0; i < formCount; i++) {
      const form = forms.eq(i);
      const action = (form.attr('action') || '').toLowerCase();
      const hasUser = form.find('input[name="username"]').size() > 0;
      if (action.includes('login') || hasUser) {
        const token = pickToken(form.find('input[name="csrf"]'), strict);
        if (token) return token;
      }
    }
    for (let i = 0; i < formCount; i++) {
      const token = pickToken(forms.eq(i).find('input[name="csrf"]'), strict);
      if (token) return token;
    }
    const token = pickToken(doc.find('input[name="csrf"]'), strict);
    if (token) return token;
  }
  return null;
}

function performLogin(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar: state.jar,
    redirects: 0,
    headers: { Accept: 'text/html' },
  });
  const formCsrf = formRes.status === 200 ? extractCsrfFromHtml(formRes.body) : null;
  const formOk = check(formRes, {
    'login form status 200': (r) => r.status === 200,
    'login form csrf extracted': () => Boolean(formCsrf),
  });
  if (!formOk) return false;

  let loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: state.username,
      password: state.password,
      csrf: formCsrf,
    }),
    {
      jar: state.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
    }
  );

  if (loginRes.status === 302) {
    const location = resolveUrl(getHeader(loginRes, 'location'));
    const hasLoc = check(loginRes, {
      'login 302 has location': () => Boolean(location),
    });
    if (!hasLoc) return false;
    loginRes = http.get(location, {
      jar: state.jar,
      redirects: 0,
      headers: { Accept: 'application/json' },
    });
  }

  const loginBody = parseJsonSafe(loginRes);
  const csrf = loginBody && typeof loginBody.csrf === 'string' ? loginBody.csrf : null;
  const loginOk = check(loginRes, {
    'login status 200': (r) => r.status === 200,
    'login returned csrf': () => Boolean(csrf),
  });
  if (!loginOk) return false;

  state.csrf = csrf;
  return true;
}

function get401Error(res) {
  const body = parseJsonSafe(res);
  if (body && typeof body.error === 'string') {
    return body.error.toLowerCase();
  }
  if (body && typeof body.code === 'string') {
    return body.code.toLowerCase();
  }
  const raw = res && res.body ? String(res.body).toLowerCase() : '';
  if (raw.includes('denied')) return 'denied';
  if (raw.includes('expired')) return 'expired';
  if (raw.includes('session')) return 'session';
  return '';
}

function recoverSessionAndCart(state, errorType) {
  let refreshed = false;

  if (errorType === 'expired') {
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
      jar: state.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'X-CSRF-Token': state.csrf || '',
      },
    });
    if (renewRes.status >= 200 && renewRes.status < 300) {
      updateCsrfFromRes(state, renewRes);
      refreshed = true;
    } else {
      refreshed = performLogin(state);
    }
  } else {
    refreshed = performLogin(state);
  }

  const refreshOk = check(refreshed, {
    'session refreshed after 401': (ok) => ok === true,
  });
  if (!refreshOk) return false;

  if (state.cartId !== null) {
    const recoverRes = http.post(
      `${BASE_URL}/v2/carts/${state.cartId}/recover`,
      JSON.stringify({}),
      {
        jar: state.jar,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
          'X-CSRF-Token': state.csrf || '',
        },
      }
    );
    const recoverOk = check(recoverRes, {
      'cart recovered after session refresh': (r) => r.status >= 200 && r.status < 300,
    });
    if (!recoverOk) return false;
    updateCsrfFromRes(state, recoverRes);
    updateEtagFromRes(state, recoverRes);
  }

  return true;
}

function withAuthRecovery(state, opFn) {
  let res = opFn();
  if (!res || res.status !== 401) {
    return res;
  }

  const errorType = get401Error(res);
  if (errorType === 'denied') {
    check(res, {
      'request not access denied': () => false,
    });
    return res;
  }

  const recovered = recoverSessionAndCart(state, errorType);
  if (!recovered) {
    return res;
  }

  return opFn();
}

function withEtagRetry(state, opFn) {
  let res = withAuthRecovery(state, opFn);
  if (res && res.status === 412 && state.cartId !== null) {
    const getRes = withAuthRecovery(state, () =>
      http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
        jar: state.jar,
        redirects: 0,
        headers: { Accept: 'application/json' },
      })
    );
    updateEtagFromRes(state, getRes);
    res = withAuthRecovery(state, opFn);
  }
  return res;
}

function findInStockVariant(body) {
  if (!body) return null;
  let products = [];
  if (body.data && Array.isArray(body.data.products)) {
    products = body.data.products;
  } else if (Array.isArray(body.products)) {
    products = body.products;
  } else if (body.data && body.data.product) {
    products = [body.data.product];
  } else if (body.product) {
    products = [body.product];
  }

  for (const product of products) {
    if (!product || !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && variant.in_stock === true && product.id !== undefined && variant.id !== undefined) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

function fetchInStockItem(state) {
  let url = `${BASE_URL}/v2/catalog`;
  let lastRes = null;
  for (let page = 0; page < 3 && url; page++) {
    const res = withAuthRecovery(state, () =>
      http.get(url, {
        jar: state.jar,
        redirects: 0,
        headers: { Accept: 'application/json' },
      })
    );
    lastRes = res;
    if (!res || res.status !== 200) {
      return { res, item: null };
    }
    const body = parseJsonSafe(res);
    const item = findInStockVariant(body);
    if (item) {
      return { res, item };
    }
    const next = (body && body.next) || (body && body.data && body.data.next) || null;
    url = next ? resolveUrl(next) : null;
  }
  return { res: lastRes, item: null };
}

export default function () {
  const userIndex = ((__VU - 1) % 16) + 1;
  const state = {
    username: `bench-${userIndex}`,
    password: 'bench',
    jar: new http.CookieJar(),
    csrf: null,
    cartId: null,
    etag: null,
  };

  if (!performLogin(state)) {
    return;
  }

  const { res: catalogRes, item } = fetchInStockItem(state);
  const catalogOk = check(catalogRes, {
    'catalog status 200': (r) => Boolean(r) && r.status === 200,
    'in-stock variant selected': () => Boolean(item),
  });
  if (!catalogOk) {
    return;
  }

  const cartRes = withAuthRecovery(state, () =>
    http.post(
      `${BASE_URL}/v2/carts`,
      JSON.stringify({
        product_id: item.product_id,
        variant_id: item.variant_id,
      }),
      {
        jar: state.jar,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
          'X-CSRF-Token': state.csrf || '',
        },
      }
    )
  );
  const cartBody = parseJsonSafe(cartRes);
  const cartOk = check(cartRes, {
    'cart created 201': (r) => Boolean(r) && r.status === 201,
    'cart id present': () => Boolean(cartBody && cartBody.id),
  });
  if (!cartOk) {
    return;
  }

  state.cartId = cartBody.id;
  updateCsrfFromRes(state, cartRes);
  updateEtagFromRes(state, cartRes);

  if (!state.etag) {
    const cartGetRes = withAuthRecovery(state, () =>
      http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
        jar: state.jar,
        redirects: 0,
        headers: { Accept: 'application/json' },
      })
    );
    updateEtagFromRes(state, cartGetRes);
  }

  const patchRes = withEtagRetry(state, () => {
    const headers = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': state.csrf || '',
    };
    if (state.etag) {
      headers['If-Match'] = state.etag;
    }
    return http.patch(
      `${BASE_URL}/v2/carts/${state.cartId}`,
      JSON.stringify({ quantity: 2 }),
      {
        jar: state.jar,
        redirects: 0,
        headers,
      }
    );
  });
  const patchOk = check(patchRes, {
    'cart patched 200': (r) => Boolean(r) && r.status >= 200 && r.status < 300,
  });
  if (!patchOk) {
    return;
  }

  updateCsrfFromRes(state, patchRes);
  updateEtagFromRes(state, patchRes);

  const idempotencyKey = `order-vu${__VU}-iter${__ITER}-cart-${state.cartId}`;
  const orderRes = withEtagRetry(state, () => {
    const headers = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': state.csrf || '',
      'Idempotency-Key': idempotencyKey,
    };
    if (state.etag) {
      headers['If-Match'] = state.etag;
    }
    return http.post(
      `${BASE_URL}/v2/orders`,
      JSON.stringify({ cart_id: state.cartId }),
      {
        jar: state.jar,
        redirects: 0,
        headers,
      }
    );
  });

  const orderBody = parseJsonSafe(orderRes);
  updateCsrfFromRes(state, orderRes);

  check(orderRes, {
    'order created 201': (r) => Boolean(r) && r.status === 201,
    'order accepted': () => Boolean(orderBody && orderBody.accepted === true && orderBody.id),
  });
}

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

  private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

  private static String resolveBaseUrl() {
    String env = System.getenv("BASE_URL");
    String url = (env == null || env.isBlank()) ? "http://127.0.0.1:8000" : env.trim();
    if (url.endsWith("/")) {
      url = url.substring(0, url.length() - 1);
    }
    return url;
  }

  private static String toJsonValue(Object value) {
    if (value == null) {
      return "null";
    }
    if (value instanceof Number || value instanceof Boolean) {
      return value.toString();
    }
    String escaped = value.toString()
        .replace("\\", "\\\\")
        .replace("\"", "\\\"");
    return "\"" + escaped + "\"";
  }

  private static String normalizeUrl(String url) {
    if (url == null) {
      return null;
    }
    if (!url.startsWith("http://") && !url.startsWith("https://") && !url.startsWith("/")) {
      return "/" + url;
    }
    return url;
  }

  private static HttpRequestActionBuilder createOrderRequest(boolean includeIfMatch) {
    HttpRequestActionBuilder req = http("create-order")
        .post("/v2/orders")
        .asJson()
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "#{idempotencyKey}");
    if (includeIfMatch) {
      req = req.header("If-Match", "#{cartEtag}");
    }
    return req
        .body(StringBody(session -> "{"
            + "\"cart_id\":" + toJsonValue(session.get("cartId")) + ","
            + "\"reservation_id\":" + toJsonValue(session.get("reservationId"))
            + "}"))
        .check(
            status().is(201),
            jmesPath("accepted").ofBoolean().is(true),
            jmesPath("id").ofObject().notNull().saveAs("orderId"),
            jmesPath("csrf").optional().saveAs("newCsrf")
        );
  }

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(resolveBaseUrl())
      .disableFollowRedirect();

  private final ChainBuilder updateCsrf = exec(session -> {
    if (session.contains("newCsrf")) {
      String fresh = session.getString("newCsrf");
      if (fresh != null && !fresh.isEmpty()) {
        return session.set("csrf", fresh).remove("newCsrf");
      }
      return session.remove("newCsrf");
    }
    return session;
  });

  private final ChainBuilder journey = exec(
      flushCookieJar(),
      exec(session -> session
          .removeAll(
              "csrf", "newCsrf", "loginStatus", "loginLocation", "loginOk",
              "productId", "variantId", "cartId", "cartEtag", "idempotencyKey",
              "statusUrl", "jobId", "jobStatus", "pollCount", "reservationId", "orderId"
          )
          .markAsSucceeded()),
      exec(
          http("login-form")
              .get("/v2/login-form")
              .check(
                  status().is(200),
                  css("input[name='csrf']", "value").notNull().saveAs("csrf")
              )
      ),
      doIf(session -> session.contains("csrf")).then(
          exec(
              http("login")
                  .post("/v2/login")
                  .asJson()
                  .body(StringBody(session -> "{"
                      + "\"username\":" + toJsonValue(session.getString("username")) + ","
                      + "\"password\":\"bench\","
                      + "\"csrf\":" + toJsonValue(session.getString("csrf"))
                      + "}"))
                  .check(
                      status().in(200, 302).saveAs("loginStatus"),
                      header("Location").optional().saveAs("loginLocation"),
                      regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("newCsrf")
                  )
          ),
          updateCsrf,
          doIfElse(session ->
              Integer.valueOf(302).equals(session.get("loginStatus"))
                  && session.contains("loginLocation")
          ).then(
              exec(session -> session.set("loginLocation", normalizeUrl(session.getString("loginLocation")))),
              exec(
                  http("login-redirect")
                      .get("#{loginLocation}")
                      .check(
                          status().is(200),
                          regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("newCsrf")
                      )
              ),
              updateCsrf,
              exec(session -> session.set("loginOk", true))
          ).orElse(
              exec(session -> Integer.valueOf(200).equals(session.get("loginStatus"))
                  ? session.set("loginOk", true)
                  : session)
          )
      ),
      doIf(session -> Boolean.TRUE.equals(session.get("loginOk"))).then(
          exec(
              http("catalog")
                  .get("/v2/catalog")
                  .check(
                      status().is(200),
                      jmesPath("data.products[?variants[?in_stock == `true`]] | [0].id")
                          .ofObject().notNull().saveAs("productId"),
                      jmesPath("data.products[?variants[?in_stock == `true`]] | [0].variants[?in_stock == `true`] | [0].id")
                          .ofObject().notNull().saveAs("variantId")
                  )
          )
      ),
      doIf(session -> session.contains("productId") && session.contains("variantId")).then(
          exec(
              http("create-cart")
                  .post("/v2/carts")
                  .asJson()
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody(session -> "{"
                      + "\"product_id\":" + toJsonValue(session.get("productId")) + ","
                      + "\"variant_id\":" + toJsonValue(session.get("variantId"))
                      + "}"))
                  .check(
                      status().is(201),
                      jmesPath("id").ofObject().notNull().saveAs("cartId"),
                      jmesPath("csrf").optional().saveAs("newCsrf"),
                      header("ETag").optional().saveAs("cartEtag")
                  )
          ),
          updateCsrf,
          exec(session -> session.set("idempotencyKey", UUID.randomUUID().toString()))
      ),
      doIf(session -> session.contains("cartId")).then(
          exec(
              http("create-reservation")
                  .post("/v2/reservations")
                  .asJson()
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody(session -> "{"
                      + "\"cart_id\":" + toJsonValue(session.get("cartId"))
                      + "}"))
                  .check(
                      status().is(202),
                      jmesPath("status_url").notNull().saveAs("statusUrl"),
                      jmesPath("job_id").ofObject().optional().saveAs("jobId"),
                      jmesPath("csrf").optional().saveAs("newCsrf")
                  )
          ),
          updateCsrf,
          exec(session -> session.contains("statusUrl")
              ? session
                  .set("statusUrl", normalizeUrl(session.getString("statusUrl")))
                  .set("pollCount", 0)
                  .set("jobStatus", "pending")
              : session)
      ),
      doIf(session -> session.contains("statusUrl")).then(
          asLongAs(session ->
              session.getInt("pollCount") < 5
                  && "pending".equals(session.getString("jobStatus"))
          ).on(
              pause(Duration.ofMillis(80)),
              exec(session -> session
                  .set("pollCount", session.getInt("pollCount") + 1)
                  .set("jobStatus", "error")
                  .remove("newCsrf")),
              doIfElse(session -> session.getInt("pollCount") < 5).then(
                  exec(
                      http("poll-reservation")
                          .get("#{statusUrl}")
                          .check(
                              status().in(200, 202),
