import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const MAX_POLLS = 5;
const MIN_POLL_INTERVAL_SEC = 0.07;

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
  thresholds: {
    checks: ['rate==1.0'],
  },
};

function safeJson(res) {
  if (!res || !res.body) {
    return null;
  }
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) {
    return '';
  }
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      const val = res.headers[keys[i]];
      return Array.isArray(val) ? String(val[0] || '') : String(val || '');
    }
  }
  return '';
}

function resolveUrl(pathOrUrl) {
  if (!pathOrUrl) {
    return '';
  }
  if (pathOrUrl.startsWith('http://') || pathOrUrl.startsWith('https://')) {
    return pathOrUrl;
  }
  const path = pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
  return `${BASE_URL}${path}`;
}

function extractCsrf(html) {
  if (!html) {
    return '';
  }
  const doc = parseHTML(html);
  const selectors = [
    'form[action*="/v2/login"] input[name="csrf"]',
    'form[action*="login"] input[name="csrf"]',
    'form input[name="csrf"]',
    'input[name="csrf"]',
  ];
  for (let s = 0; s < selectors.length; s++) {
    const matches = doc.find(selectors[s]);
    const count = matches.size();
    for (let i = 0; i < count; i++) {
      const el = matches.eq(i);
      if (
        el.attr('disabled') !== undefined ||
        el.attr('data-decoy') !== undefined ||
        el.attr('data-fake') !== undefined ||
        el.attr('aria-hidden') === 'true'
      ) {
        continue;
      }
      const val = el.attr('value');
      if (val && String(val).trim().length > 0) {
        return String(val).trim();
      }
    }
  }
  return '';
}

function extractJobIdFromUrl(url) {
  if (!url) {
    return '';
  }
  const clean = url.split('?')[0].replace(/\/+$/, '');
  const parts = clean.split('/').filter(Boolean);
  if (parts.length === 0) {
    return '';
  }
  const last = parts[parts.length - 1];
  if (last === 'status' && parts.length >= 2) {
    return parts[parts.length - 2];
  }
  return last;
}

function findInStockVariant(body) {
  if (!body) {
    return null;
  }
  let products = [];
  if (body.data && Array.isArray(body.data.products)) {
    products = body.data.products;
  } else if (Array.isArray(body.products)) {
    products = body.products;
  } else if (body.data && body.data.product) {
    products = [body.data.product];
  } else if (body.product) {
    products = [body.product];
  }

  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || !Array.isArray(product.variants)) {
      continue;
    }
    for (let j = 0; j < product.variants.length; j++) {
      const variant = product.variants[j];
      if (variant && variant.in_stock === true && product.id != null && variant.id != null) {
        return { productId: product.id, variantId: variant.id };
      }
    }
  }
  return null;
}

export default function () {
  const jar = new http.CookieJar();
  const username = `bench-${((__VU - 1) % 16) + 1}`;
  let csrf = '';

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar,
    headers: { Accept: 'text/html' },
  });
  csrf = extractCsrf(formRes.body);
  const formOk = check(formRes, {
    'login form status 200': (r) => r.status === 200,
    'login form csrf extracted': () => Boolean(csrf),
  });
  if (!formOk) {
    return;
  }

  let loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf }),
    {
      jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
    }
  );
  if (loginRes.status >= 300 && loginRes.status < 400) {
    const location = getHeader(loginRes, 'Location');
    if (location) {
      loginRes = http.get(resolveUrl(location), {
        jar,
        redirects: 0,
        headers: { Accept: 'application/json' },
      });
    }
  }
  const loginBody = safeJson(loginRes);
  if (loginBody && loginBody.csrf) {
    csrf = loginBody.csrf;
  }
  const loginOk = check(loginRes, {
    'login status 200': (r) => r.status === 200,
    'login csrf present': () => Boolean(csrf),
  });
  if (!loginOk) {
    return;
  }

  let selection = null;
  let catalogUrl = `${BASE_URL}/v2/catalog`;
  let catalogStatusOk = false;
  for (let page = 0; page < 3 && catalogUrl && !selection; page++) {
    const catalogRes = http.get(catalogUrl, {
      jar,
      headers: { Accept: 'application/json' },
    });
    catalogStatusOk = catalogRes.status === 200;
    if (!catalogStatusOk) {
      break;
    }
    const catalogBody = safeJson(catalogRes);
    selection = findInStockVariant(catalogBody);
    catalogUrl = catalogBody && catalogBody.next ? resolveUrl(catalogBody.next) : '';
  }
  const catalogOk = check(selection, {
    'catalog status 200': () => catalogStatusOk,
    'catalog in-stock variant found': (s) => Boolean(s && s.productId != null && s.variantId != null),
  });
  if (!catalogOk || !selection) {
    return;
  }

  const cartRes = http.post(
    `${BASE_URL}/v2/carts`,
    JSON.stringify({
      product_id: selection.productId,
      variant_id: selection.variantId,
    }),
    {
      jar,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  const cartBody = safeJson(cartRes);
  if (cartBody && cartBody.csrf) {
    csrf = cartBody.csrf;
  }
  const cartId = cartBody && cartBody.id != null ? cartBody.id : '';
  let etag = getHeader(cartRes, 'ETag');
  const cartOk = check(cartRes, {
    'cart created 201': (r) => r.status === 201,
    'cart id present': () => Boolean(cartId),
  });
  if (!cartOk) {
    return;
  }

  const reserveRes = http.post(
    `${BASE_URL}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    {
      jar,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  const reserveBody = safeJson(reserveRes);
  if (reserveBody && reserveBody.csrf) {
    csrf = reserveBody.csrf;
  }
  const statusUrl =
    (reserveBody && (reserveBody.status_url || reserveBody.poll_url)) ||
    getHeader(reserveRes, 'Location');
  const jobId =
    (reserveBody && (reserveBody.job_id || reserveBody.id)) ||
    extractJobIdFromUrl(statusUrl);

  const jobCreated = check(reserveRes, {
    'reservation job created 202': (r) => r.status === 202,
    'reservation status_url present': () => Boolean(statusUrl),
    'reservation job_id present': () => Boolean(jobId),
  });
  if (!jobCreated) {
    return;
  }

  const pollUrl = resolveUrl(statusUrl);
  let waitSec = MIN_POLL_INTERVAL_SEC;
  if (reserveBody && typeof reserveBody.poll_interval === 'number' && reserveBody.poll_interval > 0) {
    waitSec = Math.max(waitSec, Math.min(reserveBody.poll_interval, 1));
  }

  let jobStatus = 'pending';
  let reservationId = '';
  let pollCount = 0;

  for (let i = 0; i < MAX_POLLS; i++) {
    sleep(waitSec);
    pollCount += 1;

    const pollRes = http.get(pollUrl, {
      jar,
      headers: { Accept: 'application/json' },
    });
    const pollStatusOk = check(pollRes, {
      'reservation poll status 200': (r) => r.status === 200,
    });
    if (!pollStatusOk) {
      jobStatus = 'failed';
      break;
    }

    const pollBody = safeJson(pollRes);
    if (pollBody && pollBody.csrf) {
      csrf = pollBody.csrf;
    }
    jobStatus = pollBody && pollBody.status ? String(pollBody.status).toLowerCase() : '';

    if (jobStatus === 'ready') {
      reservationId = pollBody && pollBody.reservation_id ? String(pollBody.reservation_id) : '';
      break;
    }
    if (
      jobStatus === 'failed' ||
      jobStatus === 'error' ||
      jobStatus === 'cancelled' ||
      jobStatus === 'expired'
    ) {
      break;
    }

    const retryAfter = parseFloat(getHeader(pollRes, 'Retry-After'));
    if (!Number.isNaN(retryAfter) && retryAfter > 0) {
      waitSec = Math.max(waitSec, Math.min(retryAfter, 1));
    }
    if (pollBody && typeof pollBody.poll_interval === 'number' && pollBody.poll_interval > 0) {
      waitSec = Math.max(waitSec, Math.min(pollBody.poll_interval, 1));
    }
  }

  const reservationReady = check(
    { jobStatus, reservationId, pollCount },
    {
      'reservation ready with reservation_id': (d) =>
        d.jobStatus === 'ready' && Boolean(d.reservationId),
      'reservation polls within 1..5': (d) =>
        d.pollCount >= 1 && d.pollCount <= MAX_POLLS,
    }
  );
  if (!reservationReady || jobStatus !== 'ready' || !reservationId) {
    return;
  }

  const idempotencyKey = `order-${cartId}`;
  const orderPayload = JSON.stringify({
    cart_id: cartId,
    reservation_id: reservationId,
  });

  function sendOrder(currentEtag) {
    const headers = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idempotencyKey,
    };
    if (currentEtag) {
      headers['If-Match'] = currentEtag;
    }
    return http.post(`${BASE_URL}/v2/orders`, orderPayload, {
      jar,
      headers,
    });
  }

  let orderRes = sendOrder(etag);
  if (orderRes.status === 412) {
    const cartGetRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      jar,
      headers: { Accept: 'application/json' },
    });
    const freshEtag = getHeader(cartGetRes, 'ETag');
    if (freshEtag) {
      etag = freshEtag;
    }
    orderRes = sendOrder(etag);
  }

  const orderBody = safeJson(orderRes);
  if (orderBody && orderBody.csrf) {
    csrf = orderBody.csrf;
  }
  check(orderRes, {
    'order created 201': (r) => r.status === 201,
    'order accepted with id': () =>
      Boolean(orderBody && orderBody.accepted === true && orderBody.id != null),
  });
}

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

    private final AtomicInteger userSeq = new AtomicInteger(0);

    private static String escapeJson(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    public ModelSimulation() {
        String envBaseUrl = System.getenv("BASE_URL");
        String baseUrl = (envBaseUrl == null || envBaseUrl.isEmpty())
            ? "http://127.0.0.1:8000"
            : envBaseUrl;

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect();

        ChainBuilder journey = exec(flushCookieJar())
            .exec(session -> session
                .set("csrf", "MISSING")
                .set("cart", "MISSING")
                .set("etag", "MISSING")
                .set("hasCart", "false")
                .set("grant", "MISSING")
                .set("product", "MISSING")
                .set("variant", "MISSING")
                .removeAll("form", "location", "selectedItem")
            )
            .exec(
                http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(css("input[name=csrf][value]", "value").exists().saveAs("form"))
                    .check(header("ETag").optional().saveAs("etag"))
            )
            .exec(
                http("POST /v2/login")
                    .post("/v2/login")
                    .header("Content-Type", "application/json")
                    .body(StringBody(session ->
                        "{\"username\":\"" + escapeJson(session.getString("username"))
                            + "\",\"password\":\"bench\",\"csrf\":\"" + escapeJson(session.getString("form")) + "\"}"
                    ))
                    .check(status().in(200, 302))
                    .check(regex("\"csrf\"\\s*:").exists())
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("Location").optional().saveAs("location"))
                    .check(header("ETag").optional().saveAs("etag"))
            )
            .doIf(session -> {
                String loc = session.getString("location");
                return loc != null && !loc.isEmpty();
            }).then(
                exec(
                    http("GET login redirect")
                        .get("#{location}")
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                        .check(header("ETag").optional().saveAs("etag"))
                )
            )
            .exec(
                http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("ETag").optional().saveAs("etag"))
                    .check(
                        jsonPath("$.data.products[*]")
                            .ofMap()
                            .findAll()
                            .transform(products -> {
                                if (products != null) {
                                    for (Map<String, Object> product : products) {
                                        Object pid = product.get("id");
                                        Object variantsObj = product.get("variants");
                                        if (pid != null && variantsObj instanceof List) {
                                            for (Object item : (List<?>) variantsObj) {
                                                if (item instanceof Map) {
                                                    Map<?, ?> variant = (Map<?, ?>) item;
                                                    if (Boolean.TRUE.equals(variant.get("in_stock")) && variant.get("id") != null) {
                                                        return pid.toString() + "\u001F" + variant.get("id").toString();
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                return "";
                            })
                            .not("")
                            .saveAs("selectedItem")
                    )
            )
            .exec(session -> {
                String selected = session.getString("selectedItem");
                if (selected != null && selected.contains("\u001F")) {
                    String[] parts = selected.split("\u001F", 2);
                    return session.set("product", parts[0]).set("variant", parts[1]);
                }
                return session;
            })
            .exec(
                http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session -> {
                        String product = escapeJson(session.getString("product"));
                        String variant = escapeJson(session.getString("variant"));
                        String grant = session.getString("grant");
                        if (grant != null && !grant.isEmpty() && !"MISSING".equals(grant)) {
                            return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant
                                + "\",\"grant_id\":\"" + escapeJson(grant) + "\"}";
                        }
                        return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\"}";
                    }))
                    .check(status().is(201))
                    .check(regex("\"id\"\\s*:\\s*\"cart-").exists())
                    .check(jsonPath("$.id").exists().saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("ETag").optional().saveAs("etag"))
            )
            .exec(session -> session.set("hasCart", "true"))
            .exec(
                http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .header("Idempotency-Key", "#{cart}")
                    .body(StringBody(session ->
                        "{\"cart_id\":\"" + escapeJson(session.getString("cart")) + "\"}"
                    ))
                    .check(status().is(201))
                    .check(regex("\"accepted\"\\s*:\\s*true").exists())
                    .check(jsonPath("$.accepted").ofBoolean().is(true))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(header("ETag").optional().saveAs("etag"))
            );

        ScenarioBuilder scn = scenario("ShopFlow")
            .exec(session -> session.set("username", "bench-" + userSeq.incrementAndGet()))
            .repeat(2).on(journey);

        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}

