import http from 'k6/http';
import { check } from 'k6';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function getHeader(res, name) {
  if (!res || !res.headers) {
    return null;
  }
  const target = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === target) {
      const val = res.headers[key];
      return typeof val === 'string' ? val.trim() : val;
    }
  }
  return null;
}

function parseJson(res) {
  if (!res || !res.body) {
    return null;
  }
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function extractFormCsrf(html) {
  if (!html) {
    return null;
  }
  const doc = parseHTML(html);
  const formInputs = doc.find('form input[name="csrf"]:not([disabled])');
  for (let i = 0; i < formInputs.size(); i++) {
    const val = formInputs.eq(i).attr('value');
    if (val) {
      return val;
    }
  }
  const anyInputs = doc.find('input[name="csrf"]:not([disabled])');
  for (let i = 0; i < anyInputs.size(); i++) {
    const val = anyInputs.eq(i).attr('value');
    if (val) {
      return val;
    }
  }
  const match = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i.exec(html);
  return match ? match[1] : null;
}

function resolveUrl(location) {
  if (location.startsWith('http://') || location.startsWith('https://')) {
    return location;
  }
  return `${BASE_URL}${location.startsWith('/') ? '' : '/'}${location}`;
}

export default function () {
  const jar = new http.CookieJar();
  let csrf = null;
  let etag = null;
  let grantId = null;

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar,
    redirects: 0,
    timeout: '5s',
  });
  const formCsrf = extractFormCsrf(formRes.body);
  const formEtag = getHeader(formRes, 'etag');
  if (formEtag) {
    etag = formEtag;
  }
  const formOk = check(formRes, {
    'login-form status 200': (r) => r.status === 200,
    'login-form csrf extracted': () => Boolean(formCsrf),
  });
  if (!formOk) {
    return;
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: `bench-${__VU}`,
      password: 'bench',
      csrf: formCsrf,
    }),
    {
      headers: {
        'Content-Type': 'application/json',
      },
      jar,
      redirects: 0,
      timeout: '5s',
    }
  );

  let finalLoginRes = loginRes;
  const loginBody = parseJson(loginRes);
  if (loginBody && loginBody.csrf) {
    csrf = loginBody.csrf;
  }
  const loginEtag = getHeader(loginRes, 'etag');
  if (loginEtag) {
    etag = loginEtag;
  }

  const location = getHeader(loginRes, 'location');
  if (location) {
    finalLoginRes = http.get(resolveUrl(location), {
      jar,
      redirects: 0,
      timeout: '5s',
    });
    const redirectBody = parseJson(finalLoginRes);
    if (redirectBody && redirectBody.csrf) {
      csrf = redirectBody.csrf;
    }
    if (redirectBody && redirectBody.grant_id) {
      grantId = redirectBody.grant_id;
    }
    const redirectEtag = getHeader(finalLoginRes, 'etag');
    if (redirectEtag) {
      etag = redirectEtag;
    }
  }

  const loginOk = check(finalLoginRes, {
    'login status 200': (r) => r.status === 200,
    'login csrf present': () => Boolean(csrf),
  });
  if (!loginOk) {
    return;
  }

  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    jar,
    redirects: 0,
    timeout: '5s',
  });
  const catalogBody = parseJson(catalogRes);
  if (catalogBody && catalogBody.csrf) {
    csrf = catalogBody.csrf;
  }
  const catalogEtag = getHeader(catalogRes, 'etag');
  if (catalogEtag) {
    etag = catalogEtag;
  }

  let productId = null;
  let variantId = null;
  const products = (catalogBody && catalogBody.data && catalogBody.data.products) || [];
  for (let i = 0; i < products.length && !productId; i++) {
    const product = products[i];
    const variants = (product && product.variants) || [];
    for (let j = 0; j < variants.length; j++) {
      if (variants[j] && variants[j].in_stock === true) {
        productId = product.id;
        variantId = variants[j].id;
        break;
      }
    }
  }

  const catalogOk = check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
    'catalog in-stock item found': () => Boolean(productId && variantId),
  });
  if (!catalogOk) {
    return;
  }

  const cartPayload = {
    product_id: productId,
    variant_id: variantId,
  };
  if (grantId) {
    cartPayload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(cartPayload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    jar,
    redirects: 0,
    timeout: '5s',
  });
  const cartBody = parseJson(cartRes);
  if (cartBody && cartBody.csrf) {
    csrf = cartBody.csrf;
  }
  const cartEtag = getHeader(cartRes, 'etag');
  if (cartEtag) {
    etag = cartEtag;
  }
  const cartId = cartBody && typeof cartBody.id === 'string' ? cartBody.id : null;

  const cartOk = check(cartRes, {
    'cart status 201': (r) => r.status === 201,
    'cart id created': () => Boolean(cartId && cartId.startsWith('cart-')),
  });
  if (!cartOk) {
    return;
  }

  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': cartId,
  };
  if (etag) {
    orderHeaders['If-Match'] = etag;
  }

  const orderRes = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    {
      headers: orderHeaders,
      jar,
      redirects: 0,
      timeout: '5s',
    }
  );
  const orderBody = parseJson(orderRes);
  if (orderBody && orderBody.csrf) {
    csrf = orderBody.csrf;
  }
  const orderEtag = getHeader(orderRes, 'etag');
  if (orderEtag) {
    etag = orderEtag;
  }

  check(orderRes, {
    'order status 201': (r) => r.status === 201,
    'order accepted true': () => Boolean(orderBody && orderBody.accepted === true),
  });
}

import os
import re
from html.parser import HTMLParser
from typing import Optional

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

TARGET_USERS = 2
ITERATIONS_PER_USER = 2
REQUEST_TIMEOUT = (2.0, 3.0)
MAX_RUN_SECONDS = 60.0

_CSRF_INPUT_RE = re.compile(
    r"""<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
    re.IGNORECASE,
)


class _CsrfFormParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.csrf: Optional[str] = None
        self._skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, Optional[str]]]) -> None:
        lower = tag.lower()
        if lower in ("template", "noscript"):
            self._skip_depth += 1
            return
        if self._skip_depth > 0 or self.csrf is not None or lower != "input":
            return
        attr_map = {k.lower(): v for k, v in attrs if k}
        if attr_map.get("name") == "csrf" and attr_map.get("value") and "disabled" not in attr_map:
            self.csrf = attr_map["value"]

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in ("template", "noscript") and self._skip_depth > 0:
            self._skip_depth -= 1


def _extract_form_csrf(html_text: str) -> Optional[str]:
    parser = _CsrfFormParser()
    parser.feed(html_text)
    parser.close()
    if parser.csrf:
        return parser.csrf
    match = _CSRF_INPUT_RE.search(html_text)
    return match.group(1) if match else None


def _parse_json(resp) -> dict:
    try:
        data = resp.json()
        return data if isinstance(data, dict) else {}
    except ValueError:
        return {}


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
    wait_time = constant(0)

    _next_user_id = 0
    _completed_users = 0

    def on_start(self) -> None:
        ShopUser._next_user_id += 1
        self.user_id = ShopUser._next_user_id
        self.username = f"bench-{((self.user_id - 1) % 16) + 1}"
        self.iterations_done = 0
        self._completed = False
        if self.user_id > TARGET_USERS:
            self._completed = True
            raise StopUser()

    def on_stop(self) -> None:
        if not self._completed and self.user_id <= TARGET_USERS:
            self._completed = True
            ShopUser._completed_users += 1

    def _finish_user(self) -> None:
        if not self._completed and self.user_id <= TARGET_USERS:
            self._completed = True
            ShopUser._completed_users += 1
        raise StopUser()

    @task
    def shop_journey(self) -> None:
        if self.iterations_done >= ITERATIONS_PER_USER:
            self._finish_user()

        try:
            self._run_journey()
        finally:
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS_PER_USER:
                self._finish_user()

    def _run_journey(self) -> None:
        self.client.cookies.clear()
        csrf: Optional[str] = None
        etag: Optional[str] = None
        grant_id: Optional[str] = None

        form_csrf: Optional[str] = None
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code == 0:
                return
            if resp.headers.get("ETag"):
                etag = resp.headers["ETag"].strip()
            data = _parse_json(resp)
            if isinstance(data.get("csrf"), str) and data["csrf"]:
                csrf = data["csrf"]
            form_csrf = _extract_form_csrf(resp.text)
            if resp.status_code != 200 or not form_csrf:
                resp.failure(
                    f"login-form failed: status={resp.status_code}, csrf_found={bool(form_csrf)}"
                )
                return
            resp.success()

        location: Optional[str] = None
        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            headers={"Content-Type": "application/json"},
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code == 0:
                return
            if resp.headers.get("ETag"):
                etag = resp.headers["ETag"].strip()
            data = _parse_json(resp)
            if isinstance(data.get("csrf"), str) and data["csrf"]:
                csrf = data["csrf"]
            loc_header = resp.headers.get("Location")
            if resp.status_code == 302 and loc_header:
                location = loc_header.strip()
                resp.success()
            elif resp.status_code == 200 and csrf:
                resp.success()
            else:
                resp.failure(
                    f"login failed: status={resp.status_code}, has_csrf={bool(csrf)}"
                )
                return

        if location:
            redirect_headers: dict[str, str] = {}
            if csrf:
                redirect_headers["X-CSRF-Token"] = csrf
            with self.client.get(
                location,
                headers=redirect_headers,
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                if resp.status_code == 0:
                    return
                if resp.headers.get("ETag"):
                    etag = resp.headers["ETag"].strip()
                data = _parse_json(resp)
                if isinstance(data.get("csrf"), str) and data["csrf"]:
                    csrf = data["csrf"]
                if isinstance(data.get("grant_id"), str) and data["grant_id"]:
                    grant_id = data["grant_id"]
                if resp.status_code != 200 or not csrf:
                    resp.failure(
                        f"login redirect failed: status={resp.status_code}, has_csrf={bool(csrf)}"
                    )
                    return
                resp.success()

        product_id: Optional[str] = None
        variant_id: Optional[str] = None
        with self.client.get(
            "/v2/catalog",
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code == 0:
                return
            if resp.headers.get("ETag"):
                etag = resp.headers["ETag"].strip()
            data = _parse_json(resp)
            if isinstance(data.get("csrf"), str) and data["csrf"]:
                csrf = data["csrf"]
            products = (data.get("data") or {}).get("products") or []
            for product in products:
                if not isinstance(product, dict):
                    continue
                pid = product.get("id")
                if not pid:
                    continue
                for variant in product.get("variants") or []:
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock") is True
                        and variant.get("id")
                    ):
                        product_id = str(pid)
                        variant_id = str(variant["id"])
                        break
                if product_id and variant_id:
                    break
            if resp.status_code != 200 or not product_id or not variant_id:
                resp.failure(
                    f"catalog failed: status={resp.status_code}, product={product_id}, variant={variant_id}"
                )
                return
            resp.success()

        cart_id: Optional[str] = None
        cart_payload: dict[str, str] = {
            "product_id": product_id,
            "variant_id": variant_id,
        }
        if grant_id:
            cart_payload["grant_id"] = grant_id
        cart_headers = {"Content-Type": "application/json"}
        if csrf:
            cart_headers["X-CSRF-Token"] = csrf
        with self.client.post(
            "/v2/carts",
            json=cart_payload,
            headers=cart_headers,
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code == 0:
                return
            if resp.headers.get("ETag"):
                etag = resp.headers["ETag"].strip()
            data = _parse_json(resp)
            if isinstance(data.get("csrf"), str) and data["csrf"]:
                csrf = data["csrf"]
            raw_cart_id = data.get("id")
            if isinstance(raw_cart_id, str) and raw_cart_id.startswith("cart-"):
                cart_id = raw_cart_id
            if resp.status_code != 201 or not cart_id:
                resp.failure(
                    f"create cart failed: status={resp.status_code}, cart_id={raw_cart_id}"
                )
                return
            resp.success()

        order_headers = {
            "Content-Type": "application/json",
            "Idempotency-Key": cart_id,
        }
        if csrf:
            order_headers["X-CSRF-Token"] = csrf
        if etag:
            order_headers["If-Match"] = etag
        with self.client.post(
            "/v2/orders",
            json={"cart_id": cart_id},
            headers=order_headers,
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code == 0:
                return
            if resp.headers.get("ETag"):
                etag = resp.headers["ETag"].strip()
            data = _parse_json(resp)
            if isinstance(data.get("csrf"), str) and data["csrf"]:
                csrf = data["csrf"]
            if resp.status_code != 201 or data.get("accepted") is not True:
                resp.failure(
                    f"order failed: status={resp.status_code}, accepted={data.get('accepted')}"
                )
                return
            resp.success()


class ShopLoadShape(LoadTestShape):
    def __init__(self) -> None:
        super().__init__()
        ShopUser._next_user_id = 0
        ShopUser._completed_users = 0

    def tick(self) -> Optional[tuple[int, float]]:
        if ShopUser._completed_users >= TARGET_USERS:
            return None
        if self.get_run_time() >= MAX_RUN_SECONDS:
            return None
        return (TARGET_USERS, float(TARGET_USERS))

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.List;
import java.util.Map;

public class ModelSimulation extends Simulation {

    private static ChainBuilder updateTokens() {
        return exec(session -> {
            Session updated = session;
            String newCsrf = updated.getString("newCsrf");
            if (newCsrf != null && !newCsrf.isEmpty()) {
                updated = updated.set("csrf", newCsrf);
            }
            String newEtag = updated.getString("newEtag");
            if (newEtag != null && !newEtag.isEmpty()) {
                updated = updated.set("etag", newEtag);
            }
            return updated.removeAll("newCsrf", "newEtag");
        });
    }

    private static ChainBuilder doLogin() {
        return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name='csrf']", "value").saveAs("formCsrf"))
        ).exec(
            http("POST /v2/login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{formCsrf}\"}"))
                .check(status().in(200, 302))
                .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                .check(header("Location").optional().saveAs("location"))
                .check(header("ETag").optional().saveAs("newEtag"))
        ).exec(updateTokens())
        .doIf(session -> session.contains("location")).then(
            exec(
                http("GET login redirect")
                    .get("#{location}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                    .check(header("ETag").optional().saveAs("newEtag"))
            )
            .exec(updateTokens())
            .exec(session -> session.remove("location"))
        ).exec(session -> session.contains("csrf") ? session : session.markAsFailed());
    }

    private static ChainBuilder selectInStockProduct() {
        return exec(session -> {
            List<Map<String, Object>> products = session.getList("products");
            String chosenProduct = null;
            String chosenVariant = null;
            if (products != null) {
                for (Map<String, Object> product : products) {
                    Object variantsObj = product.get("variants");
                    if (variantsObj instanceof List<?>) {
                        for (Object variantObj : (List<?>) variantsObj) {
                            if (variantObj instanceof Map<?, ?>) {
                                Map<?, ?> variant = (Map<?, ?>) variantObj;
                                if (Boolean.TRUE.equals(variant.get("in_stock"))) {
                                    chosenProduct = String.valueOf(product.get("id"));
                                    chosenVariant = String.valueOf(variant.get("id"));
                                    break;
                                }
                            }
                        }
                    }
                    if (chosenProduct != null) {
                        break;
                    }
                }
            }
            if (chosenProduct == null || chosenVariant == null) {
                return session.markAsFailed();
            }
            return session
                .set("product", chosenProduct)
                .set("variant", chosenVariant)
                .remove("products");
        });
    }

    public ModelSimulation() {
        String baseUrl = System.getenv("BASE_URL");
        if (baseUrl == null || baseUrl.isEmpty()) {
            baseUrl = "http://127.0.0.1:8000";
        }

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

        FeederBuilder.FileBased<Object> accountsFeeder = jsonFile("/fixtures/accounts.json").queue();

        ChainBuilder journey = exec(flushCookieJar())
            .exec(session -> session
                .removeAll(
                    "csrf", "formCsrf", "cart", "etag", "grant", "location",
                    "product", "variant", "products", "newCsrf", "newEtag",
                    "errorType", "renewStatus"
                )
                .set("hasCart", false)
                .set("lastStatus", 0)
            )
            .exec(doLogin())
            .exec(
                http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(header("ETag").optional().saveAs("newEtag"))
                    .check(jsonPath("$.data.products[*]").ofMap().findAll().saveAs("products"))
            )
            .exec(updateTokens())
            .exec(selectInStockProduct())
            .exec(
                http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session -> {
                        String product = session.getString("product");
                        String variant = session.getString("variant");
                        String grant = session.getString("grant");
                        if (grant != null && !grant.isEmpty()) {
                            return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\",\"grant_id\":\"" + grant + "\"}";
                        }
                        return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\"}";
                    }))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(header("ETag").optional().saveAs("newEtag"))
            )
            .exec(updateTokens())
            .exec(session -> session.set("hasCart", true).set("lastStatus", 0).removeAll("errorType", "renewStatus"))
            .exec(
                http("PATCH /v2/carts/{id}")
                    .patch("/v2/carts/#{cart}")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .body(StringBody("{\"quantity\":#{quantity}}"))
                    .check(status().in(200, 401, 412).saveAs("lastStatus"))
                    .check(substring("\"denied\"").notExists())
                    .check(jsonPath("$.error").optional().saveAs("errorType"))
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                    .check(header("ETag").optional().saveAs("newEtag"))
            )
            .exec(updateTokens())
            .doIf(session -> session.getInt("lastStatus") == 401
                && ("expired".equals(session.getString("errorType"))
                    || "session".equals(session.getString("errorType")))
            ).then(
                exec(
                    http("POST /v2/session/renew")
                        .post("/v2/session/renew")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 401).saveAs("renewStatus"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(header("ETag").optional().saveAs("newEtag"))
                )
                .exec(updateTokens())
                .doIf(session -> session.getInt("renewStatus") != 200).then(
                    doLogin()
                )
                .doIf(session -> session.getBoolean("hasCart")).then(
                    exec(
                        http("POST /v2/carts/{id}/recover")
                            .post("/v2/carts/#{cart}/recover")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("{}"))
                            .check(status().is(200))
                            .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                            .check(header("ETag").optional().saveAs("newEtag"))
                    )
                    .exec(updateTokens())
                )
                .exec(
                    http("PATCH /v2/carts/{id} retry")
                        .patch("/v2/carts/#{cart}")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody("{\"quantity\":#{quantity}}"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(header("ETag").optional().saveAs("newEtag"))
                )
                .exec(updateTokens())
            )
            .doIf(session -> session.getInt("lastStatus") == 412).then(
                exec(
                    http("GET /v2/carts/{id}")
                        .get("/v2/carts/#{cart}")
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(header("ETag").optional().saveAs("newEtag"))
                )
                .exec(updateTokens())
                .exec(
                    http("PATCH /v2/carts/{id} retry 412")
                        .patch("/v2/carts/#{cart}")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody("{\"quantity\":#{quantity}}"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(header("ETag").optional().saveAs("newEtag"))
                )
                .exec(updateTokens())
            )
            .exec(
                http("POST /v2/orders")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .header("Idempotency-Key", "#{cart}")
                    .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").ofBoolean().is(true))
                    .check(jsonPath("$.id").exists())
                    .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
            )
            .exec(updateTokens());

        ScenarioBuilder scn = scenario("DataDrivenCheckout")
            .feed(accountsFeeder)
            .repeat(2).on(journey);

        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }
}

