import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import { parseHTML } from 'k6/html';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const VUS = 2;
const ITERATIONS = 2;

const accounts = new SharedArray('accounts', function () {
  const parsed = JSON.parse(open('/fixtures/accounts.json'));
  return Array.isArray(parsed) ? parsed : [];
});

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: VUS,
      iterations: ITERATIONS,
      maxDuration: '2m',
    },
  },
  maxRedirects: 0,
};

function safeJson(res) {
  if (!res || !res.body) {
    return null;
  }
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) {
    return null;
  }
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      return res.headers[keys[i]];
    }
  }
  return null;
}

function resolveUrl(location) {
  if (location.startsWith('http://') || location.startsWith('https://')) {
    return location;
  }
  if (location.startsWith('/')) {
    return `${BASE_URL}${location}`;
  }
  return `${BASE_URL}/${location}`;
}

function extractFormCsrf(html) {
  if (!html) {
    return null;
  }
  const doc = parseHTML(html);
  const formInputs = doc.find('form input[name="csrf"]');
  for (let i = 0; i < formInputs.size(); i++) {
    const el = formInputs.eq(i);
    if (el.attr('disabled') == null) {
      const val = el.attr('value');
      if (val) {
        return val;
      }
    }
  }
  const allInputs = doc.find('input[name="csrf"]');
  for (let i = 0; i < allInputs.size(); i++) {
    const el = allInputs.eq(i);
    if (el.attr('disabled') == null) {
      const val = el.attr('value');
      if (val) {
        return val;
      }
    }
  }
  return null;
}

function findInStockVariant(catalogData) {
  const products =
    catalogData &&
    catalogData.data &&
    Array.isArray(catalogData.data.products)
      ? catalogData.data.products
      : [];
  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || !Array.isArray(product.variants)) {
      continue;
    }
    for (let j = 0; j < product.variants.length; j++) {
      const variant = product.variants[j];
      if (variant && variant.in_stock === true) {
        return { productId: product.id, variantId: variant.id };
      }
    }
  }
  return null;
}

function updateState(state, res) {
  const data = safeJson(res);
  if (data && typeof data.csrf === 'string' && data.csrf.length > 0) {
    state.csrf = data.csrf;
  }
  const etag = getHeader(res, 'etag');
  if (etag) {
    state.etag = etag;
  }
  return data;
}

function performLogin(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    jar: state.jar,
    redirects: 0,
    timeout: '5s',
  });
  updateState(state, formRes);
  const formCsrf = extractFormCsrf(formRes.body);
  check(formRes, {
    'login-form status is 200': (r) => r.status === 200,
    'login-form contains csrf input': () => Boolean(formCsrf),
  });
  if (formRes.status !== 200 || !formCsrf) {
    return false;
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: state.username,
      password: state.password,
      csrf: formCsrf,
    }),
    {
      headers: {
        'Content-Type': 'application/json',
      },
      jar: state.jar,
      redirects: 0,
      timeout: '5s',
    }
  );
  updateState(state, loginRes);

  const location = getHeader(loginRes, 'location');
  if (loginRes.status >= 300 && loginRes.status < 400 && location) {
    const redirectRes = http.get(resolveUrl(location), {
      jar: state.jar,
      redirects: 0,
      timeout: '5s',
    });
    const redirectData = updateState(state, redirectRes);
    if (redirectData && redirectData.grant_id) {
      state.grantId = redirectData.grant_id;
    }
    check(redirectRes, {
      'login redirect status is 200': (r) => r.status === 200,
    });
  }

  const ok = check(loginRes, {
    'login status is 200 or 302': (r) => r.status === 200 || r.status === 302,
    'login obtained csrf token': () => Boolean(state.csrf),
  });
  return ok && Boolean(state.csrf);
}

function isRecoverableAuthError(res) {
  if (!res || res.status !== 401) {
    return false;
  }
  const data = safeJson(res);
  return Boolean(data && (data.error === 'expired' || data.error === 'session'));
}

function recoverSession(state) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    jar: state.jar,
    redirects: 0,
    timeout: '5s',
  });
  updateState(state, renewRes);

  if (renewRes.status !== 200) {
    const loggedIn = performLogin(state);
    if (!loggedIn) {
      return false;
    }
  }

  if (state.cartId) {
    const recoverRes = http.post(
      `${BASE_URL}/v2/carts/${state.cartId}/recover`,
      '{}',
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf || '',
        },
        jar: state.jar,
        redirects: 0,
        timeout: '5s',
      }
    );
    updateState(state, recoverRes);
    if (recoverRes.status !== 200) {
      return false;
    }
  }

  return true;
}

function withAuthRecovery(state, opFn) {
  let res = opFn();
  updateState(state, res);
  if (isRecoverableAuthError(res)) {
    if (recoverSession(state)) {
      res = opFn();
      updateState(state, res);
    }
  }
  return res;
}

export default function () {
  const vuIndex = __VU - 1;
  const rowsPerVu = Math.max(1, Math.floor(accounts.length / VUS));
  const rowIndex = (vuIndex * rowsPerVu + (__ITER % rowsPerVu)) % accounts.length;
  const row = accounts[rowIndex];

  check(row, {
    'fixture row has string username': (r) =>
      typeof r.username === 'string' && r.username.length > 0,
    'fixture row has string password': (r) =>
      typeof r.password === 'string' && r.password.length > 0,
    'fixture row has numeric quantity': (r) =>
      typeof r.quantity === 'number' &&
      Number.isInteger(r.quantity) &&
      r.quantity >= 1 &&
      r.quantity <= 20,
    'fixture row has numeric delay': (r) =>
      r.delay === undefined || typeof r.delay === 'number',
  });

  if (typeof row.delay === 'number' && row.delay > 0) {
    sleep(row.delay / 1000);
  }

  const state = {
    jar: new http.CookieJar(),
    username: row.username,
    password: row.password,
    csrf: null,
    etag: null,
    cartId: null,
    grantId: null,
  };

  if (!performLogin(state)) {
    return;
  }

  const catalogRes = withAuthRecovery(state, () =>
    http.get(`${BASE_URL}/v2/catalog`, {
      jar: state.jar,
      redirects: 0,
      timeout: '5s',
    })
  );
  const catalogData = safeJson(catalogRes);
  const selection = findInStockVariant(catalogData);
  check(catalogRes, {
    'catalog status is 200': (r) => r.status === 200,
    'catalog has in-stock variant': () => Boolean(selection),
  });
  if (catalogRes.status !== 200 || !selection) {
    return;
  }

  const cartPayload = {
    product_id: selection.productId,
    variant_id: selection.variantId,
  };
  if (state.grantId) {
    cartPayload.grant_id = state.grantId;
    state.grantId = null;
  }

  const cartRes = withAuthRecovery(state, () =>
    http.post(`${BASE_URL}/v2/carts`, JSON.stringify(cartPayload), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      jar: state.jar,
      redirects: 0,
      timeout: '5s',
    })
  );
  const cartData = safeJson(cartRes);
  if (cartData && typeof cartData.id === 'string' && cartData.id.startsWith('cart-')) {
    state.cartId = cartData.id;
  }
  check(cartRes, {
    'cart creation status is 201': (r) => r.status === 201,
    'cart id returned': () => Boolean(state.cartId),
  });
  if (cartRes.status !== 201 || !state.cartId) {
    return;
  }

  const doPatchCart = () => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
    if (state.etag) {
      headers['If-Match'] = state.etag;
    }
    return http.patch(
      `${BASE_URL}/v2/carts/${state.cartId}`,
      JSON.stringify({ quantity: row.quantity }),
      {
        headers,
        jar: state.jar,
        redirects: 0,
        timeout: '5s',
      }
    );
  };

  let patchRes = withAuthRecovery(state, doPatchCart);
  if (patchRes.status === 412) {
    withAuthRecovery(state, () =>
      http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
        jar: state.jar,
        redirects: 0,
        timeout: '5s',
      })
    );
    patchRes = withAuthRecovery(state, doPatchCart);
  }
  check(patchRes, {
    'cart patch status is 200': (r) => r.status === 200,
  });
  if (patchRes.status !== 200) {
    return;
  }

  const idempotencyKey = state.cartId;
  const doSubmitOrder = () => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': idempotencyKey,
    };
    if (state.etag) {
      headers['If-Match'] = state.etag;
    }
    return http.post(
      `${BASE_URL}/v2/orders`,
      JSON.stringify({ cart_id: state.cartId }),
      {
        headers,
        jar: state.jar,
        redirects: 0,
        timeout: '5s',
      }
    );
  };

  let orderRes = withAuthRecovery(state, doSubmitOrder);
  if (orderRes.status === 412) {
    withAuthRecovery(state, () =>
      http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
        jar: state.jar,
        redirects: 0,
        timeout: '5s',
      })
    );
    orderRes = withAuthRecovery(state, doSubmitOrder);
  }
  const orderData = safeJson(orderRes);
  check(orderRes, {
    'order status is 201': (r) => r.status === 201,
    'order accepted is true': () => Boolean(orderData && orderData.accepted === true),
    'order id returned': () =>
      Boolean(orderData && typeof orderData.id === 'string' && orderData.id.length > 0),
  });
}

import itertools
import json
import os
from html.parser import HTMLParser

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

ACCOUNTS_PATH = "/fixtures/accounts.json"
with open(ACCOUNTS_PATH, "r", encoding="utf-8") as _fp:
    ACCOUNTS = json.load(_fp)

TARGET_USERS = 2
ITERATIONS_PER_USER = 2
TIMEOUT = (2.0, 5.0)

_USER_COUNTER = itertools.count(0)
_started_users = 0
_completed_users = 0


def _get_user_rows(user_index):
    rows = ACCOUNTS[user_index::TARGET_USERS]
    if not rows:
        rows = [ACCOUNTS[user_index % len(ACCOUNTS)]]
    return rows


def _parse_json(response):
    try:
        data = response.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _update_state(state, response, data):
    csrf = data.get("csrf")
    if csrf:
        state["csrf"] = csrf
    etag = response.headers.get("ETag")
    if etag:
        state["etag"] = etag


class CsrfFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None
        self._skip_depth = 0

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        if tag_lower in ("template", "noscript"):
            self._skip_depth += 1
            return
        if self._skip_depth > 0 or self.csrf is not None:
            return
        if tag_lower == "input":
            attr_map = {}
            for key, value in attrs:
                if key is not None:
                    attr_map[key.lower()] = value
            if attr_map.get("name") == "csrf" and "disabled" not in attr_map:
                value = attr_map.get("value")
                if value:
                    self.csrf = value

    def handle_endtag(self, tag):
        if tag.lower() in ("template", "noscript") and self._skip_depth > 0:
            self._skip_depth -= 1


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0)

    def on_start(self):
        global _started_users
        self._counted_done = False
        self.user_index = next(_USER_COUNTER)
        if self.user_index >= TARGET_USERS:
            raise StopUser()
        _started_users += 1
        self.rows = _get_user_rows(self.user_index)
        self.iteration = 0

    @task
    def run_journey(self):
        global _completed_users
        if self.iteration >= ITERATIONS_PER_USER:
            if not self._counted_done:
                self._counted_done = True
                _completed_users += 1
            raise StopUser()

        row = self.rows[self.iteration % len(self.rows)]
        self.iteration += 1
        try:
            self._execute_journey(row)
        finally:
            if self.iteration >= ITERATIONS_PER_USER:
                if not self._counted_done:
                    self._counted_done = True
                    _completed_users += 1
                raise StopUser()

    def _execute_journey(self, row):
        self.client.cookies.clear()
        state = {
            "csrf": None,
            "etag": None,
            "cart_id": None,
            "has_cart": False,
            "grant_id": None,
        }

        if not self._login(state, row):
            return

        product_id, variant_id = self._fetch_catalog(state, row)
        if not product_id or not variant_id:
            return

        if not self._create_cart(state, row, product_id, variant_id):
            return

        if not self._patch_cart(state, row):
            return

        self._create_order(state, row)

    def _login(self, state, row):
        form_csrf = None
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            if response.status_code != 200:
                response.failure(f"Login form failed with status {response.status_code}")
                return False
            parser = CsrfFormParser()
            parser.feed(response.text)
            parser.close()
            if not parser.csrf:
                response.failure("Missing csrf input in login form")
                return False
            form_csrf = parser.csrf
            response.success()

        redirect_location = None
        payload = {
            "username": row["username"],
            "password": row["password"],
            "csrf": form_csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            allow_redirects=False,
            timeout=TIMEOUT,
            catch_response=True,
        ) as response:
            data = _parse_json(response)
            _update_state(state, response, data)
            location = response.headers.get("Location")
            if response.status_code in (301, 302, 303, 307, 308) and location:
                redirect_location = location
                response.success()
            elif response.status_code == 200:
                if not state.get("csrf"):
                    response.failure("Missing csrf in login response")
                    return False
                response.success()
            else:
                response.failure(f"Login failed with status {response.status_code}")
                return False

        if redirect_location:
            target = redirect_location
            if not target.startswith(("http://", "https://", "/")):
                target = "/" + target
            with self.client.get(
                target,
                allow_redirects=False,
                timeout=TIMEOUT,
                name="/v2/login-redirect",
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if data.get("grant_id"):
                    state["grant_id"] = data["grant_id"]
                if response.status_code != 200:
                    response.failure(
                        f"Login redirect failed with status {response.status_code}"
                    )
                    return False
                if not state.get("csrf"):
                    response.failure("Missing csrf after login redirect")
                    return False
                response.success()

        return bool(state.get("csrf"))

    def _recover_session(self, state, row, error_kind):
        renewed = False
        if error_kind == "expired":
            headers = {}
            if state.get("csrf"):
                headers["X-CSRF-Token"] = state["csrf"]
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=headers,
                allow_redirects=False,
                timeout=TIMEOUT,
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if 200 <= response.status_code < 300:
                    response.success()
                    renewed = True
                elif response.status_code == 401 and data.get("error") in (
                    "expired",
                    "session",
                ):
                    response.success()
                    renewed = False
                else:
                    response.failure(
                        f"Session renew failed with status {response.status_code}"
                    )
                    return False

        if not renewed:
            if not self._login(state, row):
                return False

        if state["has_cart"] and state.get("cart_id"):
            headers = {}
            if state.get("csrf"):
                headers["X-CSRF-Token"] = state["csrf"]
            with self.client.post(
                f"/v2/carts/{state['cart_id']}/recover",
                json={},
                headers=headers,
                allow_redirects=False,
                timeout=TIMEOUT,
                name="/v2/carts/{id}/recover",
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if 200 <= response.status_code < 300:
                    response.success()
                else:
                    response.failure(
                        f"Cart recover failed with status {response.status_code}"
                    )
                    return False

        return True

    def _refresh_cart_etag(self, state, row):
        for attempt in range(2):
            need_recover = None
            with self.client.get(
                f"/v2/carts/{state['cart_id']}",
                allow_redirects=False,
                timeout=TIMEOUT,
                name="/v2/carts/{id}",
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if response.status_code == 200:
                    response.success()
                    return True
                if (
                    response.status_code == 401
                    and data.get("error") in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    need_recover = data.get("error")
                else:
                    response.failure(
                        f"GET cart failed with status {response.status_code}"
                    )
                    return False
            if need_recover:
                if not self._recover_session(state, row, need_recover):
                    return False
        return False

    def _fetch_catalog(self, state, row):
        for attempt in range(2):
            need_recover = None
            with self.client.get(
                "/v2/catalog",
                allow_redirects=False,
                timeout=TIMEOUT,
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if response.status_code == 200:
                    products = data.get("data", {}).get("products", [])
                    for product in products:
                        for variant in product.get("variants", []):
                            if variant.get("in_stock") is True:
                                response.success()
                                return product.get("id"), variant.get("id")
                    response.failure("No in-stock variant found in catalog")
                    return None, None
                if (
                    response.status_code == 401
                    and data.get("error") in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    need_recover = data.get("error")
                else:
                    response.failure(
                        f"Catalog failed with status {response.status_code}"
                    )
                    return None, None
            if need_recover:
                if not self._recover_session(state, row, need_recover):
                    return None, None
        return None, None

    def _create_cart(self, state, row, product_id, variant_id):
        payload = {
            "product_id": product_id,
            "variant_id": variant_id,
        }
        if state.get("grant_id"):
            payload["grant_id"] = state["grant_id"]

        for attempt in range(2):
            need_recover = None
            headers = {}
            if state.get("csrf"):
                headers["X-CSRF-Token"] = state["csrf"]
            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=headers,
                allow_redirects=False,
                timeout=TIMEOUT,
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                cart_id = data.get("id")
                if (
                    response.status_code == 201
                    and isinstance(cart_id, str)
                    and cart_id.startswith("cart-")
                ):
                    state["cart_id"] = cart_id
                    state["has_cart"] = True
                    state["grant_id"] = None
                    response.success()
                    return True
                if (
                    response.status_code == 401
                    and data.get("error") in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    need_recover = data.get("error")
                else:
                    response.failure(
                        f"Create cart failed with status {response.status_code}"
                    )
                    return False
            if need_recover:
                if not self._recover_session(state, row, need_recover):
                    return False
        return False

    def _patch_cart(self, state, row):
        payload = {"quantity": row["quantity"]}
        recovered_auth = False
        retried_412 = False

        while True:
            headers = {}
            if state.get("csrf"):
                headers["X-CSRF-Token"] = state["csrf"]
            if state.get("etag"):
                headers["If-Match"] = state["etag"]

            need_recover = None
            need_reread = False
            with self.client.patch(
                f"/v2/carts/{state['cart_id']}",
                json=payload,
                headers=headers,
                allow_redirects=False,
                timeout=TIMEOUT,
                name="/v2/carts/{id}",
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if 200 <= response.status_code < 300:
                    response.success()
                    return True
                if (
                    response.status_code == 401
                    and data.get("error") in ("expired", "session")
                    and not recovered_auth
                ):
                    response.success()
                    need_recover = data.get("error")
                elif response.status_code == 412 and not retried_412:
                    response.success()
                    need_reread = True
                else:
                    response.failure(
                        f"Patch cart failed with status {response.status_code}"
                    )
                    return False

            if need_recover:
                recovered_auth = True
                if not self._recover_session(state, row, need_recover):
                    return False
                continue
            if need_reread:
                retried_412 = True
                if not self._refresh_cart_etag(state, row):
                    return False
                continue
            return False

    def _create_order(self, state, row):
        payload = {"cart_id": state["cart_id"]}
        idempotency_key = state["cart_id"]
        recovered_auth = False
        retried_412 = False

        while True:
            headers = {
                "Idempotency-Key": idempotency_key,
            }
            if state.get("csrf"):
                headers["X-CSRF-Token"] = state["csrf"]
            if state.get("etag"):
                headers["If-Match"] = state["etag"]

            need_recover = None
            need_reread = False
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                allow_redirects=False,
                timeout=TIMEOUT,
                catch_response=True,
            ) as response:
                data = _parse_json(response)
                _update_state(state, response, data)
                if response.status_code == 201 and data.get("accepted") is True:
                    response.success()
                    return True
                if response.status_code == 200 and data.get("accepted") is False:
                    response.failure("Order rejected with accepted=false")
                    return False
                if (
                    response.status_code == 401
                    and data.get("error") in ("expired", "session")
                    and not recovered_auth
                ):
                    response.success()
                    need_recover = data.get("error")
                elif response.status_code == 412 and not retried_412:
                    response.success()
                    need_reread = True
                else:
                    response.failure(
                        f"Create order failed with status {response.status_code}"
                    )
                    return False

            if need_recover:
                recovered_auth = True
                if not self._recover_session(state, row, need_recover):
                    return False
                continue
            if need_reread:
                retried_412 = True
                if not self._refresh_cart_etag(state, row):
                    return False
                continue
            return False


class FixedIterationShape(LoadTestShape):
    def tick(self):
        if _completed_users >= TARGET_USERS:
            return None
        if self.get_run_time() > 60:
            return None
        if _started_users < TARGET_USERS:
            target = TARGET_USERS - _completed_users
            return (max(target, 1), max(TARGET_USERS, 10))
        current = self.get_current_user_count()
        if current <= 0:
            return None
        return (current, 1)

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static String jsonString(String value) {
        if (value == null) {
            return "\"\"";
        }
        StringBuilder sb = new StringBuilder(value.length() + 2);
        sb.append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    public ModelSimulation() {
        String envBaseUrl = System.getenv("BASE_URL");
        String baseUrl = (envBaseUrl != null && !envBaseUrl.isBlank())
            ? envBaseUrl.trim()
            : "http://127.0.0.1:8000";
        while (baseUrl.endsWith("/")) {
            baseUrl = baseUrl.substring(0, baseUrl.length() - 1);
        }

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect()
            .disableCaching();

        List<Map<String, Object>> vuRecords = new ArrayList<>(4);
        for (int i = 1; i <= 4; i++) {
            Map<String, Object> record = new HashMap<>();
            record.put("vuIndex", i);
            record.put("username", "bench-" + i);
            vuRecords.add(record);
        }

        ChainBuilder journey = exec(session -> session
                .markAsSucceeded()
                .removeAll("formCsrf", "location", "grant", "products", "product", "variant", "cart")
                .set("csrf", "")
                .set("etag", "")
            )
            .exitBlockOnFail().on(
                exec(
                    http("login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(
                            css("input[name='csrf'][value]", "value")
                                .findAll()
                                .transform(values -> values.stream()
                                    .filter(v -> v != null && !v.isBlank())
                                    .findFirst()
                                    .orElse(""))
                                .not("")
                                .saveAs("formCsrf")
                        )
                        .check(header("ETag").optional().saveAs("etag"))
                )
                .exec(
                    http("login")
                        .post("/v2/login")
                        .header("Content-Type", "application/json")
                        .body(StringBody(session ->
                            "{\"username\":" + jsonString(session.getString("username"))
                                + ",\"password\":\"bench\",\"csrf\":" + jsonString(session.getString("formCsrf")) + "}"
                        ))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("location"))
                        .check(header("ETag").optional().saveAs("etag"))
                        .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                )
                .doIf(session -> session.contains("location") && !session.getString("location").isEmpty()).then(
                    exec(
                        http("login-redirect")
                            .get("#{location}")
                            .check(status().is(200))
                            .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                            .check(regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("grant"))
                            .check(header("ETag").optional().saveAs("etag"))
                    )
                )
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf == null || csrf.isEmpty()) {
                        return session.markAsFailed();
                    }
                    return session;
                })
                .exec(
                    http("catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(header("ETag").optional().saveAs("etag"))
                        .check(jsonPath("$.data.products").ofList().saveAs("products"))
                )
                .exec(session -> {
                    Object rawProducts = session.get("products");
                    if (!(rawProducts instanceof List<?>)) {
                        return session.markAsFailed();
                    }
                    for (Object pObj : (List<?>) rawProducts) {
                        if (!(pObj instanceof Map<?, ?>)) {
                            continue;
                        }
                        Map<?, ?> productMap = (Map<?, ?>) pObj;
                        Object pid = productMap.get("id");
                        Object variantsObj = productMap.get("variants");
                        if (pid == null || !(variantsObj instanceof List<?>)) {
                            continue;
                        }
                        for (Object vObj : (List<?>) variantsObj) {
                            if (!(vObj instanceof Map<?, ?>)) {
                                continue;
                            }
                            Map<?, ?> variantMap = (Map<?, ?>) vObj;
                            Object inStock = variantMap.get("in_stock");
                            Object vid = variantMap.get("id");
                            if ((Boolean.TRUE.equals(inStock) || "true".equalsIgnoreCase(String.valueOf(inStock))) && vid != null) {
                                return session
                                    .set("product", String.valueOf(pid))
                                    .set("variant", String.valueOf(vid));
                            }
                        }
                    }
                    return session.markAsFailed();
                })
                .exec(
                    http("create-cart")
                        .post("/v2/carts")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody(session -> {
                            String product = session.getString("product");
                            String variant = session.getString("variant");
                            String grant = session.getString("grant");
                            if (grant != null && !grant.isEmpty()) {
                                return "{\"product_id\":" + jsonString(product)
                                    + ",\"variant_id\":" + jsonString(variant)
                                    + ",\"grant_id\":" + jsonString(grant) + "}";
                            }
                            return "{\"product_id\":" + jsonString(product)
                                + ",\"variant_id\":" + jsonString(variant) + "}";
                        }))
                        .check(status().is(201))
                        .check(jsonPath("$.id").find().saveAs("cart"))
                        .check(regex("\"id\"\\s*:\\s*\"cart-").exists())
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(header("ETag").optional().saveAs("etag"))
                )
                .exec(
                    http("create-order")
                        .post("/v2/orders")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Idempotency-Key", "#{cart}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody(session ->
                            "{\"cart_id\":" + jsonString(session.getString("cart")) + "}"
                        ))
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").ofBoolean().is(true))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(header("ETag").optional().saveAs("etag"))
                )
            )
            .exec(Session::markAsSucceeded);

        ScenarioBuilder scn = scenario("CheckoutJourney")
            .feed(listFeeder(vuRecords).circular())
            .doIf(session -> session.getInt("vuIndex") > 1).then(
                pause(session -> Duration.ofMillis((session.getInt("vuIndex") - 1) * 500L))
            )
            .during(Duration.ofMillis(35500), false).on(
                pace(Duration.ofMillis(2000))
                    .exec(journey)
            );

        setUp(
            scn.injectOpen(atOnceUsers(4))
        ).protocols(httpProtocol);
    }
}

