import os
import time
from html.parser import HTMLParser
from urllib.parse import urlsplit

import gevent
from locust import HttpUser, LoadTestShape, constant, task


TARGET_USERS = 4
TARGET_RATE = 2.0
TARGET_DURATION = 38.0
REQUEST_TIMEOUT = (2.0, 3.0)


class _CsrfFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self._ignored_depth = 0
        self._in_form = False
        self._form_action = ""
        self.preferred = None
        self.fallback = None

    def handle_starttag(self, tag, attrs):
        tag_l = tag.lower()
        if tag_l in ("script", "style", "noscript", "template"):
            self._ignored_depth += 1
            return
        if self._ignored_depth > 0:
            return
        attr_map = {}
        disabled = False
        for key, val in attrs:
            key_l = key.lower()
            if key_l == "disabled":
                disabled = True
            elif key_l not in attr_map:
                attr_map[key_l] = val
        if tag_l == "form":
            self._in_form = True
            self._form_action = (attr_map.get("action") or "").lower()
            return
        if tag_l == "input" and not disabled and attr_map.get("name") == "csrf":
            value = attr_map.get("value")
            if value:
                if self._in_form and ("/login" in self._form_action or self._form_action == ""):
                    if self.preferred is None:
                        self.preferred = value
                if self.fallback is None:
                    self.fallback = value

    def handle_endtag(self, tag):
        tag_l = tag.lower()
        if tag_l in ("script", "style", "noscript", "template") and self._ignored_depth > 0:
            self._ignored_depth -= 1
        elif tag_l == "form":
            self._in_form = False
            self._form_action = ""


def _extract_login_csrf(html_text):
    parser = _CsrfFormParser()
    parser.feed(html_text or "")
    parser.close()
    return parser.preferred or parser.fallback


def _extract_in_stock_item(payload):
    if not isinstance(payload, dict):
        return None, None
    data = payload.get("data")
    products = data.get("products") if isinstance(data, dict) else payload.get("products")
    if not isinstance(products, list):
        return None, None
    for product in products:
        if not isinstance(product, dict):
            continue
        product_id = product.get("id")
        variants = product.get("variants")
        if not product_id or not isinstance(variants, list):
            continue
        for variant in variants:
            if isinstance(variant, dict) and variant.get("in_stock") is True and variant.get("id"):
                return product_id, variant["id"]
    return None, None


def _safe_json(resp):
    try:
        return resp.json()
    except (ValueError, TypeError):
        return None


class _SharedPacer:
    def __init__(self, rate_per_sec, duration):
        self.interval = 1.0 / rate_per_sec
        self.duration = duration
        self.start_time = None
        self.next_slot = None
        self.first_order_time = None

    def sync_start(self, run_time):
        if self.start_time is None:
            self.start_time = time.monotonic() - max(0.0, run_time)

    def stop_at(self):
        if self.first_order_time is not None and self.start_time is not None:
            t0_offset = max(0.0, self.first_order_time - self.start_time)
            return min(t0_offset + 39.0, max(self.duration, t0_offset + 36.5))
        return self.duration

    def mark_order_start(self):
        if self.first_order_time is None:
            self.first_order_time = time.monotonic()

    def acquire_slot(self):
        now = time.monotonic()
        if self.start_time is None:
            self.start_time = now
        if self.next_slot is None:
            self.next_slot = now
        slot = self.next_slot
        if slot < now:
            slot = now
        cutoff = self.start_time + self.stop_at() - 0.8
        if slot >= cutoff:
            gevent.sleep(0.5)
            return False
        self.next_slot = slot + self.interval
        delay = slot - now
        if delay > 0.0:
            gevent.sleep(delay)
        return True


_PACER = _SharedPacer(TARGET_RATE, TARGET_DURATION)


class ShopJourneyUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0)
    _user_counter = 0

    def on_start(self):
        ShopJourneyUser._user_counter += 1
        user_num = ((ShopJourneyUser._user_counter - 1) % 16) + 1
        self.username = f"bench-{user_num}"
        self.password = "bench"
        self.csrf = ""
        self.etag = None

    def _update_state(self, resp, data):
        etag = resp.headers.get("ETag")
        if etag:
            self.etag = etag
        if isinstance(data, dict):
            fresh_csrf = data.get("csrf")
            if fresh_csrf:
                self.csrf = fresh_csrf

    def _do_login(self):
        form_csrf = None
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False, None
            form_csrf = _extract_login_csrf(resp.text)
            if not form_csrf:
                resp.failure("login-form missing csrf input")
                return False, None
            resp.success()

        redirect_location = None
        grant_id = None
        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": form_csrf,
            },
            headers={"Content-Type": "application/json"},
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code in (301, 302, 303, 307, 308):
                redirect_location = resp.headers.get("Location")
                if not redirect_location:
                    resp.failure("login redirect missing Location")
                    return False, None
                resp.success()
            elif resp.status_code == 200:
                data = _safe_json(resp)
                self._update_state(resp, data)
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure("login response missing csrf")
                    return False, None
                grant_id = data.get("grant_id")
                resp.success()
            else:
                resp.failure(f"login status {resp.status_code}")
                return False, None

        if redirect_location:
            redirect_name = urlsplit(redirect_location).path or "/v2/login-redirect"
            with self.client.get(
                redirect_location,
                name=redirect_name,
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"login redirect status {resp.status_code}")
                    return False, None
                data = _safe_json(resp)
                self._update_state(resp, data)
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure("login redirect missing csrf")
                    return False, None
                grant_id = data.get("grant_id")
                resp.success()

        return True, grant_id

    def _recover_session(self, reason, cart_id=None):
        renewed = False
        if reason == "expired" and self.csrf:
            with self.client.post(
                "/v2/session/renew",
                name="/v2/session/renew",
                json={},
                headers={
                    "Content-Type": "application/json",
                    "X-CSRF-Token": self.csrf,
                },
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                data = _safe_json(resp)
                if resp.status_code == 200:
                    self._update_state(resp, data)
                    resp.success()
                    renewed = True
                elif resp.status_code == 401 and isinstance(data, dict) and data.get("error") in ("expired", "session"):
                    resp.success()
                else:
                    resp.failure(f"session renew status {resp.status_code}")

        if not renewed:
            ok, _ = self._do_login()
            if not ok:
                return False

        if cart_id:
            with self.client.post(
                f"/v2/carts/{cart_id}/recover",
                name="/v2/carts/{id}/recover",
                json={},
                headers={
                    "Content-Type": "application/json",
                    "X-CSRF-Token": self.csrf,
                },
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                data = _safe_json(resp)
                if resp.status_code == 200:
                    self._update_state(resp, data)
                    resp.success()
                else:
                    resp.failure(f"cart recover status {resp.status_code}")
                    return False

        return True

    def _request_with_recovery(
        self,
        method,
        path,
        *,
        name,
        json_body=None,
        headers_fn=None,
        expected_statuses=(200,),
        validate_fn=None,
        cart_id=None,
        is_order=False,
    ):
        recovered_once = False
        rate_retries = 0
        while True:
            headers = headers_fn() if headers_fn else {}
            if is_order:
                _PACER.mark_order_start()
            need_recovery = None
            retry_delay = None
            with self.client.request(
                method,
                path,
                name=name,
                json=json_body,
                headers=headers,
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                data = _safe_json(resp)
                if resp.status_code == 401:
                    err = data.get("error") if isinstance(data, dict) else None
                    if err in ("expired", "session") and not recovered_once:
                        resp.success()
                        need_recovery = err
                    else:
                        resp.failure(f"401 {err or 'unauthorized'}")
                        return False, data
                elif resp.status_code == 429 and rate_retries < 4:
                    resp.success()
                    try:
                        retry_delay = max(0.1, float(resp.headers.get("Retry-After", "1")))
                    except ValueError:
                        retry_delay = 1.0
                elif resp.status_code in expected_statuses:
                    self._update_state(resp, data)
                    err_msg = validate_fn(resp, data) if validate_fn else None
                    if err_msg:
                        resp.failure(err_msg)
                        return False, data
                    resp.success()
                    return True, data
                else:
                    resp.failure(f"unexpected status {resp.status_code}")
                    return False, data

            if need_recovery is not None:
                recovered_once = True
                if not self._recover_session(need_recovery, cart_id=cart_id):
                    return False, None
                continue

            if retry_delay is not None:
                rate_retries += 1
                gevent.sleep(retry_delay)
                continue

            return False, None

    @task
    def checkout_journey(self):
        if not _PACER.acquire_slot():
            return

        self.etag = None
        ok, grant_id = self._do_login()
        if not ok:
            return

        ok, catalog_data = self._request_with_recovery(
            "GET",
            "/v2/catalog",
            name="/v2/catalog",
            expected_statuses=(200,),
        )
        if not ok:
            return

        product_id, variant_id = _extract_in_stock_item(catalog_data)
        if not product_id or not variant_id:
            return

        cart_payload = {
            "product_id": product_id,
            "variant_id": variant_id,
        }
        if grant_id:
            cart_payload["grant_id"] = grant_id

        def _validate_cart(_resp, data):
            if not isinstance(data, dict):
                return "cart response not JSON"
            cid = data.get("id")
            if not isinstance(cid, str) or not cid.startswith("cart-"):
                return "cart response missing cart id"
            return None

        ok, cart_data = self._request_with_recovery(
            "POST",
            "/v2/carts",
            name="/v2/carts",
            json_body=cart_payload,
            headers_fn=lambda: {
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
            },
            expected_statuses=(201,),
            validate_fn=_validate_cart,
        )
        if not ok or not isinstance(cart_data, dict):
            return

        cart_id = cart_data["id"]

        def _order_headers():
            hdrs = {
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
                "Idempotency-Key": cart_id,
            }
            if self.etag:
                hdrs["If-Match"] = self.etag
            return hdrs

        def _validate_order(_resp, data):
            if not isinstance(data, dict):
                return "order response not JSON"
            if data.get("accepted") is not True:
                return "order not accepted"
            if not data.get("id"):
                return "order response missing id"
            return None

        self._request_with_recovery(
            "POST",
            "/v2/orders",
            name="/v2/orders",
            json_body={"cart_id": cart_id},
            headers_fn=_order_headers,
            expected_statuses=(201,),
            validate_fn=_validate_order,
            cart_id=cart_id,
            is_order=True,
        )


class JourneyLoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        _PACER.sync_start(run_time)
        if run_time < _PACER.stop_at():
            return (TARGET_USERS, TARGET_USERS)
        return None

