REQUEST_TIMEOUT = (2.0, 5.0)

CSRF_INPUT_RE = re.compile(
    r"""<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>""",
    re.IGNORECASE,
)
CSRF_JSON_RE = re.compile(r'"csrf"\s*:')
CART_ID_RE = re.compile(r'"id"\s*:\s*"cart-')
ORDER_ACCEPTED_RE = re.compile(r'"accepted"\s*:\s*true')

REQUIRED_TRANSACTIONS = (
    ("/v2/login-form", "GET"),
    ("/v2/login", "POST"),
    ("/v2/catalog", "GET"),
    ("/v2/carts", "POST"),
    ("/v2/orders", "POST"),
)


class _CsrfFormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self._in_form = 0
        self._skip_depth = 0
        self._candidates = []

    def handle_starttag(self, tag, attrs):
        tag_l = tag.lower()
        if tag_l in ("script", "style", "template", "noscript"):
            self._skip_depth += 1
            return
        if tag_l == "form":
            self._in_form += 1
            return
        if self._skip_depth > 0 or tag_l != "input":
            return
        attr_map = {k.lower(): v for k, v in attrs}
        if attr_map.get("name") != "csrf" or "disabled" in attr_map:
            return
        value = attr_map.get("value")
        if value:
            input_type = (attr_map.get("type") or "").lower()
            self._candidates.append((self._in_form > 0, input_type == "hidden", value))

    def handle_endtag(self, tag):
        tag_l = tag.lower()
        if tag_l in ("script", "style", "template", "noscript"):
            if self._skip_depth > 0:
                self._skip_depth -= 1
        elif tag_l == "form":
            if self._in_form > 0:
                self._in_form -= 1

    def extract_csrf(self):
        if not self._candidates:
            return None
        for in_form, is_hidden, value in self._candidates:
            if in_form and is_hidden:
                return value
        for in_form, _, value in self._candidates:
            if in_form:
                return value
        for _, is_hidden, value in self._candidates:
            if is_hidden:
                return value
        return self._candidates[0][2]


def _extract_form_csrf(html_text):
    parser = _CsrfFormParser()
    parser.feed(html_text)
    parser.close()
    token = parser.extract_csrf()
    if token:
        return token
    match = CSRF_INPUT_RE.search(html_text)
    return match.group(1) if match else None


def _safe_json(response):
    try:
        data = response.json()
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _select_in_stock_product(catalog_data):
    if not isinstance(catalog_data, dict):
        return None, None
    data_obj = catalog_data.get("data")
    if not isinstance(data_obj, dict):
        return None, None
    products = data_obj.get("products")
    if not isinstance(products, list):
        return None, None
    for product in products:
        if not isinstance(product, dict):
            continue
        product_id = product.get("id")
        variants = product.get("variants")
        if not product_id or not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and variant.get("id")
            ):
                return product_id, variant["id"]
    return None, None


class ShopUser(HttpUser):
