                        csrf = data["csrf"]
                    if resp.headers.get("ETag"):
                        etag = resp.headers["ETag"]
                    product_id, variant_id = _select_in_stock_product(data)
                    if product_id and variant_id:
                        resp.success()
                    else:
                        resp.failure("catalog missing in-stock variant")
                    break
                else:
                    resp.failure(f"catalog status={resp.status_code}")
                    return
            csrf, etag, ok = self._recover_session(err_kind, csrf, None, etag)
            if not ok:
                return

        if not product_id or not variant_id:
            return

        cart_id = None
        cart_payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            cart_payload["grant_id"] = grant_id

        for attempt in range(2):
            with self.client.post(
                "/v2/carts",
