                        etag = resp.headers["ETag"]
                    resp.success()
                    break
                else:
                    resp.failure(f"cart creation failed status={resp.status_code}")
                    return
            csrf, etag, ok = self._recover_session(err_kind, csrf, cart_id, etag)
            if not ok:
                return

        if not cart_id:
            return

        for attempt in range(2):
            order_headers = {
                "Content-Type": "application/json",
                "X-CSRF-Token": csrf,
                "Idempotency-Key": cart_id,
            }
            if etag:
                order_headers["If-Match"] = etag
            with self.client.post(
                "/v2/orders",
                json={"cart_id": cart_id},
                headers=order_headers,
                name="/v2/orders",
                allow_redirects=False,
                catch_response=True,
                timeout=REQUEST_TIMEOUT,
            ) as resp:
                data = _safe_json(resp)
                if resp.status_code == 401 and data and data.get("error") in ("expired", "session") and attempt == 0:
                    err_kind = data["error"]
                    resp.success()
                elif (
                    resp.status_code == 201
                    and data
                    and data.get("accepted") is True
                    and ORDER_ACCEPTED_RE.search(resp.text)
                ):
                    if data.get("csrf"):
                        csrf = data["csrf"]
                    if resp.headers.get("ETag"):
                        etag = resp.headers["ETag"]
                    resp.success()
                    break
                else:
                    accepted = data.get("accepted") if data else None
                    resp.failure(
                        f"order assertion failed: status={resp.status_code} accepted={accepted}"
                    )
                    break
            csrf, etag, ok = self._recover_session(err_kind, csrf, cart_id, etag)
            if not ok:
                return

    @task
    def run_journey(self):
        if self.user_index > TARGET_USERS or self.iterations_done >= ITERATIONS_PER_USER:
            raise StopUser()
        try:
            self._execute_journey()
        finally:
            self.iterations_done += 1
            if self.iterations_done >= ITERATIONS_PER_USER:
                ShopUser._completed_users += 1
        if self.iterations_done >= ITERATIONS_PER_USER:
            raise StopUser()


class JourneyLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        ShopUser._spawned_users = 0
        ShopUser._completed_users = 0
        self._max_run_time = 120.0

    def _evaluate_exit_code(self):
        if self.runner is None:
            return 1
        stats = self.runner.stats
        if stats.total.num_requests == 0:
            return 1
        if stats.total.num_failures > 0 or len(stats.errors) > 0:
            return 1
        for entry in stats.entries.values():
            if entry.num_requests > 0 and (entry.num_failures / entry.num_requests) > 0.0:
                return 1
        for name, method in REQUIRED_TRANSACTIONS:
            entry = stats.entries.get((name, method))
            if entry is None or entry.num_requests < EXPECTED_JOURNEYS:
                return 1
            if (entry.num_failures / entry.num_requests) > 0.0:
                return 1
        return 0

    def tick(self):
        if ShopUser._completed_users >= TARGET_USERS or self.get_run_time() >= self._max_run_time:
            if self.runner is not None and self.runner.environment is not None:
                self.runner.environment.process_exit_code = self._evaluate_exit_code()
            return None
        return (TARGET_USERS, TARGET_USERS)

