class InputExtractor(HTMLParser):
    def __init__(self, target_name):
        super().__init__()
        self.target_name = target_name
        self.value = None
        self.form_action = None

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        attr_map = {k.lower(): v for k, v in attrs}
        if tag_lower == 'form' and self.form_action is None and attr_map.get('action'):
            self.form_action = attr_map['action']
        if tag_lower == 'input' and self.value is None:
            if 'disabled' in attr_map:
                return
            if attr_map.get('name') == self.target_name and attr_map.get('value'):
                self.value = attr_map['value']


def parse_form(html_text, input_name):
    parser = InputExtractor(input_name)
    parser.feed(html_text or '')
    parser.close()
    return parser.form_action, parser.value


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool['name']] += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool


ARRIVALS = ArrivalPlan()
OWNER = {'logins': 0, 'ready': Event(), 'lock': Semaphore()}
USER_COUNTER = {'count': 0, 'lock': Semaphore()}


class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
    wait_time = lambda self: 0

    def on_start(self):
        worker_id = getattr(self, '_p95_worker_id', None)
        if worker_id and '-' in str(worker_id):
            number = int(str(worker_id).rsplit('-', 1)[1])
        else:
            with USER_COUNTER['lock']:
                USER_COUNTER['count'] += 1
                number = USER_COUNTER['count']
        self.row = ROWS[(number - 1) % len(ROWS)]
