    return r.json();
  } catch (_) {
    return {};
  }
}

function hdr(r, name) {
  if (!r || !r.headers) return undefined;
  const target = name.toLowerCase();
  for (const k in r.headers) {
    if (k.toLowerCase() === target) return r.headers[k];
  }
  return undefined;
}

function findInput(doc, name, formSelector) {
  const selectors = formSelector
    ? [formSelector + ' input[name="' + name + '"]', 'form input[name="' + name + '"]', 'input[name="' + name + '"]']
    : ['form input[name="' + name + '"]', 'input[name="' + name + '"]'];
  for (let s = 0; s < selectors.length; s++) {
    const matches = doc.find(selectors[s]);
    const count = matches.size();
    for (let i = 0; i < count; i++) {
      const el = matches.eq(i);
      if (el.attr('disabled') !== undefined) continue;
      const val = el.attr('value');
      if (val) return val;
