import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"users\": 2, \"iterations\": 2, \"mode\": \"denial\"}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final Pattern COMMENT_PATTERN = Pattern.compile("(?s)<!--.*?-->");
    private static final Pattern IGNORED_BLOCKS = Pattern.compile(
        "(?is)<(template|noscript|script|style)\\b[^>]*>.*?</\\1>");
    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern DISABLED_ATTR = Pattern.compile(
        "(?i)(?:^|\\s)disabled(?:\\s*=|\\s|>|/|$)");
    private static final Pattern NAME_ATTR = Pattern.compile(
        "(?i)(?:^|\\s)name\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`/]+))");
    private static final Pattern VALUE_ATTR = Pattern.compile(
        "(?i)(?:^|\\s)value\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`/]+))");

    private static String baseUrl() {
        String url = System.getenv("BASE_URL");
        return (url != null && !url.isBlank()) ? url : "http://127.0.0.1:8000";
    }

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String attrValue(Matcher matcher) {
        if (!matcher.find()) return null;
        if (matcher.group(1) != null) return matcher.group(1);
        if (matcher.group(2) != null) return matcher.group(2);
        return matcher.group(3);
    }

    private static String extractLoginCsrf(String html) {
        if (html == null || html.isEmpty()) return "";
        String cleaned = IGNORED_BLOCKS.matcher(COMMENT_PATTERN.matcher(html).replaceAll("")).replaceAll("");
        Matcher inputs = INPUT_TAG.matcher(cleaned);
        while (inputs.find()) {
            String tag = inputs.group();
            if (DISABLED_ATTR.matcher(tag).find()) continue;
            String name = attrValue(NAME_ATTR.matcher(tag));
            if (!"csrf".equals(name)) continue;
            String value = attrValue(VALUE_ATTR.matcher(tag));
            if (value != null && !value.isEmpty()) return value;
        }
        return "";
    }

    private static String classifyCatalogResponse(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("error")) {
                String err = node.path("error").asText("");
                return ("expired".equals(err) || "session".equals(err)) ? "recover:" + err : "error:" + err;
            }
            return node.path("data").has("products") ? "ok" : "invalid";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static String classifyCartCreateResponse(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("error")) {
                String err = node.path("error").asText("");
                return ("expired".equals(err) || "session".equals(err)) ? "recover:" + err : "error:" + err;
            }
            return node.hasNonNull("id") ? "ok" : "invalid";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static String classifyCartGetResponse(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("error")) {
                String err = node.path("error").asText("");
                return ("expired".equals(err) || "session".equals(err)) ? "recover:" + err : "error:" + err;
            }
            if (node.hasNonNull("id") || node.hasNonNull("cart_id") || node.hasNonNull("cart")
                || node.hasNonNull("product_id") || node.hasNonNull("quantity")
                || node.hasNonNull("items") || node.path("ok").asBoolean(false)) {
                return "ok";
            }
            return "invalid";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static String classifyOrderResponse(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("error")) {
                String err = node.path("error").asText("");
                return ("expired".equals(err) || "session".equals(err)) ? "recover:" + err : "error:" + err;
            }
            return node.path("accepted").asBoolean(false) ? "accepted" : "rejected";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static String classifyRenewResponse(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("error")) {
                String err = node.path("error").asText("");
                return ("session".equals(err) || "expired".equals(err)) ? "relogin:" + err : "error:" + err;
            }
            return (node.isObject() && node.size() > 0) ? "ok" : "invalid";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static boolean isRecoverable(String outcome) {
        return "recover:expired".equals(outcome) || "recover:session".equals(outcome);
    }

    private static boolean hasCart(Session session) {
        String cart = session.getString("cart");
        return cart != null && !cart.isEmpty();
    }

    private static String loginPayload(Session session) {
        return JSON.createObjectNode()
            .put("username", username(session))
            .put("password", "bench")
            .put("csrf", session.getString("formCsrf"))
            .toString();
    }

    private static String cartPayload(Session session) {
        ObjectNode node = JSON.createObjectNode()
            .put("product_id", session.getString("product"))
            .put("variant_id", session.getString("variant"));
        String grant = session.getString("grant");
        if (grant != null && !grant.isEmpty()) {
            node.put("grant_id", grant);
        }
        return node.toString();
    }

    private static String orderPayload(Session session) {
        return JSON.createObjectNode()
            .put("cart_id", session.getString("cart"))
            .toString();
    }

    private static Session selectProduct(Session session) {
        String body = session.getString("catalogBody");
        if (body == null || body.isEmpty()) return session;
        try {
            JsonNode products = JSON.readTree(body).path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder authenticate() {
        return exec(session -> session.remove("location").remove("formCsrf"))
            .exec(http("login form").get("/v2/login-form")
                .check(
                    status().is(200),
                    bodyString().transform(ModelSimulation::extractLoginCsrf).not("").saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(ModelSimulation::loginPayload))
                .check(
                    status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(
                        status().is(200),
                        jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder recoverSession(String outcomeKey) {
        return exec(session -> session.set("sessionRecovered", "false")
                .remove("renewStatus").remove("renewOutcome"))
            .exec(doIf(session -> "recover:expired".equals(session.getString(outcomeKey))).then(
                exec(http("renew").post("/v2/session/renew")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(
                        status().in(200, 201, 401),
                        status().saveAs("renewStatus"),
                        bodyString().transform(ModelSimulation::classifyRenewResponse)
                            .in("ok", "relogin:session", "relogin:expired")
                            .saveAs("renewOutcome"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> "ok".equals(session.getString("renewOutcome"))
                    ? session.set("sessionRecovered", "true")
                    : session)))
            .exec(doIf(session -> "recover:session".equals(session.getString(outcomeKey))
                || (session.contains("renewOutcome")
                    && session.getString("renewOutcome").startsWith("relogin:"))).then(
                authenticate()
                    .exec(session -> session.set("sessionRecovered", "true"))))
            .exec(doIf(session -> "true".equals(session.getString("sessionRecovered"))
                && hasCart(session)).then(
                exec(http("cart recovery").post("/v2/carts/#{cart}/recover")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(
                        status().in(200, 201),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(session -> session.set("csrf", "").set("grant", "")
                .remove("location").remove("formCsrf")
                .remove("product").remove("variant")
                .remove("cart").remove("etag")
                .remove("catalogStatus").remove("catalogOutcome").remove("catalogBody")
                .remove("cartStatus").remove("cartOutcome")
                .remove("probeStatus").remove("probeOutcome")
                .remove("orderStatus").remove("orderOutcome")
                .remove("renewStatus").remove("renewOutcome").remove("sessionRecovered"))
            .exec(authenticate())
            .exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(
                    status().in(200, 401),
                    status().saveAs("catalogStatus"),
                    bodyString().transform(ModelSimulation::classifyCatalogResponse)
                        .in("ok", "recover:expired", "recover:session")
                        .saveAs("catalogOutcome"),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("catalogStatus")
                && session.getInt("catalogStatus") == 401
                && isRecoverable(session.getString("catalogOutcome"))).then(
                recoverSession("catalogOutcome")
                    .exec(doIf(session -> "true".equals(session.getString("sessionRecovered"))).then(
                        exec(http("catalog retry").get("/v2/catalog")
                            .header("X-CSRF-Token", "#{csrf}")
                            .check(
                                status().is(200),
                                bodyString().saveAs("catalogBody"),
                                jsonPath("$.csrf").optional().saveAs("csrf")))))))
            .exec(ModelSimulation::selectProduct)
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartPayload))
                .check(
                    status().in(200, 201, 401),
                    status().saveAs("cartStatus"),
                    bodyString().transform(ModelSimulation::classifyCartCreateResponse)
                        .in("ok", "recover:expired", "recover:session")
                        .saveAs("cartOutcome"),
                    jsonPath("$.id").optional().saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("cartStatus")
                && session.getInt("cartStatus") == 401
                && isRecoverable(session.getString("cartOutcome"))).then(
                recoverSession("cartOutcome")
                    .exec(doIf(session -> "true".equals(session.getString("sessionRecovered"))).then(
                        exec(http("cart retry").post("/v2/carts")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody(ModelSimulation::cartPayload))
                            .check(
                                status().in(200, 201),
                                jsonPath("$.id").saveAs("cart"),
                                header("ETag").optional().saveAs("etag"),
                                jsonPath("$.csrf").optional().saveAs("csrf")))))))
            .exec(http("expiry probe").get("/v2/carts/#{cart}")
                .header("X-CSRF-Token", "#{csrf}")
                .check(
                    status().in(200, 401),
                    status().saveAs("probeStatus"),
                    bodyString().transform(ModelSimulation::classifyCartGetResponse)
                        .in("ok", "recover:expired", "recover:session")
                        .saveAs("probeOutcome"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("probeStatus")
                && session.getInt("probeStatus") == 401
                && isRecoverable(session.getString("probeOutcome"))).then(
                recoverSession("probeOutcome")
                    .exec(doIf(session -> "true".equals(session.getString("sessionRecovered"))).then(
                        exec(http("expiry probe retry").get("/v2/carts/#{cart}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .check(
                                status().is(200),
                                header("ETag").optional().saveAs("etag"),
                                jsonPath("$.csrf").optional().saveAs("csrf")))))))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(ModelSimulation::orderPayload))
                .check(
                    status().in(201, 401),
                    status().saveAs("orderStatus"),
                    bodyString().transform(ModelSimulation::classifyOrderResponse)
                        .in("accepted", "recover:expired", "recover:session")
                        .saveAs("orderOutcome"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("orderStatus")
                && session.getInt("orderStatus") == 401
                && isRecoverable(session.getString("orderOutcome"))).then(
                recoverSession("orderOutcome")
                    .exec(doIf(session -> "true".equals(session.getString("sessionRecovered"))).then(
                        exec(http("commit retry").post("/v2/orders")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .header("Idempotency-Key", "#{cart}")
                            .header("If-Match", "#{etag}")
                            .body(StringBody(ModelSimulation::orderPayload))
                            .check(
                                status().is(201),
                                jsonPath("$.accepted").is("true"),
                                jsonPath("$.csrf").optional().saveAs("csrf")))))));
    }

    public ModelSimulation() {
        setUp(scenario("matrix")
                .exec(repeat(CFG.path("iterations").asInt(2)).on(flow()))
                .injectOpen(atOnceUsers(CFG.path("users").asInt(2))))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

