class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.skip_depth = 0
        self.form_stack = []
        self.forms = []
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in ('template', 'noscript'):
            self.skip_depth += 1
            return
        if self.skip_depth > 0:
            return
        attr_map = {}
        for key, value in attrs:
            key = key.lower()
            if key not in attr_map:
                attr_map[key] = '' if value is None else value
        if tag == 'form':
            action = attr_map.get('action', '')
            self.form_stack.append(action)
            self.forms.append(action)
        elif tag == 'input':
            current_form = self.form_stack[-1] if self.form_stack else ''
            self.inputs.append((current_form, attr_map))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ('template', 'noscript') and self.skip_depth > 0:
            self.skip_depth -= 1
            return
        if self.skip_depth > 0:
            return
        if tag == 'form' and self.form_stack:
            self.form_stack.pop()


def extract_input_value(html_text, field_name, preferred_action=None):
    parser = FormParser()
    parser.feed(html_text or '')
    parser.close()
    candidates = []
    for form_action, attrs in parser.inputs:
        if attrs.get('name') == field_name and attrs.get('value'):
            is_disabled = 'disabled' in attrs
            matches_action = bool(preferred_action and preferred_action in form_action)
            candidates.append((matches_action, not is_disabled, attrs['value']))
    if not candidates:
        return ''
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return candidates[0][2]


def extract_form_action(html_text, prefix=''):
    parser = FormParser()
    parser.feed(html_text or '')
    parser.close()
    for action in parser.forms:
        if action and (not prefix or prefix in action):
            return action
    return parser.forms[0] if parser.forms else ''


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool['name']] += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool


