import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String BASE_URL =
        System.getenv("BASE_URL") != null && !System.getenv("BASE_URL").isEmpty()
            ? System.getenv("BASE_URL")
            : "http://127.0.0.1:8000";
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String jsonObject(String... kv) {
        ObjectNode node = JSON.createObjectNode();
        for (int i = 0; i + 1 < kv.length; i += 2) {
            if (kv[i + 1] != null) {
                node.put(kv[i], kv[i + 1]);
            }
        }
        return node.toString();
    }

    private static String extractCsrf(String html) {
        if (html == null) {
            return "";
        }
        String clean = html.replaceAll("(?s)<!--.*?-->", "");
        Matcher inputMatcher = Pattern.compile("(?is)<input\\b[^>]*>").matcher(clean);
        Pattern attrPattern = Pattern.compile(
            "(?i)(?:^|\\s|(?<=[\"']))([a-z0-9_:-]+)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+))");
        while (inputMatcher.find()) {
            String tag = inputMatcher.group();
            String inner = tag.substring(6, tag.length() - 1).trim();
            if (inner.endsWith("/")) {
                inner = inner.substring(0, inner.length() - 1);
            }
            String name = null;
            String value = null;
            Matcher attrMatcher = attrPattern.matcher(inner);
            while (attrMatcher.find()) {
                String attrName = attrMatcher.group(1);
                String attrVal = attrMatcher.group(2) != null ? attrMatcher.group(2)
                    : (attrMatcher.group(3) != null ? attrMatcher.group(3) : attrMatcher.group(4));
                if ("name".equalsIgnoreCase(attrName)) {
                    name = attrVal;
                } else if ("value".equalsIgnoreCase(attrName)) {
                    value = attrVal;
                }
            }
            if ("csrf".equals(name) && value != null && !value.isEmpty()) {
                return value;
            }
        }
        return "";
    }

    private static Session extractAuthFields(Session session, String bodyKey) {
        String body = session.contains(bodyKey) ? session.getString(bodyKey) : null;
        Session updated = session.remove(bodyKey);
        if (body == null || body.isBlank()) {
            return updated;
        }
        try {
            JsonNode node = JSON.readTree(body);
            if (node.hasNonNull("csrf") && !node.path("csrf").asText().isEmpty()) {
                updated = updated.set("csrf", node.path("csrf").asText());
            }
            if (node.hasNonNull("grant_id") && !node.path("grant_id").asText().isEmpty()) {
                updated = updated.set("grant", node.path("grant_id").asText());
            }
        } catch (IOException ignored) {
            return updated;
        }
        return updated;
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session
                            .set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException ignored) {
            return session;
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .set("csrf", "")
                .set("grant", "")
                .remove("formCsrf")
                .remove("location")
                .remove("loginBody")
                .remove("redirectBody")
                .remove("catalogBody")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    bodyString().transform(ModelSimulation::extractCsrf).not("").saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> jsonObject(
                    "username", username(session),
