import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final double TARGET_RATE = 5.0;
    private static final Duration INJECTION_DURATION = Duration.ofSeconds(37);
    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String baseUrl() {
        String env = System.getenv("BASE_URL");
        return (env == null || env.isBlank()) ? "http://127.0.0.1:8000" : env;
    }

    private static String username(Session session) {
        return "bench-" + (Math.floorMod(session.userId() - 1, 16) + 1);
    }

    private static String loginPayload(Session session) {
        try {
            return JSON.writeValueAsString(
                JSON.createObjectNode()
                    .put("username", username(session))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
            );
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static Session extractCsrf(Session session, String bodyKey) {
        if (!session.contains(bodyKey)) {
            return session;
        }
        String body = session.getString(bodyKey);
        if (body == null || body.isBlank()) {
            return session;
        }
        try {
            JsonNode csrf = JSON.readTree(body).path("csrf");
            if (csrf.isTextual() && !csrf.asText().isEmpty()) {
                return session.set("csrf", csrf.asText());
            }
        } catch (IOException ignored) {
            return session;
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "")
                .remove("formCsrf")
                .remove("location")
                .remove("loginBody")
                .remove("redirectBody"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(ModelSimulation::loginPayload))
                .check(status().in(200, 302),
                    header("Location").optional().saveAs("location"),
                    bodyString().optional().saveAs("loginBody")))
            .exec(session -> extractCsrf(session, "loginBody"))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200),
                        bodyString().optional().saveAs("redirectBody")))
                .exec(session -> extractCsrf(session, "redirectBody"))));
    }

    private static ChainBuilder work() {
        return login()
            .exec(http("work").post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().is(200),
                    jsonPath("$.ok").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        setUp(
            scenario("work")
                .exec(work())
                .injectOpen(constantUsersPerSec(TARGET_RATE).during(INJECTION_DURATION))
        ).protocols(HTTP);
    }
}
