    private static String extractInputFromFragment(String fragment, String targetName) {
        Matcher inputMatcher = INPUT_TAG.matcher(fragment);
        while (inputMatcher.find()) {
            String attrs = inputMatcher.group(1);
            String name = null;
            String value = null;
            boolean disabled = false;
            Matcher attrMatcher = HTML_ATTR.matcher(attrs);
            while (attrMatcher.find()) {
                String attrName = attrMatcher.group(1).toLowerCase(Locale.ROOT);
                String attrVal = attrMatcher.group(2) != null ? attrMatcher.group(2)
                    : (attrMatcher.group(3) != null ? attrMatcher.group(3) : attrMatcher.group(4));
                if ("name".equals(attrName)) {
                    name = attrVal;
                } else if ("value".equals(attrName)) {
                    value = attrVal;
                } else if ("disabled".equals(attrName)) {
                    disabled = true;
                }
            }
            if (!disabled && targetName.equals(name) && value != null && !value.isEmpty()) {
                return value;
            }
        }
        return null;
    }

