        String fallbackFromForm = null;
        while (formMatcher.find()) {
            String formAttrs = formMatcher.group(1).toLowerCase(Locale.ROOT);
            String formBody = formMatcher.group(2);
            String val = extractInputFromFragment(formBody, "csrf");
            if (val != null) {
                if (formAttrs.contains("login")) {
                    return val;
                }
                if (fallbackFromForm == null) {
                    fallbackFromForm = val;
                }
            }
        }
        if (fallbackFromForm != null) {
            return fallbackFromForm;
        }
        String val = extractInputFromFragment(cleaned, "csrf");
        return val != null ? val : "";
