import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'partition' };
const rows = JSON.parse(open('/fixtures/accounts.json'));
const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

let csrf = '';
let cart = '';
let grant = '';

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function body(r) {
  try {
    return r.json() || {};
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  if (!r || !r.headers) return undefined;
  if (r.headers[name] !== undefined) return r.headers[name];
  const target = name.toLowerCase();
  for (const key in r.headers) {
    if (key.toLowerCase() === target) return r.headers[key];
  }
  return undefined;
}

function accountForVu() {
  const index = (__VU - 1) % rows.length;
  return rows[index];
}

function findValidInput(scope, name) {
  const inputs = scope.find('input[name="' + name + '"]');
  for (let i = 0; i < inputs.size(); i++) {
    const inp = inputs.eq(i);
    if (inp.attr('disabled') !== undefined) continue;
    const val = inp.attr('value');
    if (val) return val;
  }
  return '';
}

function extractCsrf(r) {
  const doc = r.html();
  const forms = doc.find('form');
  for (let i = 0; i < forms.size(); i++) {
    const f = forms.eq(i);
    const action = (f.attr('action') || '').toLowerCase();
    if (action.indexOf('/v2/login') >= 0) {
      const v = findValidInput(f, 'csrf');
      if (v) return v;
    }
  }
  for (let i = 0; i < forms.size(); i++) {
    const f = forms.eq(i);
    if (f.find('input[name="username"]').size() > 0 || f.find('input[name="password"]').size() > 0) {
      const v = findValidInput(f, 'csrf');
      if (v) return v;
    }
  }
  for (let i = 0; i < forms.size(); i++) {
    const v = findValidInput(forms.eq(i), 'csrf');
    if (v) return v;
  }
  const v = findValidInput(doc, 'csrf');
  if (v) return v;
  return doc.find('input[name="csrf"]').first().attr('value') || '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const url = /^https?:\/\//i.test(path) ? path : base + path;
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  const r = http.request(method, url, data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s',
  });
  const b = body(r);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = extractCsrf(r);
  const row = accountForVu();
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });
  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) {
      r = raw(loc);
      const b = body(r);
      if (b.grant_id) grant = b.grant_id;
    }
  }
  check(r, { login: (res) => res.status === 200 });
  return r;
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  const b = body(r);
  if (r.status === 401 && (b.error === 'expired' || b.error === 'session')) {
    const renewed = raw('/v2/session/renew', 'POST', {});
    if (renewed.status !== 200) login();
    if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
    r = raw(path, method, data, extra);
  }
  return r;
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';

  const loginRes = login();
  if (loginRes.status !== 200) return;

  sleep(0.15);

  const catalogRes = request('/v2/catalog');
  const catalogBody = body(catalogRes);
  const products = (catalogBody.data && catalogBody.data.products) || [];
  const product = products.find((p) => Array.isArray(p.variants) && p.variants.some((v) => v.in_stock));
  if (!product) {
    check(false, { 'eligible product': (x) => x });
    return;
  }
  const variant = product.variants.find((v) => v.in_stock);

  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (grant) cartPayload.grant_id = grant;

  let r = request('/v2/carts', 'POST', cartPayload);
  const cartBody = body(r);
  cart = cartBody.id || '';
  const etag = header(r, 'ETag');
  check(r, { cart: (res) => res.status === 201 && Boolean(cart) });
  if (r.status !== 201 || !cart) return;

  sleep(0.15);

  const orderHeaders = { 'Idempotency-Key': cart };
  if (etag) orderHeaders['If-Match'] = etag;
  r = request('/v2/orders', 'POST', { cart_id: cart }, orderHeaders);
  check(r, { accepted: (res) => res.status === 201 && body(res).accepted === true });
}

export default function () {
  flow();
}

from html.parser import HTMLParser
import json
import os
import re
import time

from gevent import sleep
from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'partition'}
MODE = CFG.get('mode', 'flow')
with open('/fixtures/accounts.json', encoding='utf-8') as accounts_file:
    ROWS = json.load(accounts_file)
DURATION = CFG.get('duration', 35)
POOLS = CFG.get('pools') or [{'name': 'work', 'path': CFG.get('path', '/v2/work'),
                              'rate': CFG.get('rate', 5),
                              'operation': CFG.get('operation', 'work')}]
if isinstance(POOLS, dict):
    POOLS = [dict(pool, name=name) for name, pool in POOLS.items()]


class CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.login_form_tokens = []
        self.form_tokens = []
        self.tokens = []
        self.in_form = False
        self.in_login_form = False
        self.in_template = False

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == 'template':
            self.in_template = True
            return
        if self.in_template:
            return
        attr_map = {key.lower(): value for key, value in attrs}
        if tag == 'form':
            self.in_form = True
            action = attr_map.get('action') or ''
            self.in_login_form = (not action) or ('login' in action.lower())
        elif tag == 'input':
            if attr_map.get('name') == 'csrf' and 'disabled' not in attr_map:
                value = attr_map.get('value')
                if value:
                    self.tokens.append(value)
                    if self.in_form:
                        self.form_tokens.append(value)
                        if self.in_login_form:
                            self.login_form_tokens.append(value)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == 'template':
            self.in_template = False
        elif tag == 'form':
            self.in_form = False
            self.in_login_form = False

    def token(self):
        if self.login_form_tokens:
            return self.login_form_tokens[0]
        if self.form_tokens:
            return self.form_tokens[0]
        if self.tokens:
            return self.tokens[0]
        return None


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
