import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';

const cfg = {"users": 2, "iterations": 2, "mode": "flow", "workload": true, "operation": "journey", "path": "/v2/orders", "rate": 1, "max_vus": 4};
const rows = [
  {"username": "bench-1", "password": "bench", "quantity": 2},
  {"username": "bench-2", "password": "bench", "quantity": 3},
  {"username": "bench-3", "password": "bench", "quantity": 4},
  {"username": "bench-4", "password": "bench", "quantity": 5},
  {"username": "bench-5", "password": "bench", "quantity": 6},
  {"username": "bench-6", "password": "bench", "quantity": 7},
  {"username": "bench-7", "password": "bench", "quantity": 8},
  {"username": "bench-8", "password": "bench", "quantity": 9},
  {"username": "bench-9", "password": "bench", "quantity": 10},
  {"username": "bench-10", "password": "bench", "quantity": 11},
  {"username": "bench-11", "password": "bench", "quantity": 12},
  {"username": "bench-12", "password": "bench", "quantity": 13},
  {"username": "bench-13", "password": "bench", "quantity": 14},
  {"username": "bench-14", "password": "bench", "quantity": 15},
  {"username": "bench-15", "password": "bench", "quantity": 16},
  {"username": "bench-16", "password": "bench", "quantity": 17},
];
const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    phase0: {
      executor: 'constant-arrival-rate',
      rate: 1,
      timeUnit: '1s',
      duration: '36s',
      startTime: '0s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    checks: ['rate>=0.99'],
  },
  noCookiesReset: true,
};

let csrf = '', cart = '', grant = '';
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  if (!r || !r.headers) return '';
  const target = name.toLowerCase();
  for (const k in r.headers) {
    if (k.toLowerCase() === target) return r.headers[k];
  }
  return '';
}

function resolveUrl(pathOrUrl) {
  if (!pathOrUrl) return base;
  if (/^https?:\/\//i.test(pathOrUrl)) return pathOrUrl;
  return base + pathOrUrl;
}

function extractCsrf(r) {
  const doc = r.html();
  const selectors = [
    'form[action*="/v2/login"] input[name="csrf"]:not([disabled])',
    'form input[name="csrf"]:not([disabled])',
    'input[name="csrf"]:not([disabled])',
    'input[name="csrf"]',
  ];
  for (let i = 0; i < selectors.length; i++) {
    const val = doc.find(selectors[i]).first().attr('value');
    if (val) return val;
  }
  return '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && csrf) headers['X-CSRF-Token'] = csrf;
  const r = http.request(method, resolveUrl(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s',
  });
  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = extractCsrf(r);
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token});
  if (r.status === 302) {
    const loc = header(r, 'location');
    r = raw(loc);
    grant = body(r).grant_id || '';
  }
  check(r, {'login': res => res.status === 200});
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401 && ['expired', 'session'].indexOf(body(r).error) >= 0) {
    const renewed = raw('/v2/session/renew', 'POST', {});
    if (renewed.status !== 200) login();
    if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
    r = raw(path, method, data, extra);
  }
  return r;
}

function work(override) {
  if (cfg.workload || !csrf) login();
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    sleep(Number(header(r, 'retry-after') || 1) + 0.01);
    r = request(path, 'POST', {});
  }
  check(r, {'operation or expected throttle': res => (res.status === 200 && body(res).ok === true) || (cfg.completion && res.status === 429)});
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  try {
    if (cfg.mode === 'ownership' && __VU === 2) sleep(0.5);
    login();
    if (cfg.mode === 'challenge') {
      let r = request('/v2/challenge-form');
      const form = r.html().find('form');
      const token = form.find('input[name="challenge"]').first().attr('value');
      r = request(form.attr('action'), 'POST', {challenge: token});
      r = request(header(r, 'location'));
      grant = body(r).grant_id || '';
    }
    let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
    let product = null;
    for (let n = 0; n < 3 && page; n++) {
      const b = body(request(page));
      const products = (b && b.data && Array.isArray(b.data.products)) ? b.data.products : [];
      product = products.find(p => Array.isArray(p.variants) && p.variants.some(v => v.in_stock));
      if (product) break;
      page = b ? b.next : null;
    }
    if (!product) {
      check(false, {'eligible product': x => x});
      return;
    }
    const variant = product.variants.find(v => v.in_stock);
    const cartPayload = {product_id: product.id, variant_id: variant.id};
    if (grant) cartPayload.grant_id = grant;
    let r = request('/v2/carts', 'POST', cartPayload);
    cart = body(r).id || '';
    let etag = header(r, 'etag');
    check(r, {'cart': res => res.status === 201});
    if (!cart) return;
    if (cfg.mode === 'ownership') sleep(__VU === 1 ? 1.2 : 1.6);
    if (cfg.mode === 'etag' || cfg.mode === 'data') {
      const quantity = cfg.mode === 'data' ? rows[(__VU - 1) % rows.length].quantity : (cfg.quantity || 2);
      r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
      if (r.status === 412) {
        etag = header(request('/v2/carts/' + cart), 'etag');
        r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
      }
      etag = header(r, 'etag') || etag;
      check(r, {'update': res => res.status === 200});
    }
    let reservation;
    if (cfg.mode === 'reservation') {
      r = request('/v2/reservations', 'POST', {cart_id: cart});
      const url = body(r).status_url;
      for (let n = 0; n < 5; n++) {
        sleep(0.05);
        r = request(url);
        const b = body(r);
        if (b.status === 'ready') {
          reservation = b.reservation_id;
          break;
        }
        if (b.status === 'failed') {
          check(false, {'reservation ready': x => x});
          return;
        }
      }
      if (!reservation) return;
    }
    const orderPayload = {cart_id: cart};
    if (reservation) orderPayload.reservation_id = reservation;
    const orderHeaders = {'Idempotency-Key': cart};
    if (etag) orderHeaders['If-Match'] = etag;
    r = request('/v2/orders', 'POST', orderPayload, orderHeaders);
    check(r, {'accepted': res => res.status === 201 && body(res).accepted === true});
  } finally {
    sleep(1);
  }
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

from html.parser import HTMLParser
import os
import re
import time

from gevent import sleep
from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'flow', 'workload': True, 'operation': 'journey', 'path': '/v2/orders', 'rate': 1, 'max_vus': 4}
MODE = CFG.get('mode', 'flow')
ROWS = [{"username": "bench-1", "password": "bench", "quantity": 2}, {"username": "bench-2", "password": "bench", "quantity": 3}, {"username": "bench-3", "password": "bench", "quantity": 4}, {"username": "bench-4", "password": "bench", "quantity": 5}, {"username": "bench-5", "password": "bench", "quantity": 6}, {"username": "bench-6", "password": "bench", "quantity": 7}, {"username": "bench-7", "password": "bench", "quantity": 8}, {"username": "bench-8", "password": "bench", "quantity": 9}, {"username": "bench-9", "password": "bench", "quantity": 10}, {"username": "bench-10", "password": "bench", "quantity": 11}, {"username": "bench-11", "password": "bench", "quantity": 12}, {"username": "bench-12", "password": "bench", "quantity": 13}, {"username": "bench-13", "password": "bench", "quantity": 14}, {"username": "bench-14", "password": "bench", "quantity": 15}, {"username": "bench-15", "password": "bench", "quantity": 16}, {"username": "bench-16", "password": "bench", "quantity": 17}]
DURATION = CFG.get('duration', 35)
POOLS = CFG.get('pools') or [{'name': 'work', 'path': CFG.get('path', '/v2/work'),
                              'rate': CFG.get('rate', 5),
                              'operation': CFG.get('operation', 'work')}]
if isinstance(POOLS, dict):
    POOLS = [dict(pool, name=name) for name, pool in POOLS.items()]


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.form_action = ''
        self.in_form = False
        self.ignored = 0
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in ('template', 'noscript'):
            self.ignored += 1
            return
        if self.ignored:
            return
        attr_map = {k.lower(): ('' if v is None else v) for k, v in attrs}
        if tag == 'form':
            self.in_form = True
            if not self.form_action and attr_map.get('action'):
                self.form_action = attr_map['action']
        elif tag == 'input':
            self.inputs.append((self.in_form, attr_map))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ('template', 'noscript') and self.ignored:
            self.ignored -= 1
        elif tag == 'form' and not self.ignored:
            self.in_form = False


def parse_form(html_text):
    parser = FormParser()
    parser.feed(html_text or '')
    parser.close()
    return parser


def extract_input(parser, name, html_text=''):
    candidates = []
    for in_form, attrs in parser.inputs:
        if attrs.get('name') == name and 'disabled' not in attrs and attrs.get('value'):
            candidates.append((in_form, attrs['value']))
    for in_form, value in candidates:
        if in_form:
            return value
    if candidates:
        return candidates[0][1]
    match = re.search(
        r'<input(?=[^>]*\bname=["\']' + re.escape(name) + r'["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
        html_text or '', re.IGNORECASE)
    return match.group(1) if match else ''


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()
        self.done = False
        self.active = 0
        self.all_done = Event()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                base = offset + number / rate
                if pool.get('operation') == 'journey' and number > 0:
                    base += min(0.5 / rate, 0.5)
                return base
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                self.done = True
                if self.active == 0:
                    self.all_done.set()
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool['name']] += 1
            remaining = [self.slot(p, self.counts[p['name']]) for p in POOLS]
            if all(item is None for item in remaining):
                self.done = True
            self.active += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool

    def finish(self):
        with self.lock:
            if self.active > 0:
                self.active -= 1
            if self.done and self.active == 0:
                self.all_done.set()


ARRIVALS = ArrivalPlan()
OWNER = {'logins': 0, 'ready': Event(), 'lock': Semaphore()}
USER_SEQ = {'n': 0, 'lock': Semaphore()}


class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
    wait_time = lambda self: 0

    def on_start(self):
        worker_id = getattr(self, '_p95_worker_id', None)
        if worker_id and '-' in str(worker_id):
            number = int(str(worker_id).rsplit('-', 1)[1])
        else:
            with USER_SEQ['lock']:
                USER_SEQ['n'] += 1
                number = USER_SEQ['n']
        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = ('bench' if MODE == 'ownership' else
                         self.row['username'] if MODE in ('data', 'partition') else
                         'bench-' + str((number - 1) % 16 + 1))
        self.password = self.row.get('password', 'bench')
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=3) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except ValueError:
                body = {}
            error = body.get('error')
            ok_status = 200 <= response.status_code < 400
            allowed = (ok_status
                       or response.status_code == 401 and error in ('expired', 'session')
                       or response.status_code == 412 and error in ('etag', 'etag_conflict')
                       or response.status_code == 429 and path.split('?', 1)[0] == '/v2/work')
            if (path.startswith('/v2/jobs/') and ok_status
                    and body.get('status') == 'failed'
                    or path.split('?', 1)[0] == '/v2/orders' and method == 'POST'
                    and ok_status
                    and body.get('accepted') is not True):
                allowed = False
            if name == 'checkout' and response.elapsed.total_seconds() * 1000 >= 250:
                allowed = False
            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')
                self.environment.process_exit_code = 99
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def login(self):
        self.csrf = ''
        form, _ = self.raw('/v2/login-form')
        parsed = parse_form(form.text)
        token = extract_input(parsed, 'csrf', form.text)
        if not token:
            self.environment.process_exit_code = 99
            return
        response, body = self.raw('/v2/login', 'POST',
                                  {'username': self.username, 'password': self.password,
                                   'csrf': token})
        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                _, body = self.request(location)
        self.grant = body.get('grant_id', '')

    def recover(self):
        renewed, _ = self.raw('/v2/session/renew', 'POST', {})
        if renewed.status_code != 200:
            self.login()
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
            self.etag = response.headers.get('ETag', self.etag)

    def request(self, path, method='GET', data=None, headers=None, name=None):
        req_headers = dict(headers) if headers else None
        for _ in range(2):
            response, body = self.raw(path, method, data, req_headers, name)
            if response.status_code == 401 and body.get('error') in ('expired', 'session'):
                self.recover()
                if req_headers and 'If-Match' in req_headers and self.etag:
                    req_headers['If-Match'] = self.etag
                continue
            return response, body
        return response, body

    def work(self, path='/v2/work'):
        if not self.csrf:
            self.login()
        for _ in range(5):
            response, _ = self.request(path, 'POST', {})
            if response.status_code != 429:
                return
            sleep(float(response.headers.get('Retry-After', 0.01)) + 0.01)

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.login()
        if MODE == 'ownership':
            with OWNER['lock']:
                OWNER['logins'] += 1
                if OWNER['logins'] >= CFG.get('users', 2):
                    OWNER['ready'].set()
            if not OWNER['ready'].wait(5):
                self.environment.process_exit_code = 99
                return
            if getattr(self, '_p95_worker_id', '') != 'user-1':
                sleep(0.5)
        if MODE == 'challenge':
            page, _ = self.request('/v2/challenge-form')
            parsed = parse_form(page.text)
            action = parsed.form_action
            if not action:
                match = re.search(
                    r'<form\b[^>]*\baction=["\']([^"\']+)["\']', page.text, re.IGNORECASE)
                action = match.group(1) if match else ''
            challenge = extract_input(parsed, 'challenge', page.text)
            if not action or not challenge:
                self.environment.process_exit_code = 99
                return
            response, _ = self.request(action, 'POST', {'challenge': challenge})
            location = response.headers.get('Location')
            if location:
                _, body = self.request(location)
                self.grant = body.get('grant_id', '')
        page = '/v2/catalog/page' if MODE == 'pagination' else '/v2/catalog'
        product = None
        for _ in range(3):
            _, body = self.request(page)
            products = (body.get('data') or {}).get('products') or []
            product = next((item for item in products
                            if any(variant.get('in_stock') for variant in (item.get('variants') or []))),
                           None)
            if product:
                break
            page = body.get('next')
            if not page:
                break
        if not product:
            self.environment.process_exit_code = 99
            return
        variant = next(item for item in product['variants'] if item.get('in_stock'))
        cart_payload = {'product_id': product['id'], 'variant_id': variant['id']}
        if self.grant:
            cart_payload['grant_id'] = self.grant
        response, body = self.request('/v2/carts', 'POST', cart_payload)
        self.cart = body.get('id', '')
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
            return
        if MODE in ('etag', 'data'):
            quantity = self.row.get('quantity', 2) if MODE == 'data' else CFG.get('quantity', 2)
            headers = {'If-Match': self.etag} if self.etag else {}
            response, _ = self.request('/v2/carts/' + self.cart, 'PATCH',
                                       {'quantity': quantity}, headers)
            if response.status_code == 412:
                response, _ = self.request('/v2/carts/' + self.cart)
                self.etag = response.headers.get('ETag', self.etag)
                response, _ = self.request('/v2/carts/' + self.cart, 'PATCH',
                    {'quantity': quantity}, {'If-Match': self.etag} if self.etag else {})
            self.etag = response.headers.get('ETag', self.etag)
        reservation = None
        if MODE == 'reservation':
            _, body = self.request('/v2/reservations', 'POST', {'cart_id': self.cart})
            status_url = body.get('status_url')
            if not status_url:
                return
            for _ in range(5):
                sleep(0.05)
                _, state = self.request(status_url)
                if state.get('status') == 'ready':
                    reservation = state.get('reservation_id')
                    break
                if state.get('status') == 'failed':
                    return
            if not reservation:
                return
        body = {'cart_id': self.cart}
        if reservation:
            body['reservation_id'] = reservation
        order_headers = {'Idempotency-Key': self.cart}
        if self.etag:
            order_headers['If-Match'] = self.etag
        self.request('/v2/orders', 'POST', body, order_headers,
                     'checkout' if MODE == 'threshold' else None)

    @task
    def run_scenario(self):
        if CFG.get('workload'):
            pool = ARRIVALS.next()
            if pool is None:
                ARRIVALS.all_done.wait(10)
                raise StopUser()
            try:
                if pool.get('operation') == 'journey':
                    self.flow()
                    sleep(1)
                else:
                    self.work(pool['path'])
            finally:
                ARRIVALS.finish()
            return
        if MODE == 'errors':
            self.login()
            for _ in range(4):
                self.work()
        else:
            self.flow()
            sleep(1)
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        users = (CFG.get('max_vus', 64 if CFG.get('capacity') or CFG.get('pools') else 32)
                 if CFG.get('workload') else CFG.get('users', 2))
        elapsed = self.get_run_time()
        if CFG.get('workload'):
            if elapsed >= DURATION + 4 or (ARRIVALS.all_done.is_set() and elapsed >= DURATION + 0.5):
                return None
            return users, max(1, users)
        if self.first_tick:
            self.first_tick = False
            return users, max(1, users)
        return None if self.runner.user_count == 0 else (users, max(1, users))

