import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"users\": 2, \"iterations\": 2, \"mode\": \"errors\"}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .acceptHeader("application/json");

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static String baseUrl() {
        String env = System.getenv("BASE_URL");
        return (env == null || env.isBlank()) ? "http://127.0.0.1:8000" : env;
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static int statusOf(Session session, String key) {
        return session.contains(key) ? session.getInt(key) : 0;
    }

    private static String extractFormCsrf(String html) {
        if (html == null) {
            return "";
        }
        String cleaned = html
            .replaceAll("(?s)<!--.*?-->", "")
            .replaceAll("(?is)<script\\b[^>]*>.*?</script>", "")
            .replaceAll("(?is)<template\\b[^>]*>.*?</template>", "")
            .replaceAll("(?is)<noscript\\b[^>]*>.*?</noscript>", "");
        Pattern inputTag = Pattern.compile("(?is)<input\\b[^>]*>");
        Pattern nameAttr = Pattern.compile("(?i)(?<![A-Za-z0-9_-])name\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`/]+))");
        Pattern valueAttr = Pattern.compile("(?i)(?<![A-Za-z0-9_-])value\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`/]+))");
        Pattern disabledAttr = Pattern.compile("(?i)(?<![A-Za-z0-9_-])disabled(?![A-Za-z0-9_-])");
        Matcher tagMatcher = inputTag.matcher(cleaned);
        while (tagMatcher.find()) {
            String tag = tagMatcher.group();
            String unquoted = tag.replaceAll("\"[^\"]*\"|'[^']*'", "");
            if (disabledAttr.matcher(unquoted).find()) {
                continue;
            }
            Matcher nm = nameAttr.matcher(tag);
            if (!nm.find()) {
                continue;
            }
            String name = nm.group(1) != null ? nm.group(1) : (nm.group(2) != null ? nm.group(2) : nm.group(3));
            if (!"csrf".equals(name)) {
                continue;
            }
            Matcher vm = valueAttr.matcher(tag);
            if (vm.find()) {
                String value = vm.group(1) != null ? vm.group(1) : (vm.group(2) != null ? vm.group(2) : vm.group(3));
                if (value != null && !value.isEmpty()) {
                    return value;
                }
            }
        }
        return "";
    }

    private static Boolean isValidWorkBody(String body) {
        if (body == null || body.isBlank()) {
            return Boolean.TRUE;
        }
        try {
            JsonNode node = JSON.readTree(body);
            if (node.has("ok") && !node.path("ok").asBoolean(false)) {
                return Boolean.FALSE;
            }
            return !"denied".equals(node.path("error").asText(""));
        } catch (IOException error) {
            return Boolean.TRUE;
        }
    }

    private static Duration retryDelay(Session session) {
        try {
            String raw = session.getString("retryAfter");
            if (raw == null || raw.isBlank()) {
                return Duration.ofMillis(1010);
            }
            return Duration.ofMillis(Math.max(10, (long) (Double.parseDouble(raw.trim()) * 1000 + 10)));
        } catch (RuntimeException error) {
            return Duration.ofMillis(1010);
        }
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session.set("csrf", "").remove("formCsrf").remove("location"))
            .exec(http("login form").get("/v2/login-form")
                .check(
                    status().is(200),
                    bodyString().transform(ModelSimulation::extractFormCsrf).not("").saveAs("formCsrf")
                ))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> JSON.createObjectNode()
                    .put("username", username(session))
                    .put("password", "bench")
                    .put("csrf", session.getString("formCsrf"))
                    .toString()))
                .check(
                    status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")
                ))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(
                        status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf")
                    ))
            ));
    }

    private static ChainBuilder workAttempt(String name, String path, boolean allow401) {
        return exec(session -> session.set("workStatus", 0).remove("retryAfter").remove("workError"))
            .exec(http(name).post(path)
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().saveAs("workStatus"),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    allow401 ? status().in(200, 401, 429) : status().in(200, 429),
                    bodyString().transform(ModelSimulation::isValidWorkBody).is(Boolean.TRUE)
                ));
    }

    private static ChainBuilder recoverExpiry(String path) {
        return doIf(session -> statusOf(session, "workStatus") == 401
                && !"denied".equals(session.getString("workError"))
                && !"true".equals(session.getString("workRenewed"))).then(
            exec(session -> session.set("workRenewed", "true").set("renewStatus", 0))
                .exec(doIfOrElse(session -> "session".equals(session.getString("workError"))).then(
                    exec(http("renew").post("/v2/session/renew")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(
                            status().saveAs("renewStatus"),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            status().in(200, 401)
                        ))
                    .exec(doIf(session -> statusOf(session, "renewStatus") == 401).then(login()))
                ).orElse(
                    exec(http("renew").post("/v2/session/renew")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(
                            status().saveAs("renewStatus"),
                            jsonPath("$.csrf").optional().saveAs("csrf"),
                            status().is(200)
                        ))
                ))
                .exec(workAttempt("work retry", path, false))
        );
    }

    private static ChainBuilder workRequest(String path) {
        ChainBuilder chain = exec(session -> session.set("workRenewed", "false"))
            .exec(workAttempt("work", path, true))
            .exec(recoverExpiry(path));
        for (int retry = 0; retry < 4; retry++) {
            chain = chain.exec(doIf(session -> statusOf(session, "workStatus") == 429).then(
                pause(ModelSimulation::retryDelay)
                    .exec(doIfOrElse(session -> "true".equals(session.getString("workRenewed"))).then(
                        workAttempt("work retry", path, false)
                    ).orElse(
                        workAttempt("work retry", path, true).exec(recoverExpiry(path))
                    ))
            ));
        }
        return chain;
    }

    public ModelSimulation() {
        int users = CFG.path("users").asInt(2);
        int iterations = CFG.path("iterations").asInt(2);
        setUp(scenario("matrix")
            .exec(repeat(iterations).on(login().exec(repeat(4).on(workRequest("/v2/work")))))
            .injectOpen(atOnceUsers(users)))
            .protocols(HTTP);
    }
}

