  { username: 'bench-15', password: 'bench' },
  { username: 'bench-16', password: 'bench' },
];

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0'],
  },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
let csrf = '';

function body(r) {
  try {
    const j = r.json();
    return j && typeof j === 'object' ? j : {};
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  if (!r || !r.headers) return undefined;
  const target = name.toLowerCase();
  const keys = Object.keys(r.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) return r.headers[keys[i]];
  }
  return undefined;
}

function toPath(url) {
  if (!url) return '';
  if (url.indexOf(base) === 0) return url.slice(base.length);
  return url;
}

function extractCsrf(doc) {
  const selectors = [
    'form[action="/v2/login"] input[name="csrf"]',
    'form input[name="csrf"]',
    'input[name="csrf"]',
  ];
  for (let s = 0; s < selectors.length; s++) {
    const sel = doc.find(selectors[s]);
    for (let i = 0; i < sel.size(); i++) {
      const el = sel.eq(i);
      if (el.attr('disabled') !== undefined) continue;
      const v = el.attr('value');
      if (v) return v;
    }
  }
  const fallback = doc.find('input[name="csrf"]').first().attr('value');
  return fallback || '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  const r = http.request(
    method,
    base + path,
    data === null ? null : JSON.stringify(data),
    { headers, redirects: 0, timeout: '3s' }
  );
  const b = body(r);
  if (r.status >= 200 && r.status < 300 && b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    const isOk = r.status === 200 && b.ok === true;
    const isExpectedExpiry =
      r.status === 401 && (b.error === 'expired' || b.error === 'session');
    const isScheduled429 = r.status === 429;
    failure.add(!(isOk || isExpectedExpiry || isScheduled429));
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = extractCsrf(r.html());
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });
  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) r = raw(toPath(loc));
  }
  check(r, { login: (res) => res.status === 200 });
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) login();
      r = raw(path, method, data, extra);
    }
  }
  return r;
}

function work() {
  let r = request('/v2/work', 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const ra = Number(header(r, 'Retry-After')) || 1;
    sleep(ra + 0.01);
    r = request('/v2/work', 'POST', {});
  }
  check(r, {
    'work succeeded': (res) => res.status === 200 && body(res).ok === true,
  });
}

export default function () {
  csrf = '';
  login();
  for (let n = 0; n < 4; n++) {
    work();
  }
}
