import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

  private static final int NUM_USERS = 16;
  private static final long SLOT_INTERVAL_MS = 200L;
  private static final long USER_PERIOD_MS = NUM_USERS * SLOT_INTERVAL_MS;
  private static final long RUN_WINDOW_MS = 35_600L;

  private static final Pattern STRIP_COMMENTS =
      Pattern.compile("<!--.*?-->", Pattern.DOTALL);
  private static final Pattern STRIP_NON_CONTENT =
      Pattern.compile(
          "<(script|style|template|noscript)\\b[^>]*>.*?</\\1\\s*>",
          Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
  private static final Pattern JSON_CSRF =
      Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"\\\\]+)\"");

  private final Object slotLock = new Object();
  private int assignedSlots = 0;
  private long baseTimeMs = 0L;
  private final AtomicBoolean firstSuccessRecorded = new AtomicBoolean(false);
  private final AtomicLong deadlineMs = new AtomicLong(Long.MAX_VALUE);

  private static String resolveBaseUrl() {
    String env = System.getenv("BASE_URL");
    String url =
        (env == null || env.trim().isEmpty()) ? "http://127.0.0.1:8000" : env.trim();
    while (url.endsWith("/")) {
      url = url.substring(0, url.length() - 1);
    }
    return url;
  }

  private long assignFirstSlotMs() {
    synchronized (slotLock) {
      long now = System.currentTimeMillis();
      int slot = assignedSlots++;
      if (slot == 0) {
        baseTimeMs = now;
        deadlineMs.compareAndSet(Long.MAX_VALUE, now + RUN_WINDOW_MS);
      }
      return baseTimeMs + slot * SLOT_INTERVAL_MS;
    }
  }

  private void recordFirstSuccess(long workStartMs) {
    if (firstSuccessRecorded.compareAndSet(false, true)) {
      deadlineMs.set(workStartMs + RUN_WINDOW_MS);
    }
  }

  private static boolean isTagNameChar(char c) {
    return (c >= 'a' && c <= 'z')
        || (c >= 'A' && c <= 'Z')
        || (c >= '0' && c <= '9')
        || c == '-'
        || c == '_'
        || c == ':';
  }

  private static String extractCsrf(String html) {
    if (html == null || html.isEmpty()) {
      return "";
    }
    String cleaned = STRIP_COMMENTS.matcher(html).replaceAll(" ");
    cleaned = STRIP_NON_CONTENT.matcher(cleaned).replaceAll(" ");

    int len = cleaned.length();
    int i = 0;
    boolean inForm = false;
    boolean isLoginForm = false;
    String bestValue = "";
    int bestScore = Integer.MIN_VALUE;

    while (i < len) {
      int lt = cleaned.indexOf('<', i);
      if (lt < 0 || lt + 1 >= len) {
        break;
      }
      int pos = lt + 1;
      boolean closing = false;
      if (cleaned.charAt(pos) == '/') {
        closing = true;
        pos++;
      }
      int nameStart = pos;
      while (pos < len && isTagNameChar(cleaned.charAt(pos))) {
        pos++;
      }
      if (pos == nameStart) {
        i = lt + 1;
        continue;
      }
      String tagName = cleaned.substring(nameStart, pos).toLowerCase(Locale.ROOT);

      Map<String, String> attrs = new HashMap<>();
      while (pos < len) {
        while (pos < len && Character.isWhitespace(cleaned.charAt(pos))) {
          pos++;
        }
        if (pos >= len) {
          break;
        }
        char c = cleaned.charAt(pos);
        if (c == '>') {
          pos++;
          break;
        }
        if (c == '/') {
          pos++;
          if (pos < len && cleaned.charAt(pos) == '>') {
            pos++;
            break;
          }
          continue;
        }
        int attrStart = pos;
        while (pos < len) {
          char ac = cleaned.charAt(pos);
          if (Character.isWhitespace(ac) || ac == '=' || ac == '>' || ac == '/') {
            break;
          }
          pos++;
        }
        if (pos == attrStart) {
          pos++;
          continue;
        }
        String attrName = cleaned.substring(attrStart, pos).toLowerCase(Locale.ROOT);
        while (pos < len && Character.isWhitespace(cleaned.charAt(pos))) {
          pos++;
        }
        String attrVal = "";
        if (pos < len && cleaned.charAt(pos) == '=') {
          pos++;
          while (pos < len && Character.isWhitespace(cleaned.charAt(pos))) {
            pos++;
          }
          if (pos < len) {
            char qc = cleaned.charAt(pos);
            if (qc == '"' || qc == '\'') {
              pos++;
              int valStart = pos;
              while (pos < len && cleaned.charAt(pos) != qc) {
                pos++;
              }
              attrVal = cleaned.substring(valStart, pos);
              if (pos < len && cleaned.charAt(pos) == qc) {
                pos++;
              }
            } else {
              int valStart = pos;
              while (pos < len) {
                char vc = cleaned.charAt(pos);
                if (Character.isWhitespace(vc)
                    || vc == '>'
                    || (vc == '/' && pos + 1 < len && cleaned.charAt(pos + 1) == '>')) {
                  break;
                }
                pos++;
              }
              attrVal = cleaned.substring(valStart, pos);
            }
          }
        }
        attrs.put(attrName, attrVal);
      }

      if ("form".equals(tagName)) {
        if (closing) {
          inForm = false;
          isLoginForm = false;
        } else {
          inForm = true;
          String action = attrs.getOrDefault("action", "").toLowerCase(Locale.ROOT);
          isLoginForm = action.contains("login");
        }
      } else if (!closing && "input".equals(tagName)) {
        String name = attrs.get("name");
        String value = attrs.get("value");
        if ("csrf".equals(name) && value != null && !value.isEmpty()) {
          int score = 0;
          if (attrs.containsKey("disabled")) {
            score -= 100;
          }
          if (attrs.containsKey("hidden")) {
            score -= 50;
          }
          if (isLoginForm) {
            score += 20;
          } else if (inForm) {
            score += 10;
          }
          if ("hidden".equalsIgnoreCase(attrs.get("type"))) {
            score += 5;
          }
          if (score > bestScore) {
            bestScore = score;
            bestValue = value;
          }
        }
      }

      i = pos;
    }

    return bestValue;
  }

  private static String extractJsonOrHtmlCsrf(String body) {
    if (body == null || body.isEmpty()) {
      return "";
    }
    Matcher m = JSON_CSRF.matcher(body);
    if (m.find()) {
      return m.group(1);
    }
    if (body.indexOf('<') >= 0) {
      return extractCsrf(body);
    }
    return "";
  }

  private static long parseRetryAfterMs(String val) {
    long baseMs = 1000L;
    if (val != null && !val.trim().isEmpty()) {
      try {
        double secs = Double.parseDouble(val.trim());
        long parsed = (long) Math.ceil(secs * 1000.0);
        if (parsed >= 1000L) {
          baseMs = Math.min(parsed, 5000L);
        }
      } catch (NumberFormatException ignored) {
        baseMs = 1000L;
      }
