  const vu = __VU || 1;
  if (vu >= 1 && vu <= 16) {
    return `bench-${vu}`;
  }
  if (vu === 17) {
    return 'bench';
  }
  return `bench-${((vu - 1) % 16) + 1}`;
}

function getHeader(res, name) {
  if (!res || !res.headers) {
    return undefined;
  }
  const target = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === target) {
      const val = res.headers[key];
      return Array.isArray(val) ? val[0] : val;
    }
  }
  return undefined;
}

function resolveUrl(location) {
  if (/^https?:\/\//i.test(location)) {
    return location;
  }
  if (location.startsWith('/')) {
    return `${BASE_URL}${location}`;
  }
  return `${BASE_URL}/${location}`;
}

function parseJson(res) {
  if (!res || !res.body) {
    return null;
  }
  try {
    return JSON.parse(res.body);
  } catch (_) {
    return null;
  }
}

function extractCsrf(html) {
  if (!html || typeof html !== 'string') {
    return null;
  }

  const doc = parseHTML(html);
  const inputs = doc.find('input[name="csrf"]');
  let bestVal = null;
  let bestScore = -Infinity;

  for (let i = 0; i < inputs.size(); i++) {
    const el = inputs.eq(i);
    const val = el.attr('value');
    if (!val || !val.trim()) {
      continue;
    }

    let score = 0;
    const typeAttr = (el.attr('type') || '').toLowerCase();
    if (typeAttr === 'hidden') {
      score += 5;
    }

    if (el.attr('disabled') !== undefined) {
      score -= 100;
    }
    if (el.attr('data-decoy') !== undefined) {
      score -= 100;
    }
    if (el.parents('template, noscript').size() > 0) {
      score -= 100;
    }

    const selfIdClass = `${el.attr('id') || ''} ${el.attr('class') || ''}`;
    if (/decoy|fake|trap|honeypot|dummy/i.test(selfIdClass)) {
      score -= 100;
    }

    const selfStyle = el.attr('style') || '';
    if (
      /display\s*:\s*none|visibility\s*:\s*hidden/i.test(selfStyle) ||
      el.attr('aria-hidden') === 'true'
    ) {
      score -= 50;
    }
    if (el.attr('hidden') !== undefined && typeAttr !== 'hidden') {
      score -= 50;
    }

    const form = el.closest('form');
    if (form.size() > 0) {
      score += 10;
      const action = (form.attr('action') || '').toLowerCase();
      if (action.includes('/v2/login') || action.includes('login')) {
        score += 20;
      } else if (action && !action.startsWith('#')) {
        score -= 50;
      }
      if (form.find('input[name="username"], input[name="password"]').size() > 0) {
        score += 15;
      }
      const formIdClass = `${form.attr('id') || ''} ${form.attr('class') || ''}`;
      if (/decoy|fake|trap|honeypot|dummy/i.test(formIdClass)) {
        score -= 100;
      }
      const formStyle = form.attr('style') || '';
      if (
        form.attr('hidden') !== undefined ||
        form.attr('aria-hidden') === 'true' ||
        form.attr('data-decoy') !== undefined ||
        /display\s*:\s*none|visibility\s*:\s*hidden/i.test(formStyle)
      ) {
        score -= 50;
      }
    }

    if (el.parents('[hidden], [aria-hidden="true"], [data-decoy]').size() > 0) {
      score -= 50;
    }

    const styledAncestors = el.parents('[style]');
    for (let j = 0; j < styledAncestors.size(); j++) {
      const st = styledAncestors.eq(j).attr('style') || '';
      if (/display\s*:\s*none|visibility\s*:\s*hidden/i.test(st)) {
