      redirects: 0,
      timeout: REQUEST_TIMEOUT,
      tags: { name: 'POST /v2/login' },
    }
  );

  if (loginRes.status === 302) {
    const location = getHeader(loginRes, 'Location');
    if (!location) {
      check(loginRes, {
        'login redirect has Location': () => false,
      });
      return false;
    }
    loginRes = http.get(resolveUrl(location), {
      redirects: 0,
      timeout: REQUEST_TIMEOUT,
      tags: { name: 'GET /v2/login-redirect' },
    });
  }

  const loginData = parseJson(loginRes);
  const csrfToken = loginData && loginData.csrf ? loginData.csrf : formCsrf;
  const loginOk = check(loginRes, {
    'login status 200': (r) => r.status === 200,
    'login csrf available': () => Boolean(csrfToken),
  });
  if (!loginOk) {
    return false;
  }

  sessionCsrf = csrfToken;
  loggedIn = true;
  return true;
}

function renewSession(username) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': sessionCsrf || '',
    },
    redirects: 0,
    timeout: REQUEST_TIMEOUT,
    tags: { name: 'POST /v2/session/renew' },
  });

  if (renewRes.status === 200) {
    const data = parseJson(renewRes);
    if (data && data.csrf) {
      sessionCsrf = data.csrf;
    }
    loggedIn = true;
    return true;
  }

  return login(username);
}

export default function () {
  const username = getUsernameForVU();

  if (!loggedIn || !sessionCsrf) {
    if (!login(username)) {
      return;
    }
  }

  let authRecoveries = 0;
  let rateLimitRetries = 0;

  while (true) {
    const res = http.post(`${BASE_URL}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': sessionCsrf || '',
      },
      redirects: 0,
      timeout: REQUEST_TIMEOUT,
      tags: { name: 'POST /v2/work' },
    });

    const data = parseJson(res);

    if (res.status === 200 && data && data.ok === true) {
      if (data.csrf) {
        sessionCsrf = data.csrf;
      }
      businessFailure.add(0);
      check(res, {
        'work status 200 ok:true': () => true,
      });
      return;
    }

    if (res.status === 429) {
      if (rateLimitRetries < 4) {
        businessFailure.add(0);
        const retryAfter = getHeader(res, 'Retry-After');
        let waitSec = 1;
        if (retryAfter !== undefined) {
          const parsed = parseFloat(retryAfter);
          if (!Number.isNaN(parsed) && parsed > 0) {
            waitSec = parsed;
          }
        }
        sleep(waitSec);
        rateLimitRetries += 1;
        continue;
      }

      businessFailure.add(1);
      check(res, {
        'work status 200 ok:true': () => false,
      });
      return;
    }

    if (res.status === 401) {
      const errCode = data && data.error;

      if (errCode === 'expired') {
        if (authRecoveries < 1) {
          businessFailure.add(0);
          authRecoveries += 1;
          if (renewSession(username)) {
            continue;
          }
          check(res, {
            'work status 200 ok:true': () => false,
          });
          return;
        }
        businessFailure.add(1);
        check(res, {
          'work status 200 ok:true': () => false,
        });
        return;
      }

      if (errCode === 'session') {
        if (authRecoveries < 1) {
          businessFailure.add(0);
          authRecoveries += 1;
          if (login(username)) {
            continue;
          }
          check(res, {
            'work status 200 ok:true': () => false,
          });
          return;
        }
        businessFailure.add(1);
        check(res, {
          'work status 200 ok:true': () => false,
        });
        return;
      }

      businessFailure.add(1);
      check(res, {
        'work not denied': () => errCode !== 'denied',
        'work status 200 ok:true': () => false,
      });
      return;
    }

    businessFailure.add(1);
    check(res, {
      'work status 200 ok:true': () => false,
    });
    return;
  }
}

from __future__ import annotations

from collections import deque
from html.parser import HTMLParser
import os
import time
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
PASSWORD = "bench"
ACCOUNTS = tuple(f"bench-{i}" for i in range(1, 17))

TARGET_RATE = 5.0
SLOT_INTERVAL = 1.0 / TARGET_RATE  # 0.2s
USER_COUNT = 16
SPAWN_RATE = 16

WARMUP_SECONDS = 5.0
MEASURED_SECONDS = 30.0
POST_WINDOW_BUFFER = 0.25
SCHEDULE_END_AFTER_T0 = WARMUP_SECONDS + MEASURED_SECONDS + POST_WINDOW_BUFFER  # 35.25s
RETRY_DEADLINE_AFTER_T0 = WARMUP_SECONDS + MEASURED_SECONDS + 4.2  # 39.2s
HARD_STOP_AFTER_T0 = WARMUP_SECONDS + MEASURED_SECONDS + 4.6  # 39.6s

MAX_BURST_PER_SEC = 8  # strictly below ceil(1.5 * 5) + 1 = 9
BURST_WINDOW_SEC = 1.02
MAX_429_RETRIES = 4
MAX_AUTH_RECOVERIES = 1
REQUEST_TIMEOUT = 5.0


class CsrfInputParser(HTMLParser):
    IGNORED_CONTAINERS = frozenset({"script", "style", "template", "noscript"})
    VOID_TAGS = frozenset(
        {
            "area",
            "base",
            "br",
            "col",
            "embed",
            "hr",
            "img",
            "input",
            "link",
            "meta",
            "param",
            "source",
            "track",
            "wbr",
        }
    )

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self._stack: list[tuple[str, dict[str, str | None]]] = []
        self._forms_by_id: dict[str, dict[str, str | None]] = {}
        self.candidates: list[tuple[int, int, str]] = []
        self._order = 0

    def _in_ignored(self) -> bool:
        return any(tag in self.IGNORED_CONTAINERS for tag, _ in self._stack)

    @staticmethod
    def _is_hidden_style(style: str | None) -> bool:
        if not style:
            return False
        compact = "".join(style.lower().split())
        return "display:none" in compact or "visibility:hidden" in compact

    @staticmethod
    def _has_decoy_marker(attrs: dict[str, str | None]) -> bool:
        for k, v in attrs.items():
            kl = k.lower()
            vl = (v or "").lower()
            for word in ("decoy", "fake", "honeypot", "trap", "dummy"):
                if word in kl or word in vl:
                    return True
        return False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        tag_l = tag.lower()
        attr_map: dict[str, str | None] = {}
        for k, v in attrs:
            kl = k.lower()
            if kl not in attr_map:
                attr_map[kl] = v

        if tag_l == "form" and not self._in_ignored():
            fid = attr_map.get("id")
            if fid:
                self._forms_by_id[fid] = attr_map

        if tag_l == "input" and not self._in_ignored():
            if attr_map.get("name") == "csrf":
                val = attr_map.get("value")
                if val is not None and val != "":
                    self._record_candidate(attr_map, val)

        if tag_l not in self.VOID_TAGS:
            self._stack.append((tag_l, attr_map))

    def handle_startendtag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        tag_l = tag.lower()
        attr_map: dict[str, str | None] = {}
        for k, v in attrs:
            kl = k.lower()
            if kl not in attr_map:
                attr_map[kl] = v

        if tag_l == "input" and not self._in_ignored():
            if attr_map.get("name") == "csrf":
                val = attr_map.get("value")
                if val is not None and val != "":
                    self._record_candidate(attr_map, val)

    def handle_endtag(self, tag: str) -> None:
        tag_l = tag.lower()
        for idx in range(len(self._stack) - 1, -1, -1):
            if self._stack[idx][0] == tag_l:
                del self._stack[idx:]
                break

    def _record_candidate(self, attr_map: dict[str, str | None], val: str) -> None:
        score = 0
        if "disabled" in attr_map:
            score -= 100
        if "hidden" in attr_map:
            score -= 30
        if self._is_hidden_style(attr_map.get("style")):
            score -= 30
        if (attr_map.get("aria-hidden") or "").lower() == "true":
            score -= 20
        if self._has_decoy_marker(attr_map):
            score -= 80

        enclosing_form: dict[str, str | None] | None = None
        for anc_tag, anc_attrs in reversed(self._stack):
            if anc_tag == "form" and enclosing_form is None:
                enclosing_form = anc_attrs
            if "hidden" in anc_attrs or self._is_hidden_style(anc_attrs.get("style")):
                score -= 40
            if (anc_attrs.get("aria-hidden") or "").lower() == "true":
                score -= 20
            if self._has_decoy_marker(anc_attrs):
                score -= 80

        form_ref = attr_map.get("form")
        if enclosing_form is None and form_ref and form_ref in self._forms_by_id:
            enclosing_form = self._forms_by_id[form_ref]

        if enclosing_form is not None:
            score += 20
            action = (enclosing_form.get("action") or "").strip().lower()
            if "/v2/login" in action or action.endswith("/login") or action == "login":
                score += 50
            elif action == "":
                score += 10
            else:
                score -= 40

        self.candidates.append((score, -self._order, val))
        self._order += 1

    def best_csrf(self) -> str | None:
        if not self.candidates:
            return None
        best = max(self.candidates, key=lambda item: (item[0], item[1]))
        return best[2]


def extract_csrf_from_html(html_text: str) -> str | None:
    parser = CsrfInputParser()
    parser.feed(html_text)
    parser.close()
    return parser.best_csrf()


def normalize_same_host_path(location: str, base_host: str) -> str | None:
    loc = location.strip()
    if not loc:
        return None
    parsed = urlsplit(loc)
    base_parsed = urlsplit(base_host)
    if parsed.scheme or parsed.netloc:
        if parsed.netloc != base_parsed.netloc:
            return None
        path = parsed.path or "/"
        return f"{path}?{parsed.query}" if parsed.query else path
    resolved = urljoin("/v2/login", loc)
    res_parsed = urlsplit(resolved)
    path = res_parsed.path or "/"
    return f"{path}?{res_parsed.query}" if res_parsed.query else path


def extract_error_code(resp) -> str | None:
    try:
        data = resp.json()
    except ValueError:
        return None
    if isinstance(data, dict):
        err = data.get("error")
        if isinstance(err, str):
            return err
    return None


def parse_retry_after(header_val: str | None) -> float:
    wait_s = 1.0
    if header_val is not None:
        try:
            parsed = float(header_val.strip())
            if parsed > wait_s:
                wait_s = parsed
        except ValueError:
            pass
    return wait_s + 0.03


class SharedWorkState:
    def __init__(self) -> None:
        self.launch_mono: float | None = None
        self.schedule_start: float | None = None
        self.t0_mono: float | None = None
        self.next_slot_idx = 0
        self.account_idx = 0
        self.spawned_users = 0
        self.active_users = 0
        self.ready_users = 0
        self.schedule_done = False
        self.recent_valid_starts: deque[float] = deque()

    def ensure_launched(self) -> float:
        if self.launch_mono is None:
            self.launch_mono = time.monotonic()
        return self.launch_mono

    def next_account(self) -> str:
        account = ACCOUNTS[self.account_idx % len(ACCOUNTS)]
        self.account_idx += 1
        return account

    def is_stopping(self) -> bool:
        if self.schedule_done:
            return True
        if self.t0_mono is not None:
            if time.monotonic() >= self.t0_mono + SCHEDULE_END_AFTER_T0:
                self.schedule_done = True
                return True
        return False

    def past_retry_deadline(self, offset: float = 0.0) -> bool:
        now = time.monotonic()
        if self.t0_mono is not None:
            return (now + offset) >= (self.t0_mono + RETRY_DEADLINE_AFTER_T0)
        launch = self.ensure_launched()
        return (now + offset) >= (launch + 42.0)

    def record_valid_work_start(self, req_start_mono: float) -> None:
        if self.t0_mono is None or req_start_mono < self.t0_mono:
            self.t0_mono = req_start_mono

    def _slot_time(self, slot_idx: int) -> float:
        assert self.schedule_start is not None
        if slot_idx == 0:
            return self.schedule_start
        return self.schedule_start + (slot_idx - 0.5) * SLOT_INTERVAL

    def acquire_slot(self) -> int | None:
        launch = self.ensure_launched()

        while True:
            if self.is_stopping():
                return None

            now = time.monotonic()
            if self.schedule_start is None:
                if self.ready_users >= min(4, USER_COUNT) or (
                    now - launch >= 1.5 and self.ready_users >= 1
                ):
                    self.schedule_start = now
                    self.next_slot_idx = 0
                else:
                    time.sleep(0.02)
                    continue

            slot_idx = self.next_slot_idx
            slot_time = self._slot_time(slot_idx)

            if self.t0_mono is not None and slot_time >= (
                self.t0_mono + SCHEDULE_END_AFTER_T0
            ):
                self.schedule_done = True
                return None
            if self.t0_mono is None and (now - launch) >= 38.0:
                self.schedule_done = True
                return None

            wait = slot_time - now
            if wait > 0.6:
                time.sleep(min(0.2, wait - 0.4))
                continue

            # Claim slot atomically before sleeping
            self.next_slot_idx += 1
            if wait > 0.0:
                time.sleep(wait)

            if self.t0_mono is not None and time.monotonic() >= (
                self.t0_mono + SCHEDULE_END_AFTER_T0 + 0.25
            ):
                self.schedule_done = True
                return None

            return slot_idx

    def acquire_burst_token(self) -> float:
        while True:
            now = time.monotonic()
            cutoff = now - BURST_WINDOW_SEC
            while self.recent_valid_starts and self.recent_valid_starts[0] <= cutoff:
                self.recent_valid_starts.popleft()
            if len(self.recent_valid_starts) < MAX_BURST_PER_SEC:
                self.recent_valid_starts.append(now)
                return now
            sleep_for = (self.recent_valid_starts[0] + BURST_WINDOW_SEC) - now + 0.005
            time.sleep(max(sleep_for, 0.005))

    def release_burst_token(self, token_ts: float) -> None:
        try:
            self.recent_valid_starts.remove(token_ts)
        except ValueError:
            pass


STATE = SharedWorkState()


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self) -> None:
        STATE.ensure_launched()
        self._counted_active = False
        self.csrf = ""
        self.username = ""

        if STATE.is_stopping():
            raise StopUser()

        self.username = STATE.next_account()
        STATE.spawned_users += 1
        STATE.active_users += 1
        self._counted_active = True

        logged_in = False
        for _ in range(3):
            if STATE.is_stopping():
                raise StopUser()
            if self._login():
                logged_in = True
                break
            time.sleep(0.2)

        if not logged_in:
            raise StopUser()

        STATE.ready_users += 1

    def on_stop(self) -> None:
        if getattr(self, "_counted_active", False):
            self._counted_active = False
            STATE.active_users -= 1

    def _login(self) -> bool:
        self.client.cookies.clear()
        self.csrf = ""

        form_csrf: str | None = None
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"/v2/login-form failed with HTTP {resp.status_code}")
                return False
            form_csrf = extract_csrf_from_html(resp.text)
            if not form_csrf:
                try:
                    data = resp.json()
                    if isinstance(data, dict) and isinstance(data.get("csrf"), str):
                        form_csrf = data["csrf"]
                except ValueError:
                    pass
            if not form_csrf:
                resp.failure("Missing input[name=csrf] in /v2/login-form")
                return False
            resp.success()

        redirect_location: str | None = None
        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": self.username,
                "password": PASSWORD,
                "csrf": form_csrf,
            },
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if resp.status_code in (302, 303):
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("Login 302 missing Location header")
                    return False
                redirect_location = loc
                resp.success()
            elif resp.status_code in (200, 201):
                try:
                    data = resp.json()
                except ValueError:
                    resp.failure("Non-JSON response from /v2/login")
                    return False
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure("Missing csrf in /v2/login response")
                    return False
                self.csrf = str(data["csrf"])
                resp.success()
                return True
            else:
                resp.failure(f"Unexpected HTTP {resp.status_code} from /v2/login")
                return False

        if redirect_location is not None:
            target_path = normalize_same_host_path(redirect_location, self.host)
            if not target_path:
                return False
            with self.client.get(
                target_path,
                name="/v2/login-redirect",
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                if resp.status_code not in (200, 201):
                    resp.failure(
                        f"Login redirect failed with HTTP {resp.status_code}"
                    )
                    return False
                try:
                    data = resp.json()
                except ValueError:
                    resp.failure("Non-JSON response from login redirect")
                    return False
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure("Missing csrf in login redirect response")
                    return False
                self.csrf = str(data["csrf"])
                resp.success()
                return True

        return False

    def _renew_session(self) -> bool:
        fallback_login = False
        with self.client.post(
            "/v2/session/renew",
            name="/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            timeout=REQUEST_TIMEOUT,
            catch_response=True,
        ) as resp:
            if 200 <= resp.status_code < 400:
                try:
                    data = resp.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = str(data["csrf"])
                except ValueError:
                    pass
                resp.success()
                return True
            if resp.status_code == 401 and extract_error_code(resp) == "session":
                resp.success()
                fallback_login = True
            else:
                resp.failure(f"/v2/session/renew failed with HTTP {resp.status_code}")
                return False

        if fallback_login:
            return self._login()
        return False

    def _execute_work(self) -> None:
        auth_recoveries = 0
        rate_limit_retries = 0

        while True:
            if STATE.past_retry_deadline():
                return

            token_ts = STATE.acquire_burst_token()
            req_start_mono = time.monotonic()
            action = "done"
            wait_s = 0.0

            with self.client.post(
                "/v2/work",
                name="/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False,
                timeout=REQUEST_TIMEOUT,
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status == 200:
                    try:
                        data = resp.json()
                    except ValueError:
                        STATE.release_burst_token(token_ts)
                        resp.failure("Non-JSON 200 response from /v2/work")
                    else:
                        if isinstance(data, dict) and data.get("ok") is True:
                            if data.get("csrf"):
                                self.csrf = str(data["csrf"])
                            STATE.record_valid_work_start(req_start_mono)
                            resp.success()
                        else:
                            STATE.release_burst_token(token_ts)
                            resp.failure(f"Invalid /v2/work 200 payload: {data!r}")
                else:
                    STATE.release_burst_token(token_ts)
                    if status == 429:
                        if rate_limit_retries < MAX_429_RETRIES:
                            resp.success()
                            wait_s = parse_retry_after(resp.headers.get("Retry-After"))
                            action = "retry_429"
                        else:
                            resp.failure(
                                f"HTTP 429 persisted after {MAX_429_RETRIES} retries"
                            )
                    elif status == 401:
                        err = extract_error_code(resp)
                        if err == "expired" and auth_recoveries < MAX_AUTH_RECOVERIES:
                            resp.success()
                            action = "renew"
                        elif err == "session" and auth_recoveries < MAX_AUTH_RECOVERIES:
                            resp.success()
                            action = "relogin"
                        else:
                            resp.failure(f"Unauthorized /v2/work (401 error={err!r})")
                    else:
                        resp.failure(f"Unexpected HTTP {status} from /v2/work")

            if action == "done":
                return
            if action == "retry_429":
                rate_limit_retries += 1
                if STATE.past_retry_deadline(offset=wait_s):
                    return
                time.sleep(wait_s)
                continue
            if action == "renew":
                auth_recoveries += 1
                if not self._renew_session():
                    return
                continue
            if action == "relogin":
                auth_recoveries += 1
                if not self._login():
                    return
                continue

    @task
    def run_work(self) -> None:
        slot = STATE.acquire_slot()
        if slot is None:
            raise StopUser()
        self._execute_work()


class WorkLoadShape(LoadTestShape):
    def tick(self) -> tuple[int, float] | None:
        STATE.ensure_launched()
        now = time.monotonic()

        if STATE.t0_mono is not None:
            elapsed_t0 = now - STATE.t0_mono
            if elapsed_t0 >= HARD_STOP_AFTER_T0:
                STATE.schedule_done = True
                return None
            if STATE.schedule_done and STATE.active_users <= 0:
                return None
        else:
            run_time = self.get_run_time()
            if run_time >= 45.0:
                STATE.schedule_done = True
                return None
            if (
                run_time >= 15.0
                and STATE.spawned_users >= USER_COUNT
                and STATE.active_users <= 0
            ):
                STATE.schedule_done = True
                return None

        return (USER_COUNT, SPAWN_RATE)

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
