public class ModelSimulation extends Simulation {

    private static final Pattern COMMENT_PATTERN = Pattern.compile("<!--.*?-->", Pattern.DOTALL);
    private static final Pattern FORM_PATTERN = Pattern.compile("<form\\b([^>]*)>(.*?)</form>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern INPUT_PATTERN = Pattern.compile("<input\\b([^>]*)/?>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern ATTR_PATTERN = Pattern.compile(
        "([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+)))?"
    );

    public ModelSimulation() {
        String baseUrl = System.getenv("BASE_URL");
        if (baseUrl == null || baseUrl.isBlank()) {
            baseUrl = "http://127.0.0.1:8000";
        }

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

        List<Map<String, Object>> accounts = new ArrayList<>();
        for (int i = 1; i <= 16; i++) {
            accounts.add(Collections.singletonMap("username", "bench-" + i));
        }
        FeederBuilder<Object> accountFeeder = listFeeder(accounts).circular();

        ChainBuilder loginChain = exec(session ->
            session.removeAll("csrfList", "loginFormHtml", "loginStatus", "loginLocation", "loginBody", "redirectBody")
                .set("needRedirect", false)
        )
        .exec(
            http("login-form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    bodyString().optional().saveAs("loginFormHtml"),
                    css("input[name=csrf]", "value").findAll().exists().saveAs("csrfList")
                )
        )
        .exec(session -> {
            List<String> candidates = session.contains("csrfList") ? session.getList("csrfList") : Collections.emptyList();
            String html = session.contains("loginFormHtml") ? session.getString("loginFormHtml") : "";
            String token = selectCsrfToken(candidates, html);
            return session.set("csrf", token);
        })
        .exec(
            http("login")
                .post("/v2/login")
                .asJson()
                .body(StringBody(session -> buildLoginPayload(
                    session.getString("username"),
                    "bench",
                    session.contains("csrf") ? session.getString("csrf") : ""
                )))
                .check(
                    status().in(200, 302).saveAs("loginStatus"),
                    header("Location").optional().saveAs("loginLocation"),
                    bodyString().optional().saveAs("loginBody")
                )
        )
        .exec(session -> {
            Session updated = session;
            String body = session.contains("loginBody") ? session.getString("loginBody") : "";
            String freshCsrf = extractJsonString(body, "csrf");
            if (freshCsrf != null && !freshCsrf.isEmpty()) {
                updated = updated.set("csrf", freshCsrf);
            }
            boolean redirect = session.contains("loginStatus")
                && session.getInt("loginStatus") == 302
                && session.contains("loginLocation");
            return updated.set("needRedirect", redirect);
        })
        .doIf(session -> session.contains("needRedirect") && session.getBoolean("needRedirect")).then(
            exec(
                http("login-redirect")
                    .get("#{loginLocation}")
                    .check(
                        status().is(200),
                        bodyString().optional().saveAs("redirectBody")
                    )
            )
            .exec(session -> {
                String body = session.contains("redirectBody") ? session.getString("redirectBody") : "";
                String freshCsrf = extractJsonString(body, "csrf");
                if (freshCsrf != null && !freshCsrf.isEmpty()) {
                    return session.set("csrf", freshCsrf);
                }
                return session;
            })
        );

        ChainBuilder renewOrReloginChain = exec(session ->
            session.removeAll("renewStatus", "renewBody").set("needRelogin", false)
        )
        .exec(
            http("session-renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .asJson()
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401).saveAs("renewStatus"),
                    bodyString().optional().saveAs("renewBody")
                )
        )
        .exec(session -> {
            if (session.contains("renewStatus") && session.getInt("renewStatus") == 200) {
                String body = session.contains("renewBody") ? session.getString("renewBody") : "";
                String freshCsrf = extractJsonString(body, "csrf");
                Session updated = session.set("needRelogin", false);
                if (freshCsrf != null && !freshCsrf.isEmpty()) {
                    updated = updated.set("csrf", freshCsrf);
                }
                return updated;
            }
            return session.set("needRelogin", true);
        })
        .doIf(session -> session.contains("needRelogin") && session.getBoolean("needRelogin")).then(
            loginChain
        );

        ChainBuilder workOperation = exec(session -> {
            Map<String, Object> init = new HashMap<>();
            init.put("workDone", false);
            init.put("authRecovered", false);
            init.put("retry429Count", 0);
            init.put("retryPauseMs", 1000L);
            init.put("nextAction", "done");
            return session.setAll(init);
        })
        .asLongAs(session -> !session.getBoolean("workDone")).on(
            exec(session ->
                session.removeAll("workStatus", "workOutcome", "workBody", "retryAfter")
                    .set("nextAction", "done")
            )
            .exec(
                http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(StringBody("{}"))
                    .check(
                        status().in(200, 401, 429).saveAs("workStatus"),
                        header("Retry-After").optional().saveAs("retryAfter"),
                        bodyString().saveAs("workBody"),
                        bodyString().transformWithSession((body, session) -> {
                            if (!session.contains("workStatus")) {
                                return "bad_status";
                            }
                            int code = session.getInt("workStatus");
                            if (code == 200) {
                                return isWorkOkTrue(body) ? "ok" : "bad_200";
                            }
                            if (code == 401) {
                                String err = extractJsonString(body, "error");
                                if ("expired".equals(err) || "session".equals(err)) {
                                    return "auth_" + err;
                                }
                                return "bad_401";
                            }
                            if (code == 429) {
                                return "retry_429";
                            }
                            return "bad_status";
                        }).in("ok", "auth_expired", "auth_session", "retry_429").saveAs("workOutcome")
                    )
            )
            .exec(session -> {
                String outcome = session.contains("workOutcome") ? session.getString("workOutcome") : "failed";
                if ("ok".equals(outcome)) {
                    Session updated = session.set("workDone", true).set("nextAction", "done");
                    String body = session.contains("workBody") ? session.getString("workBody") : "";
                    String freshCsrf = extractJsonString(body, "csrf");
                    if (freshCsrf != null && !freshCsrf.isEmpty()) {
                        updated = updated.set("csrf", freshCsrf);
                    }
                    return updated;
                }
                if ("auth_expired".equals(outcome) && !session.getBoolean("authRecovered")) {
                    return session.set("authRecovered", true).set("nextAction", "renew");
                }
                if ("auth_session".equals(outcome) && !session.getBoolean("authRecovered")) {
                    return session.set("authRecovered", true).set("nextAction", "relogin");
                }
                if ("retry_429".equals(outcome) && session.getInt("retry429Count") < 4) {
                    int nextCount = session.getInt("retry429Count") + 1;
                    String retryAfter = session.contains("retryAfter") ? session.getString("retryAfter") : null;
                    long pauseMs = parseRetryAfterMs(retryAfter);
                    return session.set("retry429Count", nextCount)
                        .set("retryPauseMs", pauseMs)
                        .set("nextAction", "wait_429");
                }
                return session.set("workDone", true).set("nextAction", "done");
            })
            .doIf(session -> "wait_429".equals(session.getString("nextAction"))).then(
                pause(session -> Duration.ofMillis(session.getLong("retryPauseMs")))
            )
            .doIf(session -> "renew".equals(session.getString("nextAction"))).then(
                renewOrReloginChain
            )
            .doIf(session -> "relogin".equals(session.getString("nextAction"))).then(
                loginChain
            )
        );

        ScenarioBuilder workScenario = scenario("work")
            .feed(accountFeeder)
            .exec(loginChain)
            .repeat(37).on(
                pace(Duration.ofSeconds(1)).exec(workOperation)
            );

        setUp(
            workScenario.injectOpen(rampUsers(5).during(Duration.ofSeconds(1)))
        )
        .protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(48));
    }

    private static String buildLoginPayload(String username, String password, String csrf) {
        return "{\"username\":\"" + jsonEscape(username)
            + "\",\"password\":\"" + jsonEscape(password)
            + "\",\"csrf\":\"" + jsonEscape(csrf) + "\"}";
    }

    private static String jsonEscape(String s) {
        if (s == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder(s.length() + 8);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    private static long parseRetryAfterMs(String retryAfter) {
        long defaultMs = 1000L;
        if (retryAfter == null || retryAfter.isBlank()) {
            return defaultMs;
        }
        try {
            double seconds = Double.parseDouble(retryAfter.trim());
            long ms = (long) Math.ceil(seconds * 1000.0);
            if (ms < 1000L) {
                return 1000L;
            }
            return Math.min(ms, 5000L);
        } catch (NumberFormatException e) {
            return defaultMs;
        }
    }

    private static String selectCsrfToken(List<String> candidates, String html) {
        if (candidates == null || candidates.isEmpty()) {
            return "";
        }
        if (candidates.size() == 1) {
            return candidates.get(0);
        }
        if (html != null && !html.isEmpty()) {
            String cleaned = COMMENT_PATTERN.matcher(html).replaceAll("");
            String formScope = extractLoginFormSection(cleaned);
            if (formScope != null) {
                String fromForm = findEnabledCsrfValue(formScope);
                if (fromForm != null && !fromForm.isEmpty()) {
                    return fromForm;
                }
            }
            String fromDoc = findEnabledCsrfValue(cleaned);
            if (fromDoc != null && !fromDoc.isEmpty()) {
                return fromDoc;
            }
        }
        for (String c : candidates) {
            if (c != null && !c.isEmpty()) {
                return c;
            }
        }
        return candidates.get(0);
    }

    private static String extractLoginFormSection(String html) {
        Matcher m = FORM_PATTERN.matcher(html);
        while (m.find()) {
            String attrs = m.group(1);
            if (attrs != null && attrs.contains("/v2/login")) {
                return m.group(2);
            }
        }
        return null;
    }

    private static String findEnabledCsrfValue(String html) {
        Matcher inputMatcher = INPUT_PATTERN.matcher(html);
        while (inputMatcher.find()) {
            String attrs = inputMatcher.group(1);
            if (attrs == null) {
                continue;
            }
            boolean disabled = false;
            String name = null;
            String value = null;
            Matcher attrMatcher = ATTR_PATTERN.matcher(attrs);
            while (attrMatcher.find()) {
                String attrName = attrMatcher.group(1);
                String attrVal = attrMatcher.group(2) != null ? attrMatcher.group(2)
                    : (attrMatcher.group(3) != null ? attrMatcher.group(3) : attrMatcher.group(4));
                if ("disabled".equalsIgnoreCase(attrName)) {
                    disabled = true;
                } else if ("name".equalsIgnoreCase(attrName)) {
                    name = attrVal;
                } else if ("value".equalsIgnoreCase(attrName)) {
                    value = attrVal;
                }
            }
            if (!disabled && "csrf".equals(name) && value != null && !value.isEmpty()) {
                return value;
            }
        }
        return null;
    }

    private static boolean isWorkOkTrue(String body) {
        Map<String, Object> obj = parseJsonObject(body);
        return Boolean.TRUE.equals(obj.get("ok"));
    }

    private static String extractJsonString(String body, String key) {
        Map<String, Object> obj = parseJsonObject(body);
        Object val = obj.get(key);
        return (val instanceof String) ? (String) val : null;
    }

    private static Map<String, Object> parseJsonObject(String json) {
        Map<String, Object> result = new HashMap<>();
        if (json == null) {
            return result;
        }
        int len = json.length();
        int idx = skipWhitespace(json, 0);
        if (idx >= len || json.charAt(idx) != '{') {
            return result;
        }
        idx++;
        while (idx < len) {
            idx = skipWhitespace(json, idx);
            if (idx >= len || json.charAt(idx) == '}') {
                break;
            }
            if (json.charAt(idx) != '"') {
                break;
            }
            StringBuilder keyBuf = new StringBuilder();
            idx = readJsonString(json, idx, keyBuf);
            if (idx < 0) {
                break;
            }
            String key = keyBuf.toString();
            idx = skipWhitespace(json, idx);
            if (idx >= len || json.charAt(idx) != ':') {
                break;
            }
            idx = skipWhitespace(json, idx + 1);
            if (idx >= len) {
                break;
            }
            char ch = json.charAt(idx);
            if (ch == '"') {
                StringBuilder valBuf = new StringBuilder();
                idx = readJsonString(json, idx, valBuf);
                if (idx < 0) {
                    break;
                }
                result.put(key, valBuf.toString());
            } else if (ch == '{' || ch == '[') {
                idx = skipJsonComposite(json, idx);
                if (idx < 0) {
                    break;
                }
            } else {
                int start = idx;
                while (idx < len) {
                    char c = json.charAt(idx);
                    if (c == ',' || c == '}' || Character.isWhitespace(c)) {
                        break;
                    }
                    idx++;
                }
                String token = json.substring(start, idx);
                if ("true".equals(token)) {
                    result.put(key, Boolean.TRUE);
                } else if ("false".equals(token)) {
                    result.put(key, Boolean.FALSE);
                } else if (!"null".equals(token)) {
                    result.put(key, token);
                }
            }
            idx = skipWhitespace(json, idx);
            if (idx < len && json.charAt(idx) == ',') {
                idx++;
            } else {
                break;
            }
        }
        return result;
    }

    private static int skipWhitespace(String s, int idx) {
        int len = s.length();
        while (idx < len && Character.isWhitespace(s.charAt(idx))) {
            idx++;
        }
        return idx;
    }

    private static int readJsonString(String s, int idx, StringBuilder out) {
        int len = s.length();
        if (idx >= len || s.charAt(idx) != '"') {
            return -1;
        }
        idx++;
        while (idx < len) {
            char c = s.charAt(idx++);
            if (c == '"') {
                return idx;
            }
            if (c == '\\') {
                if (idx >= len) {
                    return -1;
                }
                char esc = s.charAt(idx++);
                switch (esc) {
                    case '"':
                        out.append('"');
                        break;
                    case '\\':
                        out.append('\\');
                        break;
                    case '/':
                        out.append('/');
                        break;
                    case 'b':
                        out.append('\b');
                        break;
                    case 'f':
                        out.append('\f');
                        break;
                    case 'n':
                        out.append('\n');
                        break;
                    case 'r':
                        out.append('\r');
                        break;
                    case 't':
                        out.append('\t');
                        break;
                    case 'u':
                        if (idx + 4 > len) {
                            return -1;
                        }
                        try {
                            int code = Integer.parseInt(s.substring(idx, idx + 4), 16);
                            out.append((char) code);
                            idx += 4;
                        } catch (NumberFormatException e) {
                            return -1;
                        }
                        break;
                    default:
                        out.append(esc);
                        break;
                }
            } else {
                out.append(c);
            }
        }
        return -1;
    }

    private static int skipJsonComposite(String s, int idx) {
        int len = s.length();
        int depth = 0;
        boolean inString = false;
        while (idx < len) {
            char c = s.charAt(idx++);
            if (inString) {
                if (c == '\\') {
                    idx++;
                } else if (c == '"') {
                    inString = false;
                }
            } else {
                if (c == '"') {
                    inString = true;
                } else if (c == '{' || c == '[') {
                    depth++;
                } else if (c == '}' || c == ']') {
                    depth--;
                    if (depth == 0) {
                        return idx;
                    }
                }
            }
        }
        return -1;
    }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'ramping-arrival-rate',
      startRate: 2,
      timeUnit: '1s',
      preAllocatedVUs: 8,
      maxVUs: 16,
      stages: [
        { target: 5, duration: '2s' },
        { target: 5, duration: '35.5s' },
      ],
      gracefulStop: '2s',
    },
  },
  thresholds: {
    checks: ['rate>=0.99'],
    business_failure: ['rate<0.01'],
  },
};

const vuState = {
  loggedIn: false,
  csrf: '',
};

function getUsername() {
  return `bench-${((__VU - 1) % 16) + 1}`;
}

function safeJson(res) {
  if (!res || !res.body) {
    return null;
  }
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) {
    return '';
  }
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      const val = res.headers[keys[i]];
      return Array.isArray(val) ? String(val[0] || '') : String(val || '');
    }
  }
  return '';
}

function resolveUrl(location) {
  if (!location) {
    return '';
  }
  if (/^https?:\/\//i.test(location)) {
    return location;
  }
  if (location.startsWith('/')) {
    return `${BASE_URL}${location}`;
  }
  return `${BASE_URL}/${location}`;
}

function hasAttr(el, name) {
  const val = el.attr(name);
  return val !== undefined && val !== null;
}

function findValidCsrfInput(inputs) {
  const candidates = [];
  for (let i = 0; i < inputs.size(); i++) {
    const inp = inputs.eq(i);
    const val = inp.attr('value');
    if (!val || val.trim() === '') {
      continue;
    }
    candidates.push({
      value: val.trim(),
      disabled: hasAttr(inp, 'disabled'),
      hiddenAttr: hasAttr(inp, 'hidden'),
      type: (inp.attr('type') || '').toLowerCase(),
    });
  }

  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    if (!c.disabled && !c.hiddenAttr && (c.type === 'hidden' || c.type === '')) {
      return c.value;
    }
  }
  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    if (!c.disabled && !c.hiddenAttr) {
      return c.value;
    }
  }
  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    if (!c.disabled) {
      return c.value;
    }
  }
  return candidates.length > 0 ? candidates[0].value : '';
}

function extractCsrfFromHtml(body) {
  if (!body) {
    return '';
  }
  const doc = parseHTML(body);
  const forms = doc.find('form');

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (hasAttr(form, 'hidden')) {
      continue;
    }
    const action = (form.attr('action') || '').trim();
    const isLoginForm =
      action.includes('/v2/login') ||
      form.find('input[name="username"], input[name="password"], input[type="password"]').size() > 0;
    if (isLoginForm) {
      const val = findValidCsrfInput(form.find('input[name="csrf"]'));
      if (val) {
        return val;
      }
    }
  }

  for (let i = 0; i < forms.size(); i++) {
    const form = forms.eq(i);
    if (hasAttr(form, 'hidden')) {
      continue;
    }
    const val = findValidCsrfInput(form.find('input[name="csrf"]'));
    if (val) {
      return val;
    }
  }

  return findValidCsrfInput(doc.find('input[name="csrf"]'));
}

function login() {
  const jar = http.cookieJar();
  if (jar && typeof jar.clear === 'function') {
    jar.clear(BASE_URL);
  }

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    timeout: '10s',
    tags: { name: 'GET /v2/login-form' },
  });

  const formCsrf = formRes.status === 200 ? extractCsrfFromHtml(formRes.body) : '';
  const formOk = check(formRes, {
    'login form status 200': (r) => r.status === 200,
    'login form csrf present': () => formCsrf.length > 0,
  });

  if (!formOk) {
    vuState.loggedIn = false;
    vuState.csrf = '';
    return false;
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: getUsername(),
      password: PASSWORD,
      csrf: formCsrf,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      timeout: '10s',
      tags: { name: 'POST /v2/login' },
    }
  );

  let finalRes = loginRes;
  if (loginRes.status === 302) {
    const location = getHeader(loginRes, 'location');
    if (location) {
      finalRes = http.get(resolveUrl(location), {
        redirects: 0,
        timeout: '10s',
        tags: { name: 'GET /v2/login-redirect' },
      });
    }
  }

  const finalData = safeJson(finalRes);
  const initialData = finalRes === loginRes ? finalData : safeJson(loginRes);
  let sessionCsrf = '';
  if (finalData && typeof finalData.csrf === 'string' && finalData.csrf) {
    sessionCsrf = finalData.csrf;
  } else if (initialData && typeof initialData.csrf === 'string' && initialData.csrf) {
    sessionCsrf = initialData.csrf;
  }

  const loginOk = check(finalRes, {
    'login status 200': (r) => r.status === 200,
    'login csrf returned': () => sessionCsrf.length > 0,
  });

  if (!loginOk) {
    vuState.loggedIn = false;
    vuState.csrf = '';
    return false;
  }

  vuState.loggedIn = true;
  vuState.csrf = sessionCsrf;
  return true;
}

function renewSession() {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': vuState.csrf,
    },
    redirects: 0,
    timeout: '10s',
    tags: { name: 'POST /v2/session/renew' },
  });

  if (res.status === 200) {
    const data = safeJson(res);
    if (data && typeof data.csrf === 'string' && data.csrf) {
      vuState.csrf = data.csrf;
    }
    return true;
  }
  return false;
}

function sendWork() {
  return http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': vuState.csrf,
    },
    redirects: 0,
    timeout: '10s',
    tags: { name: 'POST /v2/work' },
  });
}

export default function () {
  if (!vuState.loggedIn) {
    if (!login()) {
      return;
    }
  }

  let authRecovered = false;
  let rateLimitRetries = 0;
  let res = null;
  let data = null;

  while (true) {
    res = sendWork();
    data = safeJson(res);

    if (res.status === 200 && data && data.ok === true) {
      if (typeof data.csrf === 'string' && data.csrf) {
        vuState.csrf = data.csrf;
      }
      businessFailure.add(false);
      break;
    }

    if (res.status === 429) {
      const retryHeader = getHeader(res, 'retry-after');
      const parsedRetry = parseFloat(retryHeader);
      const waitSec = Number.isFinite(parsedRetry) && parsedRetry > 0 ? parsedRetry : 1;

      if (rateLimitRetries < 4) {
        businessFailure.add(false);
        rateLimitRetries += 1;
        sleep(waitSec);
        continue;
      }
      businessFailure.add(true);
      break;
    }

    if (res.status === 401) {
      const errCode = data && typeof data.error === 'string' ? data.error : '';
      if (errCode === 'expired' || errCode === 'session') {
        businessFailure.add(false);
        if (!authRecovered) {
          authRecovered = true;
          const recovered = errCode === 'expired' ? renewSession() || login() : login();
          if (recovered) {
            continue;
          }
        }
        break;
      }
      businessFailure.add(true);
      break;
    }

    businessFailure.add(true);
    break;
  }

  check(res, {
    'work status 200': (r) => r !== null && r.status === 200,
    'work ok true': () => data !== null && data.ok === true,
  });
}

from __future__ import annotations

from html.parser import HTMLParser
import os
import time

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
ACCOUNTS = tuple(f"bench-{i}" for i in range(1, 17))
PASSWORD = "bench"

TARGET_RATE = 5.0
SLOT_INTERVAL = 1.0 / TARGET_RATE
PHASE_OFFSET = 0.1
SCORE_END_SECONDS = 35.15
DRAIN_CUTOFF_SECONDS = 37.5
DRAIN_HARD_CAP_SECONDS = 38.5
MIN_DISPATCH_GAP = 0.14

USER_COUNT = 8
SPAWN_RATE = 16
MIN_READY_USERS = 4
REQUEST_TIMEOUT = 10.0


class _ScheduleState:
    def __init__(self) -> None:
        self.user_seq = 0
        self.ready_users = 0
        self.first_ready_at: float | None = None
        self.t0: float | None = None
        self.first_success_t0: float | None = None
        self.next_slot = 0
        self.pending_slots = 0
        self.done_scheduling = False
        self.last_dispatch = -1e9


_state = _ScheduleState()


class _CsrfFormParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self._ignore_depth = 0
        self._current_form: dict | None = None
        self._candidates: list[dict] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        tag = tag.lower()
        if tag in ("script", "style", "template", "noscript"):
            self._ignore_depth += 1
            return
        if self._ignore_depth > 0:
            return

        attr_map: dict[str, str | None] = {}
        for k, v in attrs:
            if k is not None:
                attr_map[k.lower()] = v

        if tag == "form":
            action = (attr_map.get("action") or "").lower()
            style = (attr_map.get("style") or "").replace(" ", "").lower()
            is_decoy = (
                "hidden" in attr_map
                or "display:none" in style
                or "decoy" in action
                or "decoy" in (attr_map.get("id") or "").lower()
                or "decoy" in (attr_map.get("class") or "").lower()
                or "data-decoy" in attr_map
            )
            self._current_form = {
                "has_login_action": "login" in action,
                "has_auth_fields": False,
                "is_decoy": is_decoy,
            }
            return

        if tag == "input":
            name = (attr_map.get("name") or "").strip()
            if self._current_form is not None and name in ("username", "password"):
                self._current_form["has_auth_fields"] = True
            if name != "csrf":
                return
            if "disabled" in attr_map:
                return
            val = attr_map.get("value")
            if not val:
                return
            style = (attr_map.get("style") or "").replace(" ", "").lower()
            input_decoy = (
                "hidden" in attr_map
                or "display:none" in style
                or "data-decoy" in attr_map
                or "decoy" in (attr_map.get("id") or "").lower()
                or "decoy" in (attr_map.get("class") or "").lower()
            )
            self._candidates.append(
                {
                    "value": val,
                    "form": self._current_form,
                    "is_hidden_type": (attr_map.get("type") or "").lower() == "hidden",
                    "input_decoy": input_decoy,
                }
            )

    def handle_endtag(self, tag: str) -> None:
        tag = tag.lower()
        if tag in ("script", "style", "template", "noscript"):
            if self._ignore_depth > 0:
                self._ignore_depth -= 1
            return
        if tag == "form":
            self._current_form = None

    def best_csrf(self) -> str:
        if not self._candidates:
            return ""
        best_score = -(10**9)
        best_val = ""
        for cand in self._candidates:
            score = 0
            form = cand["form"]
            if form is not None:
                score += 1
                if form["has_login_action"]:
                    score += 4
                if form["has_auth_fields"]:
                    score += 2
                if form["is_decoy"]:
                    score -= 6
            if cand["is_hidden_type"]:
                score += 1
            if cand["input_decoy"]:
                score -= 6
            if score > best_score:
                best_score = score
                best_val = cand["value"]
        return best_val


def _extract_csrf_from_html(html_text: str) -> str:
    parser = _CsrfFormParser()
    parser.feed(html_text)
    parser.close()
    return parser.best_csrf()


def _safe_json(resp) -> object:
    try:
        return resp.json()
    except Exception:
        return None


def _parse_retry_after(header_val: str | None) -> float:
    if header_val is None:
        return 1.02
    try:
        val = float(header_val.strip())
        if val > 0:
            return val + 0.02
    except ValueError:
        pass
    return 1.02


def _anchor_t0() -> float | None:
    if _state.first_success_t0 is not None:
        return _state.first_success_t0
    return _state.t0


def _is_past_drain_cutoff() -> bool:
    anchor = _anchor_t0()
    if anchor is None:
        return False
    return (time.monotonic() - anchor) >= DRAIN_CUTOFF_SECONDS


def _wait_for_initial_pool() -> None:
    while _state.t0 is None:
        if _state.ready_users >= MIN_READY_USERS:
            return
        if (
            _state.first_ready_at is not None
            and (time.monotonic() - _state.first_ready_at) >= 0.5
        ):
            return
        time.sleep(0.01)


def _acquire_slot() -> tuple[int, float] | None:
    if _state.done_scheduling:
        return None
    if _state.t0 is None:
        _state.t0 = time.monotonic()

    idx = _state.next_slot
    if idx == 0:
        target = _state.t0
    else:
        target = _state.t0 + idx * SLOT_INTERVAL + PHASE_OFFSET

    anchor = _anchor_t0()
    if anchor is not None and target > anchor + SCORE_END_SECONDS:
        _state.done_scheduling = True
        return None

    _state.next_slot = idx + 1
    _state.pending_slots += 1
    return idx, target


def _wait_dispatch_gate() -> bool:
    while True:
        if _is_past_drain_cutoff():
            return False
        now = time.monotonic()
        earliest = _state.last_dispatch + MIN_DISPATCH_GAP
        if now >= earliest:
            _state.last_dispatch = now
            return True
        time.sleep(earliest - now)


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self) -> None:
        if _state.done_scheduling:
            raise StopUser()
        seq = _state.user_seq
        _state.user_seq += 1
        self.username = ACCOUNTS[seq % len(ACCOUNTS)]
        self.csrf = ""

        logged_in = False
        for attempt in range(3):
            if self._login(clear_cookies=(attempt > 0)):
                logged_in = True
                break
            time.sleep(0.2)

        if not logged_in:
            raise StopUser()

        _state.ready_users += 1
        if _state.first_ready_at is None:
            _state.first_ready_at = time.monotonic()

    def _login(self, clear_cookies: bool = False) -> bool:
        if clear_cookies:
            self.client.cookies.clear()
            self.csrf = ""

        form_csrf = ""
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            catch_response=True,
            timeout=REQUEST_TIMEOUT,
            name="/v2/login-form",
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form failed: {resp.status_code}")
                return False
            form_csrf = _extract_csrf_from_html(resp.text)
            if not form_csrf:
                resp.failure("login-form missing input[name=csrf]")
                return False
            resp.success()

        redirect_location: str | None = None
        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": PASSWORD,
                "csrf": form_csrf,
            },
            allow_redirects=False,
            catch_response=True,
            timeout=REQUEST_TIMEOUT,
            name="/v2/login",
        ) as resp:
            if resp.status_code in (301, 302, 303, 307, 308):
                redirect_location = resp.headers.get("Location")
                if not redirect_location:
                    resp.failure("login redirect missing Location")
                    return False
                resp.success()
            elif 200 <= resp.status_code < 300:
                data = _safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("login returned non-JSON body")
                    return False
                new_csrf = data.get("csrf")
                self.csrf = str(new_csrf) if new_csrf else form_csrf
                resp.success()
                return True
            else:
                resp.failure(f"login failed: {resp.status_code}")
                return False

        if not redirect_location.startswith(("http://", "https://", "/")):
            redirect_location = "/v2/" + redirect_location

        with self.client.get(
            redirect_location,
            allow_redirects=False,
            catch_response=True,
            timeout=REQUEST_TIMEOUT,
            name="/v2/login/redirect",
        ) as resp:
            if 200 <= resp.status_code < 300:
                data = _safe_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = str(data["csrf"])
                elif not self.csrf:
                    self.csrf = form_csrf
                resp.success()
                return True
            resp.failure(f"login redirect GET failed: {resp.status_code}")
            return False

    def _renew_session(self) -> bool:
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
            timeout=REQUEST_TIMEOUT,
            name="/v2/session/renew",
        ) as resp:
            if resp.status_code == 200:
                data = _safe_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = str(data["csrf"])
                resp.success()
                return True
            if resp.status_code == 401:
                resp.success()
                return False
            resp.failure(f"session renew failed: {resp.status_code}")
            return False

    def _execute_work(self) -> None:
        retries_429 = 0
        auth_retries = 0

        while True:
            headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
            req_start = time.monotonic()
            action = "done"
            retry_sleep = 0.0

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
                timeout=REQUEST_TIMEOUT,
                name="/v2/work",
            ) as resp:
                status = resp.status_code
                if status == 200:
                    data = _safe_json(resp)
                    if isinstance(data, dict) and data.get("ok") is True:
                        if data.get("csrf"):
                            self.csrf = str(data["csrf"])
                        if _state.first_success_t0 is None:
                            _state.first_success_t0 = req_start
                        resp.success()
                        return
                    resp.failure(f"work ok!=true: {resp.text[:200]}")
                    return

                if status == 429:
                    if retries_429 < 4:
                        retry_sleep = _parse_retry_after(
                            resp.headers.get("Retry-After")
                        )
                        resp.success()
                        action = "retry_429"
                    else:
                        resp.failure("work 429 retries exhausted")
                        return

                elif status == 401:
                    data = _safe_json(resp)
                    err = data.get("error") if isinstance(data, dict) else None
                    if err == "expired" and auth_retries < 1:
                        resp.success()
                        action = "renew"
                    elif err == "session" and auth_retries < 1:
                        resp.success()
                        action = "relogin"
                    else:
                        resp.failure(f"work 401 error={err or 'unknown'}")
                        return

                else:
                    resp.failure(f"work unexpected status {status}: {resp.text[:200]}")
                    return

            if action == "retry_429":
                retries_429 += 1
                if retry_sleep > 0:
                    time.sleep(retry_sleep)
                if _is_past_drain_cutoff():
                    return
                if not _wait_dispatch_gate():
                    return
                continue

            if action == "renew":
                auth_retries += 1
                if not self._renew_session():
                    if not self._login(clear_cookies=True):
                        return
                if _is_past_drain_cutoff():
                    return
                if not _wait_dispatch_gate():
                    return
                continue

            if action == "relogin":
                auth_retries += 1
                if not self._login(clear_cookies=True):
                    return
                if _is_past_drain_cutoff():
                    return
                if not _wait_dispatch_gate():
                    return
                continue

            return

    @task
    def work(self) -> None:
        if _state.t0 is None:
            _wait_for_initial_pool()

        slot = _acquire_slot()
        if slot is None:
            raise StopUser()

        try:
            _, target_time = slot
            delay = target_time - time.monotonic()
            if delay > 0:
                time.sleep(delay)
            if not _wait_dispatch_gate():
                raise StopUser()
            self._execute_work()
        finally:
            _state.pending_slots -= 1


class WorkLoadShape(LoadTestShape):
    def tick(self) -> tuple[int, float] | None:
        run_time = self.get_run_time()
        anchor = _anchor_t0()
        if anchor is None:
            if run_time >= 15.0:
                return None
            return (USER_COUNT, SPAWN_RATE)

        elapsed = time.monotonic() - anchor
        if elapsed >= DRAIN_HARD_CAP_SECONDS:
            return None
        if (
            _state.done_scheduling
            and _state.pending_slots <= 0
            and elapsed >= 35.2
        ):
            return None
        return (USER_COUNT, SPAWN_RATE)

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class ModelSimulation extends Simulation {

  private static final int VU_COUNT = 16;
  private static final long TARGET_INTERVAL_NS = 125_000_000L;
  private static final long RUN_DURATION_AFTER_T0_NS = 35_500_000_000L;
  private static final long HARD_FALLBACK_DURATION_NS = 41_000_000_000L;
  private static final int BURST_WINDOW_CAP = 11;
  private static final long ONE_SECOND_NS = 1_000_000_000L;
  private static final long BURST_MARGIN_NS = 10_000_000L;

  private static final Object PACER_LOCK = new Object();
  private static final long LAUNCH_NANOS = System.nanoTime();
  private static long t0Nanos = 0L;
  private static long nextSlotNanos = 0L;
  private static final long[] DISPATCH_RING = new long[BURST_WINDOW_CAP];
  private static int dispatchRingHead = 0;
  private static int dispatchRingCount = 0;

  private static long claimNextSlotWaitMs() {
    synchronized (PACER_LOCK) {
      long now = System.nanoTime();
      long stopNanos = (t0Nanos != 0L)
          ? (t0Nanos + RUN_DURATION_AFTER_T0_NS)
          : (LAUNCH_NANOS + HARD_FALLBACK_DURATION_NS);
      long candidate = (nextSlotNanos == 0L) ? now : Math.max(nextSlotNanos, now);
      if (candidate >= stopNanos) {
        return -1L;
      }
      nextSlotNanos = candidate + TARGET_INTERVAL_NS;
      long waitNs = candidate - now;
      return waitNs > 0L ? (waitNs + 500_000L) / 1_000_000L : 0L;
    }
  }

  private static long reserveDispatchWaitMs() {
    synchronized (PACER_LOCK) {
      long now = System.nanoTime();
      long scheduled = now;
      if (dispatchRingCount == BURST_WINDOW_CAP) {
        long oldest = DISPATCH_RING[dispatchRingHead];
        long earliestAllowed = oldest + ONE_SECOND_NS + BURST_MARGIN_NS;
        if (earliestAllowed > scheduled) {
          scheduled = earliestAllowed;
        }
      }
      if (dispatchRingCount > 0) {
        long lastScheduled = DISPATCH_RING[(dispatchRingHead + BURST_WINDOW_CAP - 1) % BURST_WINDOW_CAP];
        if (lastScheduled > scheduled) {
          scheduled = lastScheduled;
        }
      }
      DISPATCH_RING[dispatchRingHead] = scheduled;
      dispatchRingHead = (dispatchRingHead + 1) % BURST_WINDOW_CAP;
      if (dispatchRingCount < BURST_WINDOW_CAP) {
        dispatchRingCount++;
      }
      long waitNs = scheduled - now;
      return waitNs > 0L ? (waitNs + 999_999L) / 1_000_000L : 0L;
    }
  }

  private static void recordFirstSuccess(long requestStartNanos) {
    synchronized (PACER_LOCK) {
      if (t0Nanos == 0L) {
        t0Nanos = requestStartNanos;
      }
    }
  }

  private static long parseRetryAfterMs(String headerVal) {
    if (headerVal == null || headerVal.isBlank()) {
      return 1020L;
    }
    try {
      double secs = Double.parseDouble(headerVal.trim());
      long ms = (long) Math.ceil(secs * 1000.0) + 20L;
      if (ms < 1020L) {
        return 1020L;
      }
      if (ms > 5000L) {
        return 5000L;
      }
      return ms;
    } catch (NumberFormatException e) {
      return 1020L;
    }
  }

  private static String firstNonBlank(String... values) {
    for (String v : values) {
      if (v != null && !v.isBlank()) {
        return v;
      }
    }
    return null;
  }

  private static boolean hasNonBlank(Session session, String key) {
    String val = session.getString(key);
    return val != null && !val.isBlank();
  }

  private static Session updateCsrfIfPresent(Session session, String key) {
    String fresh = session.getString(key);
    Session cleaned = session.removeAll(key);
    if (fresh != null && !fresh.isBlank()) {
      return cleaned.set("csrf", fresh);
    }
    return cleaned;
  }

  private static String jsonEscape(String s) {
    if (s == null) {
      return "";
    }
    StringBuilder sb = new StringBuilder(s.length() + 8);
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      switch (c) {
        case '"':
          sb.append("\\\"");
          break;
        case '\\':
          sb.append("\\\\");
          break;
        case '\n':
          sb.append("\\n");
          break;
        case '\r':
          sb.append("\\r");
          break;
        case '\t':
          sb.append("\\t");
          break;
        default:
          sb.append(c);
      }
    }
    return sb.toString();
  }

  private static String buildLoginJson(String username, String password, String csrf) {
    return "{\"username\":\"" + jsonEscape(username)
        + "\",\"password\":\"" + jsonEscape(password)
        + "\",\"csrf\":\"" + jsonEscape(csrf) + "\"}";
  }

  private static String resolveBaseUrl() {
    String envBaseUrl = System.getenv("BASE_URL");
    String url = (envBaseUrl == null || envBaseUrl.isBlank())
        ? "http://127.0.0.1:8000"
        : envBaseUrl.trim();
    if (url.endsWith("/")) {
      url = url.substring(0, url.length() - 1);
    }
    return url;
  }

  private static FeederBuilder<Object> buildUserFeeder() {
    List<Map<String, Object>> users = new ArrayList<>(VU_COUNT);
    for (int i = 1; i <= VU_COUNT; i++) {
      users.add(Map.<String, Object>of("username", "bench-" + i));
    }
    return listFeeder(users).circular();
  }

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(resolveBaseUrl())
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
      .disableFollowRedirect();

  private final ChainBuilder loginChain = exec(session ->
      session.removeAll(
          "hiddenFormCsrf", "formCsrf", "hiddenCsrf", "anyCsrf",
          "loginBody", "loginStatus", "loginLocation")
  )
      .exec(
          http("login-form")
              .get("/v2/login-form")
              .check(
                  status().is(200),
                  css("form[action*=login] input[type=hidden][name=csrf]", "value")
                      .optional().saveAs("hiddenFormCsrf"),
                  css("form[action*=login] input[name=csrf]", "value")
                      .optional().saveAs("formCsrf"),
                  css("input[type=hidden][name=csrf]", "value")
                      .optional().saveAs("hiddenCsrf"),
                  css("input[name=csrf]", "value").find().saveAs("anyCsrf")
              )
      )
      .exec(session -> {
        String token = firstNonBlank(
            session.getString("hiddenFormCsrf"),
            session.getString("formCsrf"),
            session.getString("hiddenCsrf"),
            session.getString("anyCsrf")
        );
        String username = session.getString("username");
        String body = buildLoginJson(username, "bench", token == null ? "" : token);
        return session
            .set("loginBody", body)
            .removeAll("hiddenFormCsrf", "formCsrf", "hiddenCsrf", "anyCsrf");
      })
      .exec(
          http("login")
              .post("/v2/login")
              .header("Content-Type", "application/json")
              .body(StringBody("#{loginBody}"))
              .check(status().in(200, 302).saveAs("loginStatus"))
              .checkIf((response, session) -> response.status().code() == 200)
              .then(jmesPath("csrf").saveAs("csrf"))
              .checkIf((response, session) -> response.status().code() == 302)
              .then(header("Location").saveAs("loginLocation"))
      )
      .doIf(session ->
          session.contains("loginStatus")
              && session.getInt("loginStatus") == 302
              && hasNonBlank(session, "loginLocation"))
      .then(
          exec(
              http("login-redirect")
                  .get("#{loginLocation}")
                  .check(
                      status().is(200),
                      jmesPath("csrf").saveAs("csrf")
                  )
          )
      )
      .exec(session -> session.removeAll("loginBody", "loginStatus", "loginLocation"));

  private final ChainBuilder workOperationChain = exec(session ->
      session
          .set("workDone", false)
          .set("retries429", 0)
          .set("recovered401", 0)
          .set("nextAction", "none")
          .set("retryWaitMs", 0L)
          .removeAll("workStatus", "workError", "retryAfter", "newCsrf", "guardWaitMs", "attemptStartNanos")
  )
      .asLongAs(session -> !session.getBoolean("workDone"))
      .on(
          exec(session -> {
            long guardWaitMs = reserveDispatchWaitMs();
            return session
                .set("guardWaitMs", guardWaitMs)
                .set("nextAction", "none")
                .removeAll("workStatus", "workError", "retryAfter", "newCsrf");
          })
              .doIf(session -> session.getLong("guardWaitMs") > 0L)
              .then(pause(session -> Duration.ofMillis(session.getLong("guardWaitMs"))))
              .exec(session -> session.set("attemptStartNanos", System.nanoTime()))
              .exec(
                  http("work")
                      .post("/v2/work")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody("{}"))
                      .check(status().in(200, 401, 429).saveAs("workStatus"))
