        long oldest = DISPATCH_RING[dispatchRingHead];
        long earliestAllowed = oldest + ONE_SECOND_NS + BURST_MARGIN_NS;
        if (earliestAllowed > scheduled) {
          scheduled = earliestAllowed;
        }
      }
