  }

  private static String resolveBaseUrl() {
    String envBaseUrl = System.getenv("BASE_URL");
    String url = (envBaseUrl == null || envBaseUrl.isBlank())
        ? "http://127.0.0.1:8000"
        : envBaseUrl.trim();
    if (url.endsWith("/")) {
      url = url.substring(0, url.length() - 1);
    }
    return url;
  }

  private static FeederBuilder<Object> buildUserFeeder() {
    List<Map<String, Object>> users = new ArrayList<>(VU_COUNT);
    for (int i = 1; i <= VU_COUNT; i++) {
      users.add(Map.<String, Object>of("username", "bench-" + i));
    }
    return listFeeder(users).circular();
  }

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(resolveBaseUrl())
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
      .disableFollowRedirect();

  private final ChainBuilder loginChain = exec(session ->
      session.removeAll(
          "exactHiddenFormCsrf", "exactFormCsrf",
          "hiddenFormCsrf", "formCsrf", "hiddenCsrf", "anyCsrf",
          "loginBody", "loginStatus", "loginLocation")
  )
      .exec(
          http("login-form")
              .get("/v2/login-form")
              .check(
                  status().is(200),
                  css("form[action='/v2/login'] input[type=hidden][name=csrf]", "value")
                      .optional().saveAs("exactHiddenFormCsrf"),
                  css("form[action='/v2/login'] input[name=csrf]", "value")
                      .optional().saveAs("exactFormCsrf"),
                  css("form[action*=login] input[type=hidden][name=csrf]", "value")
                      .optional().saveAs("hiddenFormCsrf"),
                  css("form[action*=login] input[name=csrf]", "value")
                      .optional().saveAs("formCsrf"),
                  css("input[type=hidden][name=csrf]", "value")
                      .optional().saveAs("hiddenCsrf"),
                  css("input[name=csrf]", "value").find().saveAs("anyCsrf")
              )
      )
      .exec(session -> {
        String token = firstNonBlank(
            session.getString("exactHiddenFormCsrf"),
            session.getString("exactFormCsrf"),
            session.getString("hiddenFormCsrf"),
            session.getString("formCsrf"),
            session.getString("hiddenCsrf"),
            session.getString("anyCsrf")
        );
        String username = session.getString("username");
        String body = buildLoginJson(username, "bench", token == null ? "" : token);
        return session
            .set("loginBody", body)
            .removeAll(
                "exactHiddenFormCsrf", "exactFormCsrf",
                "hiddenFormCsrf", "formCsrf", "hiddenCsrf", "anyCsrf");
      })
      .exec(
          http("login")
              .post("/v2/login")
              .header("Content-Type", "application/json")
              .body(StringBody("#{loginBody}"))
              .check(status().in(200, 302).saveAs("loginStatus"))
              .checkIf((response, session) -> response.status().code() == 200)
              .then(jmesPath("csrf").saveAs("csrf"))
              .checkIf((response, session) -> response.status().code() == 302)
              .then(header("Location").saveAs("loginLocation"))
      )
      .doIf(session ->
          session.contains("loginStatus")
              && session.getInt("loginStatus") == 302
              && hasNonBlank(session, "loginLocation"))
      .then(
          exec(
              http("login-redirect")
                  .get("#{loginLocation}")
                  .check(
                      status().is(200),
                      jmesPath("csrf").saveAs("csrf")
                  )
          )
      )
      .exec(session -> session.removeAll("loginBody", "loginStatus", "loginLocation"));

  private final ChainBuilder workOperationChain = exec(session ->
      session
          .set("workDone", false)
          .set("retries429", 0)
          .set("recovered401", 0)
          .set("nextAction", "none")
          .set("retryWaitMs", 0L)
          .removeAll("workStatus", "workError", "retryAfter", "newCsrf", "guardWaitMs", "attemptStartNanos")
  )
      .asLongAs(session -> !session.getBoolean("workDone"))
      .on(
          exec(session -> {
            long guardWaitMs = reserveDispatchWaitMs();
            return session
                .set("guardWaitMs", guardWaitMs)
                .set("nextAction", "none")
                .removeAll("workStatus", "workError", "retryAfter", "newCsrf");
          })
              .doIf(session -> session.getLong("guardWaitMs") > 0L)
              .then(pause(session -> Duration.ofMillis(session.getLong("guardWaitMs"))))
              .exec(session -> session.set("attemptStartNanos", System.nanoTime()))
              .exec(
                  http("work")
                      .post("/v2/work")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "#{csrf}")
                      .body(StringBody("{}"))
                      .check(status().in(200, 401, 429).saveAs("workStatus"))
                      .checkIf((response, session) -> response.status().code() == 200)
                      .then(
                          jmesPath("ok").ofBoolean().is(true),
                          jmesPath("csrf").optional().saveAs("newCsrf")
                      )
                      .checkIf((response, session) -> response.status().code() == 401)
                      .then(
                          jmesPath("error").in("expired", "session").saveAs("workError")
                      )
                      .checkIf((response, session) -> response.status().code() == 429)
                      .then(
                          header("Retry-After").optional().saveAs("retryAfter")
                      )
              )
              .exec(session -> {
                if (session.isFailed() || !session.contains("workStatus")) {
                  return session
                      .set("workDone", true)
                      .set("nextAction", "none")
                      .markAsSucceeded();
                }
                int st = session.getInt("workStatus");
                if (st == 200) {
                  recordFirstSuccess(session.getLong("attemptStartNanos"));
                  Session updated = updateCsrfIfPresent(session, "newCsrf");
                  return updated
                      .set("workDone", true)
                      .set("nextAction", "none");
                }
                if (st == 429) {
                  int retries = session.getInt("retries429");
                  if (retries < 4) {
                    long waitMs = parseRetryAfterMs(session.getString("retryAfter"));
                    return session
                        .set("retries429", retries + 1)
                        .set("retryWaitMs", waitMs)
                        .set("nextAction", "retry429");
                  }
                  return session
                      .set("workDone", true)
                      .set("nextAction", "none");
                }
                if (st == 401) {
                  int recovered = session.getInt("recovered401");
                  String err = session.getString("workError");
                  if (recovered < 1) {
                    if ("expired".equals(err)) {
                      return session
                          .set("recovered401", recovered + 1)
                          .set("nextAction", "renew");
                    }
                    if ("session".equals(err)) {
                      return session
                          .set("recovered401", recovered + 1)
                          .set("nextAction", "relogin");
                    }
                  }
                  return session
                      .set("workDone", true)
                      .set("nextAction", "none");
                }
                return session
                    .set("workDone", true)
                    .set("nextAction", "none");
              })
              .doIf(session -> "retry429".equals(session.getString("nextAction")))
              .then(pause(session -> Duration.ofMillis(session.getLong("retryWaitMs"))))
              .doIf(session -> "renew".equals(session.getString("nextAction")))
              .then(
                  exec(session -> session.removeAll("renewStatus", "newCsrf", "needRelogin"))
                      .exec(
                          http("session-renew")
                              .post("/v2/session/renew")
                              .header("Content-Type", "application/json")
                              .header("X-CSRF-Token", "#{csrf}")
                              .body(StringBody("{}"))
                              .check(status().in(200, 401).saveAs("renewStatus"))
                              .checkIf((response, session) -> response.status().code() == 200)
                              .then(jmesPath("csrf").optional().saveAs("newCsrf"))
                      )
                      .exec(session -> {
                        boolean ok = !session.isFailed()
                            && session.contains("renewStatus")
                            && session.getInt("renewStatus") == 200;
                        Session s = ok
                            ? updateCsrfIfPresent(session, "newCsrf")
                            : session.markAsSucceeded();
                        return s.set("needRelogin", !ok).removeAll("renewStatus", "newCsrf");
                      })
                      .doIf(session -> session.getBoolean("needRelogin"))
                      .then(loginChain)
                      .exec(session -> session.isFailed()
                          ? session.set("workDone", true).markAsSucceeded()
                          : session)
              )
              .doIf(session -> "relogin".equals(session.getString("nextAction")))
              .then(
                  exec(loginChain)
                      .exec(session -> session.isFailed()
                          ? session.set("workDone", true).markAsSucceeded()
                          : session)
              )
      );

  private final ScenarioBuilder workScenario = scenario("work-pool")
      .feed(buildUserFeeder())
      .exec(loginChain)
      .doIf(session -> session.isFailed() || !hasNonBlank(session, "csrf"))
      .then(
          exec(Session::markAsSucceeded)
              .pause(Duration.ofMillis(100))
              .exec(loginChain)
      )
      .exec(session -> session.set("keepRunning", hasNonBlank(session, "csrf")))
      .asLongAs(session -> session.getBoolean("keepRunning"))
      .on(
          exec(session -> {
            long waitMs = claimNextSlotWaitMs();
            if (waitMs < 0L) {
              return session.set("keepRunning", false).set("slotWaitMs", 0L);
            }
            return session.set("keepRunning", true).set("slotWaitMs", waitMs);
          })
              .doIf(session -> session.getBoolean("keepRunning"))
              .then(
                  doIf(session -> session.getLong("slotWaitMs") > 0L)
                      .then(pause(session -> Duration.ofMillis(session.getLong("slotWaitMs"))))
                      .exec(workOperationChain)
              )
      );

  {
    setUp(
        workScenario.injectOpen(
            rampUsers(VU_COUNT).during(Duration.ofMillis(400))
        )
    )
        .protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(50));
  }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const ACCOUNTS = [
  'bench-1',
  'bench-2',
  'bench-3',
  'bench-4',
  'bench-5',
  'bench-6',
  'bench-7',
  'bench-8',
  'bench-9',
  'bench-10',
  'bench-11',
  'bench-12',
  'bench-13',
  'bench-14',
  'bench-15',
  'bench-16',
  'bench',
];

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 8,
      timeUnit: '1s',
      duration: '36500ms',
      preAllocatedVUs: 16,
      maxVUs: 32,
      gracefulStop: '3s',
    },
  },
  noConnectionReuse: false,
  userAgent: 'k6-work-bench/1.0',
};

const vuState = {
  username: null,
  csrf: null,
  authenticated: false,
};

function getHeader(res, name) {
  if (!res || !res.headers) return undefined;
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) {
      const val = res.headers[keys[i]];
      return Array.isArray(val) ? val[0] : val;
    }
  }
  return undefined;
}

function resolveUrl(loc) {
  if (/^https?:\/\//i.test(loc)) {
    return loc;
  }
  if (loc.startsWith('/')) {
    return `${BASE_URL}${loc}`;
  }
  return `${BASE_URL}/${loc}`;
}

function safeJson(res) {
  if (!res || typeof res.body !== 'string' || res.body.length === 0) {
    return null;
  }
  try {
    return JSON.parse(res.body);
  } catch (_) {
    return null;
  }
}

function extractCsrf(html) {
  if (!html || typeof html !== 'string') return null;
  const doc = parseHTML(html);

  const formInfo = {};
  const forms = doc.find('form');
  for (let i = 0; i < forms.size(); i++) {
    const f = forms.eq(i);
    const id = f.attr('id');
    if (id) {
      const action = (f.attr('action') || '').toLowerCase();
      const hasCreds =
        f.find('input[name="username"], input[name="password"], input[type="password"]').size() > 0;
      const isDecoyAction =
        action.includes('decoy') || action.includes('fake') || action.includes('dummy');
      formInfo[id] = {
        isLoginAction: action.includes('/v2/login') || action.includes('/login'),
        hasCreds,
        isDecoyAction,
      };
    }
  }

  const inputs = doc.find('input[name="csrf"]');
  let bestVal = null;
  let bestScore = -1e9;

  for (let i = 0; i < inputs.size(); i++) {
    const el = inputs.eq(i);
    const val = el.attr('value');
    if (!val || !val.trim()) continue;
    if (el.attr('disabled') !== undefined) continue;
    if (el.parents('template, noscript').size() > 0) continue;

    let score = 0;

    const typeAttr = (el.attr('type') || 'hidden').toLowerCase();
    if (typeAttr === 'hidden') score += 5;

    const elId = (el.attr('id') || '').toLowerCase();
    const elCls = (el.attr('class') || '').toLowerCase();
    if (
      el.attr('data-decoy') !== undefined ||
      el.attr('data-fake') !== undefined ||
      elId.includes('decoy') ||
      elId.includes('fake') ||
      elId.includes('dummy') ||
      elCls.includes('decoy') ||
      elCls.includes('fake') ||
      elCls.includes('dummy')
    ) {
      score -= 200;
    }
    if (el.attr('hidden') !== undefined || el.attr('aria-hidden') === 'true') {
      score -= 80;
    }

    const parentForms = el.parents('form');
    if (parentForms.size() > 0) {
      const f = parentForms.eq(0);
      const action = (f.attr('action') || '').toLowerCase();
      const hasCreds =
        f.find('input[name="username"], input[name="password"], input[type="password"]').size() > 0;
      if (action.includes('/v2/login') || action.includes('/login')) {
        score += 100;
      }
      if (hasCreds) {
        score += 50;
      }
      if (
        action.includes('decoy') ||
        action.includes('fake') ||
        action.includes('dummy') ||
        action.includes('search')
      ) {
        score -= 150;
      } else {
        score += 20;
      }
    } else {
      const linkedFormId = el.attr('form');
      if (linkedFormId && formInfo[linkedFormId]) {
        const info = formInfo[linkedFormId];
        if (info.isLoginAction) score += 90;
        if (info.hasCreds) score += 50;
        if (info.isDecoyAction) score -= 150;
        else score += 15;
      }
    }

    const ancestors = el.parents('*');
    for (let j = 0; j < ancestors.size(); j++) {
      const p = ancestors.eq(j);
      if (p.attr('data-decoy') !== undefined || p.attr('data-fake') !== undefined) {
        score -= 200;
      }
      const pCls = (p.attr('class') || '').toLowerCase();
      const pId = (p.attr('id') || '').toLowerCase();
      if (
        pCls.includes('decoy') ||
        pCls.includes('fake') ||
        pCls.includes('dummy') ||
        pId.includes('decoy') ||
        pId.includes('fake') ||
        pId.includes('dummy')
      ) {
        score -= 200;
      }
      if (p.attr('hidden') !== undefined || p.attr('aria-hidden') === 'true') {
        score -= 80;
      }
      const style = (p.attr('style') || '').toLowerCase().replace(/\s+/g, '');
      if (style.includes('display:none') || style.includes('visibility:hidden')) {
        score -= 40;
      }
    }

    if (score > bestScore) {
      bestScore = score;
      bestVal = val.trim();
    }
  }

  return bestVal;
}

function login() {
  const jar = http.cookieJar();
  if (jar && typeof jar.clear === 'function') {
    jar.clear(BASE_URL);
    jar.clear(`${BASE_URL}/v2/`);
  }

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    timeout: '5s',
  });
  if (!formRes || formRes.status < 200 || formRes.status >= 300) {
    vuState.authenticated = false;
    return false;
  }

  const formCsrf = extractCsrf(formRes.body);
  if (!formCsrf) {
    vuState.authenticated = false;
    return false;
  }

  let loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: vuState.username,
      password: PASSWORD,
      csrf: formCsrf,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      timeout: '5s',
    }
  );

  if (
    loginRes &&
    (loginRes.status === 301 ||
      loginRes.status === 302 ||
      loginRes.status === 303 ||
      loginRes.status === 307 ||
      loginRes.status === 308)
  ) {
    const loc = getHeader(loginRes, 'location');
    if (!loc) {
      vuState.authenticated = false;
      return false;
    }
    loginRes = http.get(resolveUrl(loc), {
      redirects: 0,
      timeout: '5s',
      tags: { name: 'GET /v2/login-redirect' },
    });
  }

  if (!loginRes || loginRes.status < 200 || loginRes.status >= 300) {
    vuState.authenticated = false;
    return false;
  }

  const data = safeJson(loginRes);
  vuState.csrf =
    data && typeof data.csrf === 'string' && data.csrf.length > 0 ? data.csrf : formCsrf;
  vuState.authenticated = true;
  return true;
}

function renewSession() {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': vuState.csrf || '',
    },
    redirects: 0,
    timeout: '5s',
  });

  if (!res || res.status < 200 || res.status >= 300) {
    return false;
  }

  const data = safeJson(res);
  if (data && typeof data.csrf === 'string' && data.csrf.length > 0) {
    vuState.csrf = data.csrf;
  }
  vuState.authenticated = true;
  return true;
}

export default function () {
  if (!vuState.username) {
    vuState.username = ACCOUNTS[(__VU - 1) % ACCOUNTS.length];
  }

  if (!vuState.authenticated || !vuState.csrf) {
    const okLogin = login();
    if (!okLogin) {
      check(null, {
        'work status is 200': () => false,
        'work ok is true': () => false,
      });
      return;
    }
  }

  let authRecovered = false;
  let retries429 = 0;
  let finalRes = null;
  let finalOk = false;

  while (true) {
    const res = http.post(`${BASE_URL}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': vuState.csrf,
      },
      redirects: 0,
      timeout: '5s',
    });

    const body = safeJson(res);
    finalRes = res;

    if (res.status === 200 && body && body.ok === true) {
      if (typeof body.csrf === 'string' && body.csrf.length > 0) {
        vuState.csrf = body.csrf;
      }
      businessFailure.add(false);
      finalOk = true;
      break;
    }

    if (res.status === 429 && retries429 < 4) {
      businessFailure.add(false);
      retries429 += 1;
      const ra = parseFloat(getHeader(res, 'retry-after'));
      const waitSec = Number.isFinite(ra) && ra > 0 ? ra : 1;
      sleep(waitSec + 0.02 + Math.random() * 0.06);
      continue;
    }

    if (
      res.status === 401 &&
      !authRecovered &&
      body &&
      (body.error === 'expired' || body.error === 'session')
    ) {
      businessFailure.add(false);
      authRecovered = true;
      let recovered = false;
      if (body.error === 'expired') {
        recovered = renewSession();
        if (!recovered) {
          recovered = login();
        }
      } else {
        recovered = login();
      }
      if (recovered) {
        continue;
      }
      finalOk = false;
      break;
    }

    businessFailure.add(true);
    finalOk = false;
    break;
  }

  check(finalRes, {
    'work status is 200': (r) => r !== null && r.status === 200,
    'work ok is true': () => finalOk === true,
  });
}
